  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une SARL, le gérant :', '[{"id": "a", "label": "N''a pas systématiquement la qualité de commerçant", "is_correct": false}, {"id": "b", "label": "Doit obligatoirement être associé", "is_correct": false}, {"id": "c", "label": "Ne peut être salarié qu''à la condition d''être actionnaire majoritaire", "is_correct": false}, {"id": "d", "label": "Devient automatiquement commerçant s''il ne l''était pas déjà", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:1', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le président d''une société par actions simplifiée (S.A.S.) :', '[{"id": "a", "label": "Est toujours une personne morale", "is_correct": false}, {"id": "b", "label": "Est obligatoirement un associé de la S.A.S", "is_correct": false}, {"id": "c", "label": "Est toujours désigné par un conseil d''administration", "is_correct": false}, {"id": "d", "label": "Peut-être une personne physique ou morale", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:2', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un chef d''entreprise désire avoir le statut de salarié, il doit :', '[{"id": "a", "label": "S''inscrire au registre du commerce et des sociétés en nom personnel", "is_correct": false}, {"id": "b", "label": "Être le gérant associé d''une EURL (entreprise unipersonnelle à responsabilité limitée)", "is_correct": false}, {"id": "c", "label": "Être le gérant unique d''une SARL (société à responsabilité limitée) dont il aura la majorité du capital", "is_correct": false}, {"id": "d", "label": "Être le gérant unique d''une SARL dont il aura la minorité du capital", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:3', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une SARL (société à responsabilité limitée), le gérant est élu à la majorité des associés :', '[{"id": "a", "label": "À l''unanimité", "is_correct": false}, {"id": "b", "label": "Représentant un quart des parts sociales", "is_correct": false}, {"id": "c", "label": "Représentant plus des trois quarts des parts sociales", "is_correct": false}, {"id": "d", "label": "Représentant plus de la moitié des parts sociales", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:4', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une EURL (société unipersonnelle à responsabilité limitée), le gérant associé unique est responsable : Page 3 sur 204 :', '[{"id": "a", "label": "De la totalité des dettes sociales", "is_correct": false}, {"id": "b", "label": "Des dettes sociales sur ses biens personnels", "is_correct": false}, {"id": "c", "label": "Des dettes sociales à concurrence de ses apports", "is_correct": false}, {"id": "d", "label": "Des dettes sociales à concurrence de son chiffre d''affaires annuel", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:5', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une SARL (société à responsabilité limitée), les associés doivent répondre des dettes de la société :', '[{"id": "a", "label": "Dans leur totalité", "is_correct": false}, {"id": "b", "label": "Proportionnellement à leurs apports", "is_correct": false}, {"id": "c", "label": "Sauf en cas de liquidation judiciaire", "is_correct": false}, {"id": "d", "label": "Dans la limite de leurs apports", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:6', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La demande d''ouverture de la procédure de redressement judiciaire est de la compétence :', '[{"id": "a", "label": "Exclusive du chef d''entreprise", "is_correct": false}, {"id": "b", "label": "Exclusive du chef d''entreprise et des créanciers", "is_correct": false}, {"id": "c", "label": "Exclusive du président du tribunal de commerce et des créanciers de l''entreprise", "is_correct": false}, {"id": "d", "label": "Indifféremment du chef d''entreprise, des créanciers, des salariés, du président du tribunal de commerce, du procureur de la République", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:7', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une S.A.R.L (société à responsabilité limitée), le gérant :', '[{"id": "a", "label": "N''a pas obligatoirement la qualité de commerçant", "is_correct": false}, {"id": "b", "label": "Doit obligatoirement être associé", "is_correct": false}, {"id": "c", "label": "Ne peut être salarié qu''à la condition d''être actionnaire majoritaire", "is_correct": false}, {"id": "d", "label": "Devient automatiquement commerçant", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:8', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La cessation de paiement d''une société commerciale est :', '[{"id": "a", "label": "L''impossibilité de faire face au passif exigible avec son actif disponible", "is_correct": false}, {"id": "b", "label": "La perte de la moitié de son capital social", "is_correct": false}, {"id": "c", "label": "Une infraction imputable aux dirigeants de la société", "is_correct": false}, {"id": "d", "label": "La tenue d''une comptabilité irrégulière au regard des dispositions légales ; Page 4 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:9', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''entrepreneur individuel est imposé au titre :', '[{"id": "a", "label": "Des prélèvements effectués pour ses besoins personnels", "is_correct": false}, {"id": "b", "label": "De ses revenus (bénéfices industriels et commerciaux)", "is_correct": false}, {"id": "c", "label": "De l''impôt sur les sociétés", "is_correct": false}, {"id": "d", "label": "Des valeurs mobilières de placement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:10', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un de vos clients, commerçant, domicilié à Brest, vous fait des difficultés pour le règlement d''une facture de transport. Entreprise lilloise, vous optez pour la procédure d''injonction de payer en adressant votre requête :', '[{"id": "a", "label": "Au tribunal de commerce de Lille", "is_correct": false}, {"id": "b", "label": "Au tribunal d''instance de Lille", "is_correct": false}, {"id": "c", "label": "Au tribunal de commerce de Brest", "is_correct": false}, {"id": "d", "label": "Au tribunal d''instance de Brest", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:11', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Possède la personnalité morale :', '[{"id": "a", "label": "La société en participation", "is_correct": false}, {"id": "b", "label": "La société de fait", "is_correct": false}, {"id": "c", "label": "L''entreprise personnelle", "is_correct": false}, {"id": "d", "label": "La société par actions simplifiée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:12', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les juges du tribunal de commerce, appelés juges consulaires, sont :', '[{"id": "a", "label": "Des magistrats traditionnels", "is_correct": false}, {"id": "b", "label": "Des commerçants élus par leurs pairs", "is_correct": false}, {"id": "c", "label": "Des commerçants désignés par la chambre de commerce", "is_correct": false}, {"id": "d", "label": "Des commerçants désignés par les organisations professionnelles", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:13', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le crédit documentaire peut être annulé à la demande :', '[{"id": "a", "label": "Du vendeur", "is_correct": false}, {"id": "b", "label": "Des banquiers et de l''acheteur", "is_correct": false}, {"id": "c", "label": "De l''acheteur ; Page 5 sur 204", "is_correct": false}, {"id": "d", "label": "Du vendeur, de l''acheteur ou des banquiers", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:14', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une SARL (société à responsabilité limitée) familiale :', '[{"id": "a", "label": "Seuls les parents et les enfants sont associés", "is_correct": false}, {"id": "b", "label": "C''est le chef de famille qui est gérant", "is_correct": false}, {"id": "c", "label": "Il n''y a pas d''assemblée générale", "is_correct": false}, {"id": "d", "label": "La SARL peut opter pour l''impôt sur les sociétés ou l''impôt sur le revenu", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:15', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La faillite personnelle est :', '[{"id": "a", "label": "Une condamnation d''une personne physique", "is_correct": false}, {"id": "b", "label": "La mise en liquidation de l''entreprise personnelle", "is_correct": false}, {"id": "c", "label": "Le dépôt de bilan de l''entreprise personnelle", "is_correct": false}, {"id": "d", "label": "L''impossibilité de rembourser les créanciers après liquidation", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:16', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La lettre de change est un effet de commerce :', '[{"id": "a", "label": "Dont le paiement est garanti à la date d''échéance figurant sur ce document", "is_correct": false}, {"id": "b", "label": "Qui est rédigé par le tiré et adressé au tireur pour acceptation", "is_correct": false}, {"id": "c", "label": "Qui est toujours à échéance indéterminée et escomptable", "is_correct": false}, {"id": "d", "label": "Qui est rédigé par le tireur et adressé au tiré pour acceptation", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:17', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Parmi les quatre mentions figurant ci-dessous, une mention doit figurer obligatoirement dans les statuts d''une société :', '[{"id": "a", "label": "L''objet social de la société", "is_correct": false}, {"id": "b", "label": "Le régime fiscal adopté par la société", "is_correct": false}, {"id": "c", "label": "Le nombre de salariés", "is_correct": false}, {"id": "d", "label": "Le nom du ou des gérants de la société", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:18', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les associés d''une SAS (société par actions simplifiée) ont signé leurs statuts le 13 janvier. L''inscription au RCS (registre du commerce et des sociétés) a été effectuée le 25 janvier. La publicité de la constitution de la société est parue dans un journal d''annonces légales le 30 janvier. L''activité de la société a débuté le 4 mars. A quelle date la société a-t-elle acquis la personnalité morale ? Page 6 sur 204 :', '[{"id": "a", "label": "Le 13 janvier", "is_correct": false}, {"id": "b", "label": "Le 30 janvier", "is_correct": false}, {"id": "c", "label": "Le 25 janvier", "is_correct": false}, {"id": "d", "label": "Le 4 mars", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:19', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un chèque certifié est un chèque :', '[{"id": "a", "label": "Dont la provision est bloquée pendant le délai légal de présentation", "is_correct": false}, {"id": "b", "label": "Visé par le banquier", "is_correct": false}, {"id": "c", "label": "Pour lequel le porteur a obtenu de la banque un certificat de non-paiement", "is_correct": false}, {"id": "d", "label": "Dont le banquier atteste que la provision, non bloquée, existe au moment de la certification", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:20', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Sur les documents commerciaux d''une entreprise, une mention est facultative :', '[{"id": "a", "label": "Le numéro SIRET délivré par l''INSEE (Institut national de la statistique et des études économiques)", "is_correct": false}, {"id": "b", "label": "La mention RCS (Registre du commerce et des sociétés)", "is_correct": false}, {"id": "c", "label": "Le lieu du siège social", "is_correct": false}, {"id": "d", "label": "Le code NAF (Nomenclature des activités françaises)", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:21', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les associés d''une SARL (Société à responsabilité limitée) décident d''augmenter le capital social en faisant appel à de nouveaux apports. Ils doivent le faire :', '[{"id": "a", "label": "Lors de l''assemblée générale ordinaire", "is_correct": false}, {"id": "b", "label": "Lors de l''assemblée générale constitutive", "is_correct": false}, {"id": "c", "label": "Lors de l''assemblée générale extraordinaire", "is_correct": false}, {"id": "d", "label": "En dehors de toute assemblée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:22', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de désaccord avec une décision de justice rendue par le tribunal de commerce, concernant un montant de 7 500 €, vous pouvez porter l''affaire devant :', '[{"id": "a", "label": "La Cour de cassation", "is_correct": false}, {"id": "b", "label": "La Cour d''Appel", "is_correct": false}, {"id": "c", "label": "Le tribunal judiciaire", "is_correct": false}, {"id": "d", "label": "La Cour d''Assises ; Page 7 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:23', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le souscripteur d''un billet à ordre est :', '[{"id": "a", "label": "L''acheteur", "is_correct": false}, {"id": "b", "label": "Le vendeur", "is_correct": false}, {"id": "c", "label": "Le banquier du client", "is_correct": false}, {"id": "d", "label": "Le banquier du vendeur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:24', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La procédure d''injonction de payer permet :', '[{"id": "a", "label": "De demander par voie de justice le recouvrement de créances", "is_correct": false}, {"id": "b", "label": "De retarder juridiquement le paiement des créanciers", "is_correct": false}, {"id": "c", "label": "D''obtenir la liquidation judiciaire immédiate d''une entreprise", "is_correct": false}, {"id": "d", "label": "De se faire payer sans passer par une voie judiciaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:25', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lors de la création d''une société de capitaux, l''argent constituant le capital social libéré :', '[{"id": "a", "label": "Reste bloqué pendant toute la durée de vie de la société sur un compte en banque spécial", "is_correct": false}, {"id": "b", "label": "Reste bloqué uniquement pendant l''accomplissement des formalités de création et est ensuite disponible pour rembourser les associés", "is_correct": false}, {"id": "c", "label": "Reste bloqué uniquement pendant l''accomplissement des formalités de création et est ensuite disponible pour les besoins de la société", "is_correct": false}, {"id": "d", "label": "Est fictif et n''est jamais disponible pour la société", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:26', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La lettre de change est un effet de commerce :', '[{"id": "a", "label": "Dont le paiement est garanti à la date d’échéance figurant sur ce document", "is_correct": false}, {"id": "b", "label": "Qui est rédigé par le tiré et adressé au tireur pour acceptation", "is_correct": false}, {"id": "c", "label": "Qui est toujours à échéance indéterminée et escomptable", "is_correct": false}, {"id": "d", "label": "Qui est rédigé par le tireur et adressé au tiré pour acceptation", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:27', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Endosser un effet de commerce c’est :', '[{"id": "a", "label": "Bénéficier d’un crédit garanti sur le montant de l’effet", "is_correct": false}, {"id": "b", "label": "Désigner la banque qui paiera le montant de l’effet Page 8 sur 204", "is_correct": false}, {"id": "c", "label": "Se porter garant du paiement du montant de l’effet", "is_correct": false}, {"id": "d", "label": "Transmettre le bénéfice de l’effet à une tierce personne", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:28', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’injonction de payer est :', '[{"id": "a", "label": "Un effet de commerce", "is_correct": false}, {"id": "b", "label": "Une ordonnance du président du tribunal de commerce, ou du tribunal d’instance", "is_correct": false}, {"id": "c", "label": "Une lettre recommandée adressée par le créancier à son débiteur et exigeant le paiement immédiat de la créance", "is_correct": false}, {"id": "d", "label": "Une sommation signifiée par voie d’huissier", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:29', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’escompte d’une lettre de change :', '[{"id": "a", "label": "N’occasionne aucune charge financière à l’entreprise", "is_correct": false}, {"id": "b", "label": "Dégage l’entreprise du risque de non-paiement", "is_correct": false}, {"id": "c", "label": "Donne lieu à une entrée de trésorerie", "is_correct": false}, {"id": "d", "label": "Est toujours accepté", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:30', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La lettre de change (traite) est :', '[{"id": "a", "label": "Un moyen de paiement et un procédé de crédit à court terme", "is_correct": false}, {"id": "b", "label": "Un ordre de paiement immédiat sans frais", "is_correct": false}, {"id": "c", "label": "Un effet de commerce obligatoire entre commerçants", "is_correct": false}, {"id": "d", "label": "Un moyen de paiement uniquement international", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:31', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’escompte d’une traite consiste à :', '[{"id": "a", "label": "Indiquer au dos de l’effet un nouveau bénéficiaire", "is_correct": false}, {"id": "b", "label": "Compter des frais d’agio en cas de non- paiement", "is_correct": false}, {"id": "c", "label": "Obtenir la signature de sa banque pour confirmer la traite", "is_correct": false}, {"id": "d", "label": "Obtenir de sa banque une avance sur le montant de la traite", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:32', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un commerçant parisien confie à un transporteur lyonnais une expédition au départ de Lille et à destination de Marseille. Le transporteur n''est pas payé et Page 9 sur 204 assigne son client en paiement. Le tribunal de commerce normalement compétent sera celui de :', '[{"id": "a", "label": "Paris", "is_correct": false}, {"id": "b", "label": "Lyon", "is_correct": false}, {"id": "c", "label": "Lille", "is_correct": false}, {"id": "d", "label": "Marseille", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:33', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une SARL à associé unique, hors faute de gestion, le gérant associé unique est responsable :', '[{"id": "a", "label": "De la totalité des dettes sociales", "is_correct": false}, {"id": "b", "label": "Des dettes sociales sur ses biens personnels", "is_correct": false}, {"id": "c", "label": "Des dettes sociales à concurrence de ses apports", "is_correct": false}, {"id": "d", "label": "Des dettes sociales à concurrence de son chiffre d''affaires annuel", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:34', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Trois associés "X" , "Y" et "Z" décident de constituer une S.A.R.L. "X" apporte 4 500 € en espèces, "Y" apporte un terrain évalué à 10 000 €, "Z" apporte 3 100 € et un véhicule évalué à 9 000 € - L''Assemblée Générale des associés décide que "Z" sera le gérant unique de la S.A.R.L :', '[{"id": "a", "label": "Il sera majoritaire", "is_correct": false}, {"id": "b", "label": "Il sera minoritaire", "is_correct": false}, {"id": "c", "label": "Il pourra être salarié", "is_correct": false}, {"id": "d", "label": "Il devra obligatoirement être salarié", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:35', false) ON CONFLICT DO NOTHING;
