  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour qu''une SAS puisse opter pour l''impôt sur le revenu (IR), il faut :', '[{"id": "a", "label": "Un nombre minimum de 50 salariés", "is_correct": false}, {"id": "b", "label": "Un chiffre d''affaires minimum de 10 millions d’euros", "is_correct": false}, {"id": "c", "label": "Une durée d''existence de moins de 2 ans", "is_correct": false}, {"id": "d", "label": "Un montant de capital social minimum", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:61', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le principal avantage de l''impôt sur les sociétés (IS) pour une entreprise est :', '[{"id": "a", "label": "Une imposition plus faible que l''impôt sur le revenu (IR)", "is_correct": false}, {"id": "b", "label": "Une exonération totale d''impôt sur les revenus de l’entrepreneur", "is_correct": false}, {"id": "c", "label": "Une déduction des charges plus importante", "is_correct": false}, {"id": "c", "label": "Une imposition uniquement basée sur le chiffre d''affaires", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:62', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La différence entre la TVA collectée et la TVA déductible est :', '[{"id": "a", "label": "La TVA collectée est celle facturée aux clients, la TVA déductible est celle payée sur les achats", "is_correct": false}, {"id": "b", "label": "La TVA déductible est celle facturée aux clients, la TVA collectée est celle payée sur les achats", "is_correct": false}, {"id": "c", "label": "La TVA collectée est celle payée sur les achats, la TVA déductible est celle facturée aux clients", "is_correct": false}, {"id": "d", "label": "La TVA déductible est celle payée sur les salaires, la TVA collectée est celle payée sur les impôts Page 16 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:63', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le régime de franchise en base de TVA est :', '[{"id": "a", "label": "Un régime fiscal où l''entreprise ne collecte pas la TVA sur ses ventes", "is_correct": false}, {"id": "b", "label": "Un régime réservé aux grandes entreprises", "is_correct": false}, {"id": "c", "label": "Un régime qui exonère l''entreprise de tout impôt", "is_correct": false}, {"id": "d", "label": "Un régime où l''entreprise doit payer une TVA supplémentaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:64', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour bénéficier du régime de franchise en base de TVA, il faut :', '[{"id": "a", "label": "Un chiffre d''affaires annuel maximum", "is_correct": false}, {"id": "b", "label": "Un capital social minimum", "is_correct": false}, {"id": "c", "label": "Un nombre minimum de salariés", "is_correct": false}, {"id": "d", "label": "Une durée d''existence de moins de 3 ans", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:65', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La TVA intracommunautaire est :', '[{"id": "a", "label": "Une taxe sur les produits importés en provenance d''un pays tiers à l''Union européenne", "is_correct": false}, {"id": "b", "label": "Une taxe sur les produits importés en provenance d''un pays membre de l''Union européenne", "is_correct": false}, {"id": "c", "label": "Une taxe sur les produits vendus à l''intérieur d''un même pays", "is_correct": false}, {"id": "d", "label": "Une taxe sur les produits vendus à l''intérieur de l''Union européenne", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:66', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''objectif principal de la TVA intracommunautaire est :', '[{"id": "a", "label": "Faciliter les échanges commerciaux entre les pays membres de l''Union européenne", "is_correct": false}, {"id": "b", "label": "Taxer les échanges commerciaux avec les pays situés en dehors de l''Union européenne", "is_correct": false}, {"id": "c", "label": "Encourager la consommation des produits locaux", "is_correct": false}, {"id": "d", "label": "Limiter les importations en provenance des pays tiers à l''Union européenne", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:67', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La TVA collectée sur les achats intracommunautaires est :', '[{"id": "a", "label": "La TVA payée sur les achats effectués auprès de fournisseurs établis dans un autre pays de l''Union européenne Page 17 sur 204", "is_correct": false}, {"id": "b", "label": "La TVA payée sur les achats effectués auprès de fournisseurs établis en dehors de l''Union européenne", "is_correct": false}, {"id": "c", "label": "La TVA perçue par l''État sur les achats réalisés à l''intérieur du territoire national", "is_correct": false}, {"id": "d", "label": "La TVA perçue par les entreprises sur les achats réalisés auprès des particuliers", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:68', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le délai de paiement d''une facture est :', '[{"id": "a", "label": "Le temps laissé à l''entreprise pour émettre une facture après une prestation de service", "is_correct": false}, {"id": "b", "label": "Le temps laissé au client pour régler une facture après sa réception", "is_correct": false}, {"id": "c", "label": "Le temps laissé à l''entreprise pour régler une facture auprès de ses fournisseurs", "is_correct": false}, {"id": "d", "label": "Le temps pendant lequel une facture doit être conservée par l''entreprise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:69', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le délai de règlement par défaut après l’émission d’une facture est :', '[{"id": "a", "label": "15 jours", "is_correct": false}, {"id": "b", "label": "30 jours", "is_correct": false}, {"id": "c", "label": "45 jours", "is_correct": false}, {"id": "d", "label": "60 jours", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:70', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour préciser le montant total à payer, il faut indiquer, obligatoirement :', '[{"id": "a", "label": "Le prix unitaire des produits", "is_correct": false}, {"id": "b", "label": "Le coût de la livraison", "is_correct": false}, {"id": "c", "label": "Le total à payer", "is_correct": false}, {"id": "d", "label": "Le montant de la TVA", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:71', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La mention des taux de pénalités en cas de retard de paiement sur une facture sert à :', '[{"id": "a", "label": "Justifier les frais de livraison", "is_correct": false}, {"id": "b", "label": "Informer sur les conditions de paiement", "is_correct": false}, {"id": "c", "label": "Organiser la logistique de livraison", "is_correct": false}, {"id": "d", "label": "Inciter au règlement anticipé Page 18 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:72', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un effet de commerce est un(e) :', '[{"id": "a", "label": "Document permettant de régler une somme d''argent à vue", "is_correct": false}, {"id": "b", "label": "Titre ordonné par un créancier à un débiteur pour régler une somme d''argent à une échéance donnée", "is_correct": false}, {"id": "c", "label": "Lettre de change à usage commercial", "is_correct": false}, {"id": "d", "label": "Contrat de vente entre un fournisseur et un client", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:73', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les mentions obligatoires sur un effet de commerce sont :', '[{"id": "a", "label": "Le nom du fournisseur et du client", "is_correct": false}, {"id": "b", "label": "Le montant total de la transaction", "is_correct": false}, {"id": "c", "label": "La date de naissance du créancier et du débiteur", "is_correct": false}, {"id": "d", "label": "Le lieu et la date de sa réalisation, la désignation du tireur et du tiré, le montant de la créance, l’échéance du paiement, le lieu où le paiement doit être effectué, la signature du créancier et du débiteur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:74', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un effet de commerce est ordonnée par :', '[{"id": "a", "label": "Le créancier à lui-même", "is_correct": false}, {"id": "b", "label": "Le débiteur à un tiers", "is_correct": false}, {"id": "c", "label": "Le tiré au tireur", "is_correct": false}, {"id": "d", "label": "Le tireur au tiré", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:75', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La garantie pour le fournisseur en utilisant un effet de commerce est :', '[{"id": "a", "label": "La possibilité d''obtenir un crédit auprès d''une banque", "is_correct": false}, {"id": "b", "label": "La garantie d''être payé à l''échéance convenue", "is_correct": false}, {"id": "c", "label": "Le recours à des frais de traitement bancaire", "is_correct": false}, {"id": "d", "label": "L''assurance de récupérer les frais de recouvrement en cas de litige", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:76', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Quel est l''avantage pour le débiteur en utilisant un effet de commerce :', '[{"id": "a", "label": "La possibilité de payer immédiatement à la réception de la marchandise", "is_correct": false}, {"id": "b", "label": "Le bénéfice d''un délai de règlement tout en ayant immédiatement accès au service ou à la marchandise Page 19 sur 204", "is_correct": false}, {"id": "c", "label": "La garantie d''être exonéré de frais de traitement bancaire", "is_correct": false}, {"id": "d", "label": "L''accès à un escompte supplémentaire sur le prix de la transaction", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:77', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La durée généralement admise pour un effet de commerce est :', '[{"id": "a", "label": "Moins de 30 jours", "is_correct": false}, {"id": "b", "label": "Entre 30 et 60 jours", "is_correct": false}, {"id": "c", "label": "Moins de 90 jours", "is_correct": false}, {"id": "d", "label": "Plus de 90 jours", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:78', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''objectif principal de l''utilisation des effets de commerce est de :', '[{"id": "a", "label": "Faciliter les échanges commerciaux", "is_correct": false}, {"id": "b", "label": "Réduire les coûts administratifs", "is_correct": false}, {"id": "c", "label": "Optimiser la gestion de la trésorerie", "is_correct": false}, {"id": "d", "label": "Accélérer les procédures de recouvrement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:79', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''utilisation d''un effet de commerce en cas de litige a pour conséquence potentielle :', '[{"id": "a", "label": "Les frais de traitement bancaire supplémentaires", "is_correct": false}, {"id": "b", "label": "Un recours automatique au tribunal", "is_correct": false}, {"id": "c", "label": "Les frais de recouvrement à la charge du créancier", "is_correct": false}, {"id": "d", "label": "Un retard dans le paiement de la créance", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:80', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un tireur a intérêt à escompter un effet de commerce pour :', '[{"id": "a", "label": "Percevoir l''argent avant la date d''échéance", "is_correct": false}, {"id": "b", "label": "Allonger le délai de règlement pour le client", "is_correct": false}, {"id": "c", "label": "Éviter les frais de traitement bancaire", "is_correct": false}, {"id": "d", "label": "Garantir le paiement à l''échéance convenue", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:81', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le document écrit engageant l''acheteur à verser le paiement de la somme due soit à une date définie, soit à vue est :', '[{"id": "a", "label": "La traite Page 20 sur 204", "is_correct": false}, {"id": "b", "label": "La lettre de change", "is_correct": false}, {"id": "c", "label": "Le billet à ordre", "is_correct": false}, {"id": "d", "label": "Le contrat de vente", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:82', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Est généralement désigné comme le tireur sur un effet de commerce :', '[{"id": "a", "label": "Le créancier", "is_correct": false}, {"id": "b", "label": "Le débiteur", "is_correct": false}, {"id": "c", "label": "Le tiré", "is_correct": false}, {"id": "d", "label": "Le bénéficiaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:83', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''escompte d''un effet de commerce permet de :', '[{"id": "a", "label": "Prolonger le délai de paiement pour le débiteur", "is_correct": false}, {"id": "b", "label": "Accélérer le paiement pour le créancier", "is_correct": false}, {"id": "c", "label": "Annuler les frais de traitement bancaire", "is_correct": false}, {"id": "d", "label": "Exonérer le tiré de sa responsabilité", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:84', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La lettre de change sert principalement à :', '[{"id": "a", "label": "Établir les conditions de paiement entre deux parties", "is_correct": false}, {"id": "b", "label": "Régler une somme d''argent à une échéance convenue", "is_correct": false}, {"id": "c", "label": "Garantir le règlement d''une créance à l''échéance", "is_correct": false}, {"id": "d", "label": "Exiger un paiement immédiat à la réception de la marchandise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:85', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''effet de commerce est considéré comme un outil de gestion de trésorerie pour le débiteur car il lui :', '[{"id": "a", "label": "Permet de reporter le paiement jusqu''à la date d''échéance", "is_correct": false}, {"id": "b", "label": "Donne un crédit immédiat auprès de l''établissement bancaire", "is_correct": false}, {"id": "c", "label": "Garantit un escompte sur le prix total de la transaction", "is_correct": false}, {"id": "d", "label": "Permet de percevoir de l''argent avant la date de paiement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:86', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''utilisation d''un effet de commerce impacte la gestion de la trésorerie du tiré en lui : Page 21 sur 204 :', '[{"id": "a", "label": "Permettant de gérer plus facilement ses comptes bancaires", "is_correct": false}, {"id": "b", "label": "Permettant de bénéficier d''un crédit instantané auprès de la banque", "is_correct": false}, {"id": "c", "label": "Donnant un délai de paiement tout en lui assurant un service immédiat", "is_correct": false}, {"id": "d", "label": "Imposant des frais de traitement supplémentaires", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:87', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''effet de commerce est considéré comme une garantie de paiement pour le créancier parce que :', '[{"id": "a", "label": "Il implique l''acceptation préalable du tiré pour le paiement", "is_correct": false}, {"id": "b", "label": "Il est adossé à une assurance-crédit pour couvrir les impayés", "is_correct": false}, {"id": "c", "label": "Il formalise l''engagement du débiteur à payer à une date précise", "is_correct": false}, {"id": "d", "label": "Il est émis par un établissement bancaire garantissant le paiement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:88', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La différencie principale entre un effet de commerce et une lettre de change est :', '[{"id": "a", "label": "Le nombre d''intervenants impliqués", "is_correct": false}, {"id": "b", "label": "La nature de la transaction couverte", "is_correct": false}, {"id": "c", "label": "La durée de validité", "is_correct": false}, {"id": "d", "label": "Le mode de paiement requis", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:89', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le nombre d’intervenants impliqués dans un effet de commerce est :', '[{"id": "a", "label": "1", "is_correct": false}, {"id": "b", "label": "2", "is_correct": false}, {"id": "c", "label": "3", "is_correct": false}, {"id": "d", "label": "4", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:90', false) ON CONFLICT DO NOTHING;
