  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'un créancier est :', '[{"id": "a", "label": "Une personne physique ou morale ayant une dette envers une autre", "is_correct": false}, {"id": "b", "label": "Une personne physique ou morale détenant un droit de recevoir un paiement", "is_correct": false}, {"id": "c", "label": "Une société de recouvrement", "is_correct": false}, {"id": "d", "label": "Un service contentieux interne", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:113', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour connaître les raisons d''un paiement tardif, l’entreprise peut recourir, parfois, à un(e) :', '[{"id": "a", "label": "Injonction de payer", "is_correct": false}, {"id": "b", "label": "Recours à un avocat", "is_correct": false}, {"id": "c", "label": "Lettre de relance", "is_correct": false}, {"id": "d", "label": "Mise en demeure de payer", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:114', false) ON CONFLICT DO NOTHING;
