  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'les trois étapes du processus de recouvrement sont :', '[{"id": "a", "label": "Phoning, courriers, rendez-vous", "is_correct": false}, {"id": "b", "label": "Recueil d''informations, relance amiable, décision", "is_correct": false}, {"id": "c", "label": "Enquête, visite sur site, encaissement", "is_correct": false}, {"id": "d", "label": "Courriers, appels téléphoniques, visites", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:117', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La dernière étape du processus de recouvrement est la phase :', '[{"id": "a", "label": "De recueil d''informations", "is_correct": false}, {"id": "b", "label": "De relance amiable", "is_correct": false}, {"id": "c", "label": "De décision", "is_correct": false}, {"id": "d", "label": "De suivi", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:118', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', '"La créance est classée pour irrécouvrable" signifie :', '[{"id": "a", "label": "La créance est remboursée en totalité", "is_correct": false}, {"id": "b", "label": "La créance ne peut pas être recouvrée et est abandonnée", "is_correct": false}, {"id": "c", "label": "La créance est en cours de paiement", "is_correct": false}, {"id": "d", "label": "La créance est transférée à une autre agence", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:119', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’étape qui implique la mise en place de paliers pour associer différentes méthodes de relance est la phase : Page 28 sur 204 :', '[{"id": "a", "label": "De recueil d''informations", "is_correct": false}, {"id": "b", "label": "De relance amiable", "is_correct": false}, {"id": "c", "label": "De décision", "is_correct": false}, {"id": "d", "label": "De suivi", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:120', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lors de la phase de recueil d''informations, l''opérateur chargé de la créance :', '[{"id": "a", "label": "Envoie des courriers simples et recommandés", "is_correct": false}, {"id": "b", "label": "Réalise une enquête sur le client", "is_correct": false}, {"id": "c", "label": "Organise des rendez-vous avec le client", "is_correct": false}, {"id": "d", "label": "Envoie des rappels de paiement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:121', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les agences de recouvrement définissent des paliers lors de la phase de relance amiable pour :', '[{"id": "a", "label": "Réduire les coûts de recouvrement", "is_correct": false}, {"id": "b", "label": "Associer les différentes méthodes de contact en fonction du montant de la créance", "is_correct": false}, {"id": "c", "label": "Augmenter les ventes", "is_correct": false}, {"id": "d", "label": "Améliorer la satisfaction client", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:103', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si le débiteur a réglé sa dette, après la phase de relance amiable, :', '[{"id": "a", "label": "La procédure judiciaire est lancée", "is_correct": false}, {"id": "b", "label": "La créance est classée pour irrécouvrable", "is_correct": false}, {"id": "c", "label": "La créance est considérée comme recouvrée", "is_correct": false}, {"id": "d", "label": "Un rappel est envoyé au client", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:122', false) ON CONFLICT DO NOTHING;
