  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La principale différence entre la sauvegarde et la liquidation est :', '[{"id": "a", "label": "La sauvegarde maintient l''activité économique, tandis que la liquidation entraîne la vente des actifs", "is_correct": false}, {"id": "b", "label": "La sauvegarde liquide l''entreprise, tandis que la liquidation la réorganise", "is_correct": false}, {"id": "c", "label": "La sauvegarde entraîne la cessation d''activité, tandis que la liquidation maintient l''emploi", "is_correct": false}, {"id": "d", "label": "La sauvegarde permet de réorganiser l''entreprise, tandis que la liquidation ferme l''entreprise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:127', false) ON CONFLICT DO NOTHING;
