  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour bénéficier de la procédure de sauvegarde, il faut :', '[{"id": "a", "label": "Être en cessation des paiements et avoir des dettes exigibles", "is_correct": false}, {"id": "b", "label": "Être confronté à des difficultés qu’on ne peut pas surmonter", "is_correct": false}, {"id": "c", "label": "Être en possession de capitaux propres importants", "is_correct": false}, {"id": "d", "label": "Avoir un actif disponible supérieur aux dettes exigibles", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:129', false) ON CONFLICT DO NOTHING;
