  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le commerçant doit respecter le droit de la concurrence qui implique :', '[{"id": "a", "label": "La possibilité de fixer les prix librement", "is_correct": false}, {"id": "b", "label": "L’interdiction des pratiques déloyales", "is_correct": false}, {"id": "c", "label": "L’obligation de fusionner avec d’autres entreprises", "is_correct": false}, {"id": "d", "label": "La fixation des prix par l''État", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:165', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'l’obligation principale du commerçant en matière de comptabilité est :', '[{"id": "a", "label": "Tenir une comptabilité en partie double", "is_correct": false}, {"id": "b", "label": "Tenir une comptabilité simplifiée Page 37 sur 204", "is_correct": false}, {"id": "c", "label": "Présenter ses comptes au greffe tous les ans", "is_correct": false}, {"id": "d", "label": "Publier ses résultats financiers dans un journal d''annonces légales", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:166', false) ON CONFLICT DO NOTHING;
