  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le délai pour déclarer une créance dans une procédure collective est de :', '[{"id": "a", "label": "1 mois", "is_correct": false}, {"id": "b", "label": "2 mois", "is_correct": false}, {"id": "c", "label": "3 mois", "is_correct": false}, {"id": "d", "label": "6 mois", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:168', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans le cadre d''une liquidation judiciaire, les contrats en cours de l’entreprise sont :', '[{"id": "a", "label": "Automatiquement résiliés", "is_correct": false}, {"id": "b", "label": "Maintenus sous la supervision du liquidateur", "is_correct": false}, {"id": "c", "label": "Négociés au cas par cas", "is_correct": false}, {"id": "d", "label": "Transférés à une autre entreprise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:169', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'lors d''une liquidation judiciaire, la priorité des créanciers est :', '[{"id": "a", "label": "Les créanciers chirographaires (non privilégiés)", "is_correct": false}, {"id": "b", "label": "Les créanciers hypothécaires", "is_correct": false}, {"id": "c", "label": "Les créanciers salariés", "is_correct": false}, {"id": "d", "label": "Les créanciers fiscaux Page 38 sur 204 Module B L’ENTREPRISE ET SON ACTIVITE COMMERCIALE", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-a', 'droit', 'capa-3-5t'], 'base-2026:qcm:170', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''étude de marché permet de :', '[{"id": "a", "label": "Définir la stratégie de communication", "is_correct": false}, {"id": "b", "label": "Analyser l''offre et la demande sur un marché donné", "is_correct": false}, {"id": "c", "label": "Calculer les bénéfices nets d''une entreprise", "is_correct": false}, {"id": "d", "label": "Évaluer les performances des salariés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:171', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le segment de marché désigne :', '[{"id": "a", "label": "Le prix moyen des produits sur un marché", "is_correct": false}, {"id": "b", "label": "Un groupe homogène de consommateurs partageant des caractéristiques communes", "is_correct": false}, {"id": "c", "label": "L''ensemble des concurrents présents sur un marché", "is_correct": false}, {"id": "d", "label": "La part de marché détenue par une entreprise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:172', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La prospection réactive consiste à :', '[{"id": "a", "label": "Attendre que les prospects prennent contact avec l''entreprise", "is_correct": false}, {"id": "b", "label": "Réagir aux sollicitations des clients potentiels de manière proactive", "is_correct": false}, {"id": "c", "label": "Mettre en place des actions promotionnelles en réponse à la concurrence", "is_correct": false}, {"id": "d", "label": "Adapter les prix en fonction des fluctuations du marché", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:173', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La prospection digitale se différencie de la prospection traditionnelle par :', '[{"id": "a", "label": "L''utilisation d''outils numériques comme les réseaux sociaux, l''emailing, et le marketing de contenu pour atteindre de nouveaux clients", "is_correct": false}, {"id": "b", "label": "La suppression des contacts directs avec les clients", "is_correct": false}, {"id": "c", "label": "La concentration sur les marchés locaux uniquement", "is_correct": false}, {"id": "d", "label": "La réduction des coûts en éliminant les intermédiaires", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:174', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’automatisation du marketing dans la prospection commerciale permet de :', '[{"id": "a", "label": "Remplacer totalement les commerciaux", "is_correct": false}, {"id": "b", "label": "Réduire les coûts de production", "is_correct": false}, {"id": "c", "label": "Augmenter automatiquement les prix en fonction de la demande", "is_correct": false}, {"id": "d", "label": "Personnaliser à grande échelle les campagnes de prospection", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:174', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Page 39 sur 204 La prospection commerciale a pour principal objectif :', '[{"id": "a", "label": "De fidéliser les clients existants", "is_correct": false}, {"id": "b", "label": "De rechercher et d''acquérir de nouveaux clients", "is_correct": false}, {"id": "c", "label": "De réduire les coûts de production", "is_correct": false}, {"id": "d", "label": "De diversifier les produits de l''entreprise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:175', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une étude de la concurrence dans le cadre d''une étude de marché vise à :', '[{"id": "a", "label": "Identifier les leaders d''opinion dans un secteur", "is_correct": false}, {"id": "b", "label": "Analyser les forces et les faiblesses des concurrents directs et indirects", "is_correct": false}, {"id": "c", "label": "Déterminer le potentiel de vente d''un produit innovant", "is_correct": false}, {"id": "d", "label": "Définir la stratégie de prospection commerciale", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:176', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le taux de réponse dans une campagne de prospection est :', '[{"id": "a", "label": "Le nombre de ventes réalisées par rapport aux produits en stock", "is_correct": false}, {"id": "b", "label": "Le pourcentage de prospects qui ont répondu favorablement à une sollicitation", "is_correct": false}, {"id": "c", "label": "La proportion de clients qui recommandent le produit", "is_correct": false}, {"id": "d", "label": "Le taux de retour des produits après achat", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:177', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La prise de rendez-vous qualifiée dans une stratégie de prospection consiste à :', '[{"id": "a", "label": "Programmer des rencontres avec des prospects ayant un fort potentiel d’achat", "is_correct": false}, {"id": "b", "label": "Fixer des objectifs de vente mensuels", "is_correct": false}, {"id": "c", "label": "Réaliser des ventes directes lors des rendez-vous", "is_correct": false}, {"id": "d", "label": "Obtenir des références de la part de clients existants", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:179', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une politique de fidélisation des clients inclut souvent :', '[{"id": "a", "label": "Les réductions de prix pour les nouveaux clients", "is_correct": false}, {"id": "b", "label": "Les programmes de récompenses et de fidélité pour encourager les achats récurrents", "is_correct": false}, {"id": "c", "label": "Les campagnes de publicité agressives", "is_correct": false}, {"id": "d", "label": "La suppression des produits moins rentables", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:180', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un pitch commercial efficace doit :', '[{"id": "a", "label": "Être long et détaillé pour convaincre le prospect", "is_correct": false}, {"id": "b", "label": "Être court, percutant, et mettre en avant la proposition de valeur unique de l''offre", "is_correct": false}, {"id": "c", "label": "Se concentrer uniquement sur les caractéristiques techniques du produit Page 40 sur 204", "is_correct": false}, {"id": "d", "label": "Inclure des réductions de prix immédiates pour attirer le client", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:181', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une politique de prix d''appel implique :', '[{"id": "a", "label": "La fixation d''un prix bas pour un produit de base afin d''attirer les clients, en espérant qu''ils achètent aussi des produits à marge plus élevée", "is_correct": false}, {"id": "b", "label": "La fixation du prix le plus élevé possible pour maximiser les marges", "is_correct": false}, {"id": "c", "label": "La tarification dynamique en fonction de la saisonnalité", "is_correct": false}, {"id": "d", "label": "L''utilisation de coupons de réduction pour stimuler les ventes", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:182', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le cycle de vie d’un produit comprend généralement les phases suivantes :', '[{"id": "a", "label": "Lancement, croissance, maturité, déclin", "is_correct": false}, {"id": "b", "label": "Introduction, saturation, obsolescence, renouvellement", "is_correct": false}, {"id": "c", "label": "Innovation, développement, saturation, remplacement", "is_correct": false}, {"id": "d", "label": "Conception, production, commercialisation, fin de vie", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:183', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le positionnement d''un produit correspond à :', '[{"id": "a", "label": "La stratégie de distribution choisie", "is_correct": false}, {"id": "b", "label": "La place qu''il occupe dans l''esprit du consommateur par rapport à ses concurrents", "is_correct": false}, {"id": "c", "label": "Le segment de marché auquel il s''adresse", "is_correct": false}, {"id": "d", "label": "Son prix de vente par rapport à la concurrence", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-b', 'commercial', 'capa-3-5t'], 'base-2026:qcm:184', false) ON CONFLICT DO NOTHING;
