  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de non-conformité aux exigences réglementaires, une entreprise de transport risque : Page 47 sur 204 :', '[{"id": "a", "label": "Une augmentation des frais de gestion", "is_correct": false}, {"id": "b", "label": "Des amendes et restrictions d''exploitation", "is_correct": false}, {"id": "c", "label": "Des amendes et le retrait immédiat des licences", "is_correct": false}, {"id": "d", "label": "Des sanctions pénales pour le dirigent et les associés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:216', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''une des principales responsabilités en matière de gestion de la qualité dans le secteur du transport est :', '[{"id": "a", "label": "D’assurer la conformité des véhicules aux normes environnementales", "is_correct": false}, {"id": "b", "label": "De maintenir la qualité du service client et des livraisons", "is_correct": false}, {"id": "c", "label": "De réduire les coûts de carburant", "is_correct": false}, {"id": "d", "label": "D’optimiser les horaires de livraison", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:217', false) ON CONFLICT DO NOTHING;
