  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un gestionnaire de flotte a pour fonction principale de :', '[{"id": "a", "label": "Négocier les contrats de sous-traitance", "is_correct": false}, {"id": "b", "label": "Gérer l''entretien préventif et correctif des véhicules", "is_correct": false}, {"id": "c", "label": "Élaborer des stratégies de marketing", "is_correct": false}, {"id": "d", "label": "Augmenter les revenus par la diversification des services", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:219', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le transport pour compte propre :', '[{"id": "a", "label": "Est réservé aux entreprises de transport public", "is_correct": false}, {"id": "b", "label": "Est soumis à une réglementation stricte", "is_correct": false}, {"id": "c", "label": "Est réalisé par une entreprise pour ses propres besoins", "is_correct": false}, {"id": "d", "label": "Nécessite une licence de transport spécifique", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:220', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Selon le code des transports, un type de transports est généralement libéralisé . Il s’agit du :', '[{"id": "a", "label": "Transport pour compte propre", "is_correct": false}, {"id": "b", "label": "Transport pour compte d''autrui", "is_correct": false}, {"id": "c", "label": "Transport de marchandises dangereuses", "is_correct": false}, {"id": "d", "label": "Transport international Page 48 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:221', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le transport de lait dans le cadre d''une exploitation agricole est considéré comme :', '[{"id": "a", "label": "Transport pour compte propre", "is_correct": false}, {"id": "b", "label": "Transport pour compte d''autrui", "is_correct": false}, {"id": "c", "label": "Transport public", "is_correct": false}, {"id": "d", "label": "Transport pour le compte d’une coopérative agricole", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:222', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un type de transport n''est pas soumis aux limitations de quantité ou de distance selon les articles du code des transports :', '[{"id": "a", "label": "Transport pour compte propre", "is_correct": false}, {"id": "b", "label": "Transport de marchandises par autocars de ligne", "is_correct": false}, {"id": "c", "label": "Transport pour compte d''autrui", "is_correct": false}, {"id": "d", "label": "Transport de marchandises dangereuses", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:223', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Est exempté de certaines réglementations lorsqu''il transporte des marchandises :', '[{"id": "a", "label": "Le véhicules agricoles utilisés à titre occasionnel", "is_correct": false}, {"id": "b", "label": "Le véhicules à vitesse inférieure à 80 km/h", "is_correct": false}, {"id": "c", "label": "Le véhicules de transport en commun", "is_correct": false}, {"id": "d", "label": "Le véhicules de tourisme", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:224', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour que les transports réalisés au sein des groupements d''entreprises agricoles aient une exemption de réglementation il faut que :', '[{"id": "a", "label": "Les véhicules appartiennent uniquement aux membres du groupement", "is_correct": false}, {"id": "b", "label": "Les transports soient effectués dans une zone limité", "is_correct": false}, {"id": "c", "label": "Les marchandises transportées appartiennent à un membre du groupement", "is_correct": false}, {"id": "d", "label": "Le transport ne soit que l''accessoire de l''activité principale du groupement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:225', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour un transport de véhicules accidentés, la restriction principale imposée par la réglementation est :', '[{"id": "a", "label": "La distance maximale du transport ne doit pas dépasser 500 km", "is_correct": false}, {"id": "b", "label": "Le transport doit être réalisé par un véhicule spécialisé", "is_correct": false}, {"id": "c", "label": "Le transport doit être effectué le jour de l’accident", "is_correct": false}, {"id": "d", "label": "Le véhicule accidenté doit être d’occasion", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:226', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour que les transports entre entreprises liées par contrat soient exemptés de réglementation stricte, il faut :', '[{"id": "a", "label": "Que le transport soit réalisé par des sous-traitants", "is_correct": false}, {"id": "b", "label": "Que les marchandises soient la propriété de l''une des entreprises contractantes Page 49 sur 204", "is_correct": false}, {"id": "c", "label": "Que le transport soit réalisé sur une distance supérieure à 100 km", "is_correct": false}, {"id": "d", "label": "Que le transport soit l''activité principale de l''entreprise contractante", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:227', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une entreprise de transport public de marchandises doit faire une inscription au registre des transporteurs :', '[{"id": "a", "label": "Pour obtenir des subventions publiques", "is_correct": false}, {"id": "b", "label": "Pour garantir l''accès aux marchés internationaux", "is_correct": false}, {"id": "c", "label": "Pour respecter les obligations légales de transport pour compte d''autrui", "is_correct": false}, {"id": "d", "label": "Pour réduire les coûts d''exploitation", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:228', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un type de véhicule est soumis à des exemptions lorsqu''il roule à moins de 25 km/h, ce sont des :', '[{"id": "a", "label": "Véhicules de tourisme", "is_correct": false}, {"id": "b", "label": "Véhicules agricoles", "is_correct": false}, {"id": "c", "label": "Véhicules spéciaux (matériels forestiers, travaux publics)", "is_correct": false}, {"id": "d", "label": "Véhicules électriques", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:229', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le transport de marchandises par autocars de ligne peut être effectué :', '[{"id": "a", "label": "Sans limitation de quantité ou de distance", "is_correct": false}, {"id": "b", "label": "Avec une limitation stricte de 50 km", "is_correct": false}, {"id": "c", "label": "Seulement pour les transports urbains", "is_correct": false}, {"id": "d", "label": "Exclusivement pour les marchandises périssables", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:230', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le transport pour compte propre est-il libéralisé :', '[{"id": "a", "label": "Parce qu''il est moins coûteux à réglementer", "is_correct": false}, {"id": "b", "label": "Parce qu''il est effectué par des entreprises pour leur propre usage", "is_correct": false}, {"id": "c", "label": "Parce qu''il concerne uniquement les petites entreprises", "is_correct": false}, {"id": "d", "label": "Parce qu''il est réalisé sur des distances courtes", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:231', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les transports réalisés par des véhicules agricoles peuvent être exemptés de certaines réglementations :', '[{"id": "a", "label": "Parce qu''ils sont toujours effectués à titre onéreux", "is_correct": false}, {"id": "b", "label": "Parce qu''ils concernent des distances supérieures à 100 km", "is_correct": false}, {"id": "c", "label": "Parce qu''ils sont souvent nécessaires pour les besoins urgents de l''agriculture", "is_correct": false}, {"id": "d", "label": "Parce qu''ils impliquent des véhicules légers", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:232', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Par rapport à un transport pour compte d''autrui, un transport pour compte propre : Page 50 sur 204 :', '[{"id": "a", "label": "Est plus rentable", "is_correct": false}, {"id": "b", "label": "Est exempté de la plupart des réglementations strictes", "is_correct": false}, {"id": "c", "label": "Est réservé aux grandes entreprises", "is_correct": false}, {"id": "d", "label": "Est subventionné par l''État", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:233', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Certains transports peuvent être effectués par des entreprises liées par contrat sans respecter la réglementation stricte :', '[{"id": "a", "label": "Les transports réalisés à l''international", "is_correct": false}, {"id": "b", "label": "Les transports nécessaires à l''exécution d''un travail commun", "is_correct": false}, {"id": "c", "label": "Les transports effectués en milieu urbain", "is_correct": false}, {"id": "d", "label": "Les transports de courte distance", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:234', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les prestations de base dans un contrat de transport sont :', '[{"id": "a", "label": "La manutention au déchargement", "is_correct": false}, {"id": "b", "label": "La conduite du véhicule et la préparation au chargement", "is_correct": false}, {"id": "c", "label": "Le nettoyage du véhicule après livraison", "is_correct": false}, {"id": "d", "label": "La gestion des douanes", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:235', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans un contrat de transport, "port dû" signifie :', '[{"id": "a", "label": "Les frais sont à la charge de l''expéditeur", "is_correct": false}, {"id": "b", "label": "Les frais sont à la charge du destinataire", "is_correct": false}, {"id": "c", "label": "Les frais sont payés par le transporteur", "is_correct": false}, {"id": "d", "label": "Les frais sont partagés entre l''expéditeur et le destinataire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:236', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un transporteur doit respecter les délais de livraison :', '[{"id": "a", "label": "Seulement si spécifié par le destinataire", "is_correct": false}, {"id": "b", "label": "Toujours, sauf en cas de force majeure", "is_correct": false}, {"id": "c", "label": "Seulement si l''expéditeur le demande", "is_correct": false}, {"id": "d", "label": "Lorsque le véhicule est en bon état", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:237', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En l''absence de réserves à la prise en charge, on présume :', '[{"id": "a", "label": "Que les marchandises ont été endommagées", "is_correct": false}, {"id": "b", "label": "Que les marchandises ont été livrées en bon état", "is_correct": false}, {"id": "c", "label": "Que le transporteur n''a pas effectué de vérification", "is_correct": false}, {"id": "d", "label": "Que les marchandises n''ont pas été chargées correctement Page 51 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:238', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La principale conséquence de l''absence de réserves pour défaut d''emballage à la prise en charge est :', '[{"id": "a", "label": "Le transporteur est exonéré de toute responsabilité", "is_correct": false}, {"id": "b", "label": "Le transporteur doit prouver que les dommages proviennent d''un défaut d''emballage", "is_correct": false}, {"id": "c", "label": "Le destinataire devient responsable de tout dommage", "is_correct": false}, {"id": "d", "label": "Le contrat de transport devient nul", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:239', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les obligations de l''expéditeur envers le transporteur lors de la prise en charge de la marchandise sont :', '[{"id": "a", "label": "Emballer et étiqueter la marchandise, respecter les réglementations, fournir les documents nécessaires", "is_correct": false}, {"id": "b", "label": "Superviser la conduite du chauffeur", "is_correct": false}, {"id": "c", "label": "Payer le salaire du chauffeur", "is_correct": false}, {"id": "d", "label": "Entretenir le véhicule du transporteur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:240', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lors de la prise en charge de la marchandise, le transporteur doit :', '[{"id": "a", "label": "Contrôler le chargement sous l''angle de la sécurité", "is_correct": false}, {"id": "b", "label": "Emballer la marchandise", "is_correct": false}, {"id": "c", "label": "Réaliser la manutention au déchargement", "is_correct": false}, {"id": "d", "label": "Vérifier le carburant du véhicule", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:241', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le document de suivi dans le contrat de transport sert à :', '[{"id": "a", "label": "Vérifier l''état du véhicule", "is_correct": false}, {"id": "b", "label": "Confirmer l''exécution des conditions prévues dans le devis accepté", "is_correct": false}, {"id": "c", "label": "Décrire la marchandise transportée", "is_correct": false}, {"id": "d", "label": "Déterminer la rémunération du chauffeur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:242', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si un transporteur livre une marchandise à un tiers non mandaté, il en résulte :', '[{"id": "a", "label": "Une réduction du prix du transport", "is_correct": false}, {"id": "b", "label": "Une responsabilité engagée du transporteur Page 52 sur 204", "is_correct": false}, {"id": "c", "label": "Une exonération de responsabilité pour le transporteur", "is_correct": false}, {"id": "d", "label": "Une annulation du contrat", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:243', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La procédure normale pour le paiement du transport est :', '[{"id": "a", "label": "Paiement avant le départ de la marchandise", "is_correct": false}, {"id": "b", "label": "Paiement à réception de la facture", "is_correct": false}, {"id": "c", "label": "Paiement après un mois", "is_correct": false}, {"id": "d", "label": "Paiement à l''arrivée de la marchandise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:244', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le document qui n''est pas obligatoire dans le cadre d''un contrat de transport est :', '[{"id": "a", "label": "La lettre de voiture", "is_correct": false}, {"id": "b", "label": "Le document de suivi", "is_correct": false}, {"id": "c", "label": "L''ordre de mission", "is_correct": false}, {"id": "d", "label": "L''état récapitulatif", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:245', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le déchargement des envois de moins de trois tonnes dans un commerce sur rue se fait :', '[{"id": "a", "label": "Au pied du véhicule", "is_correct": false}, {"id": "b", "label": "Au seuil du magasin", "is_correct": false}, {"id": "c", "label": "À l''intérieur du magasin", "is_correct": false}, {"id": "d", "label": "Au dépôt central", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:246', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si un tiers prend livraison d''une marchandise par erreur mais utilise la marchandise sans intention frauduleuse, le (s) responsable (s) est (sont ) :', '[{"id": "a", "label": "Le destinataire", "is_correct": false}, {"id": "b", "label": "Le transporteur seul", "is_correct": false}, {"id": "c", "label": "Le tiers seul", "is_correct": false}, {"id": "d", "label": "Le tiers et le transporteur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:247', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contre-remboursement dans un contrat de transport est une :', '[{"id": "a", "label": "Prestation de base", "is_correct": false}, {"id": "b", "label": "Prestation annexe", "is_correct": false}, {"id": "c", "label": "Prestation obligatoire", "is_correct": false}, {"id": "d", "label": "Prestation conditionnelle Page 53 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:248', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le transporteur devient juridiquement responsable de la marchandise :', '[{"id": "a", "label": "Dès la signature du contrat", "is_correct": false}, {"id": "b", "label": "Lors de la prise en charge physique de la marchandise", "is_correct": false}, {"id": "c", "label": "À l''arrivée au lieu de destination", "is_correct": false}, {"id": "d", "label": "Après le chargement complet du véhicule", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:249', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lors d’un transport, le type de matériel et les équipements particuliers souhaités sont fournis par :', '[{"id": "a", "label": "Le destinataire", "is_correct": false}, {"id": "b", "label": "Le transporteur", "is_correct": false}, {"id": "c", "label": "Le donneur d''ordre", "is_correct": false}, {"id": "d", "label": "Le fabricant du matériel", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:250', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''une des obligations du transporteur concernant l''heure d''arrivée est de :', '[{"id": "a", "label": "Respecter l''heure du rendez-vous ou arriver dans un délai raisonnable", "is_correct": false}, {"id": "b", "label": "Arriver une heure avant l''heure prévue", "is_correct": false}, {"id": "c", "label": "Informer l''expéditeur du retard", "is_correct": false}, {"id": "d", "label": "Ne pas dépasser le délai fixé par le destinataire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:251', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si un transporteur ne fait pas de réserves lors de la prise en charge, cela prouve en cas de dommage :', '[{"id": "a", "label": "Que la marchandise était endommagée avant le chargement", "is_correct": false}, {"id": "b", "label": "Que le dommage a été causé par un facteur externe", "is_correct": false}, {"id": "c", "label": "Que le dommage est survenu pendant le transport", "is_correct": false}, {"id": "d", "label": "Il n''a rien à prouver, car l''absence de réserves prouve que la marchandise était en bon état", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:252', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si le transporteur émet des réserves pour avarie lors de la prise en charge :', '[{"id": "a", "label": "Les réserves sont incontestables et prouvent l''état de la marchandise", "is_correct": false}, {"id": "b", "label": "Les réserves sont annulées après la livraison", "is_correct": false}, {"id": "c", "label": "Le transporteur est automatiquement exonéré de responsabilité", "is_correct": false}, {"id": "d", "label": "L''expéditeur doit réparer les avaries avant la livraison", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:253', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Page 54 sur 204 Pour un envoi de trois tonnes et plus, le déchargement est la responsabilité :', '[{"id": "a", "label": "Du transporteur", "is_correct": false}, {"id": "b", "label": "De l''expéditeur", "is_correct": false}, {"id": "c", "label": "Du destinataire", "is_correct": false}, {"id": "d", "label": "Du mandataire du destinataire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:254', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''assurance marchandise couvre généralement :', '[{"id": "a", "label": "Les dommages causés par le retard du transporteur", "is_correct": false}, {"id": "b", "label": "Les pertes ou avaries de la marchandise pendant le transport", "is_correct": false}, {"id": "c", "label": "Les amendes de douane", "is_correct": false}, {"id": "d", "label": "Les pertes financières liées à l''annulation du contrat de transport", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:255', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Peut souscrire une assurance marchandise :', '[{"id": "a", "label": "Le vendeur uniquement", "is_correct": false}, {"id": "b", "label": "Le transporteur uniquement", "is_correct": false}, {"id": "c", "label": "Le propriétaire, le mandataire ou le vendeur", "is_correct": false}, {"id": "d", "label": "L''acheteur uniquement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:256', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de souscription d''une assurance "tous risques", l''assureur :', '[{"id": "a", "label": "Couvre uniquement les pertes causées par des catastrophes naturelles", "is_correct": false}, {"id": "b", "label": "Couvre tous les types de pertes sauf celles exclues explicitement", "is_correct": false}, {"id": "c", "label": "Ne couvre pas les pertes de poids", "is_correct": false}, {"id": "d", "label": "Couvre uniquement les vols prouvés par une plainte déposée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:257', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La garantie "Accidents caractérisés" couvre :', '[{"id": "a", "label": "Tous les dommages sans exception", "is_correct": false}, {"id": "b", "label": "Seulement les pertes ou dommages causés par des événements spécifiques énumérés dans la police", "is_correct": false}, {"id": "c", "label": "Les dommages causés par les vice propres de la marchandise", "is_correct": false}, {"id": "d", "label": "Les pertes financières dues à un retard dans la livraison", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:258', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''assurance responsabilité contractuelle couvre :', '[{"id": "a", "label": "Les dommages aux marchandises. Page 55 sur 204", "is_correct": false}, {"id": "b", "label": "Les pertes financières dues à une mauvaise exécution du contrat de transport", "is_correct": false}, {"id": "c", "label": "Les biens personnels du transporteur", "is_correct": false}, {"id": "d", "label": "Les pertes subies par le transporteur en cas de faillite", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:259', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La garantie "tous risques" en assurance responsabilité couvre :', '[{"id": "a", "label": "Tous les événements sauf ceux explicitement exclus", "is_correct": false}, {"id": "b", "label": "Un nombre limité d''accidents énumérés dans le contrat", "is_correct": false}, {"id": "c", "label": "Uniquement les dommages causés par des catastrophes naturelles", "is_correct": false}, {"id": "d", "label": "Aucun risque sans une déclaration préalable", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:260', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une entreprise qui n''a pas souscrit d''assurance responsabilité court le risque :', '[{"id": "a", "label": "D''être exemptée de toute responsabilité en cas d''incident", "is_correct": false}, {"id": "b", "label": "De devoir payer de sa propre poche les indemnités dues en cas de litige", "is_correct": false}, {"id": "c", "label": "De ne pas être autorisée à exercer l''activité de transporteur", "is_correct": false}, {"id": "d", "label": "De voir ses véhicules saisis par les autorités", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:261', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La police de base en assurance responsabilité exclut généralement :', '[{"id": "a", "label": "Les dommages causés aux marchandises précieuses", "is_correct": false}, {"id": "b", "label": "Les dommages causés par des événements naturels", "is_correct": false}, {"id": "c", "label": "Les dommages causés par une surcharge du véhicule", "is_correct": false}, {"id": "d", "label": "Les dommages causés aux animaux vivants", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:262', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''assurance flotte est obligatoire pour :', '[{"id": "a", "label": "Couvrir les dommages aux marchandises transportées", "is_correct": false}, {"id": "b", "label": "Garantir la responsabilité civile liée à l''utilisation des véhicules", "is_correct": false}, {"id": "c", "label": "Assurer la flotte contre les catastrophes naturelles", "is_correct": false}, {"id": "d", "label": "Couvrir les vols de véhicules", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:263', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''assurance « vol et incendie » dans le cadre de l''assurance flotte couvre :', '[{"id": "a", "label": "Uniquement les dommages causés aux marchandises", "is_correct": false}, {"id": "b", "label": "Les dommages causés au véhicule volé ou incendié", "is_correct": false}, {"id": "c", "label": "Les dommages aux passagers du véhicule", "is_correct": false}, {"id": "d", "label": "Tous les accidents de la route", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:264', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La déclaration de valeur : Page 56 sur 204 :', '[{"id": "a", "label": "Remplace l''assurance marchandise", "is_correct": false}, {"id": "b", "label": "Permet une réparation des dommages si la responsabilité du transporteur est reconnue", "is_correct": false}, {"id": "c", "label": "Couvre tous les risques", "is_correct": false}, {"id": "d", "label": "Est obligatoire pour chaque expédition", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:265', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La police d''abonnement est également appelée :', '[{"id": "a", "label": "Police au voyage", "is_correct": false}, {"id": "b", "label": "Police flottante", "is_correct": false}, {"id": "c", "label": "Police à alimenter", "is_correct": false}, {"id": "d", "label": "Police à tiers chargeur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:266', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les matières dangereuses :', '[{"id": "a", "label": "Sont toujours couvertes par la police de base d''assurance marchandise", "is_correct": false}, {"id": "b", "label": "Nécessitent une garantie spéciale", "is_correct": false}, {"id": "c", "label": "Sont exclues de toutes les assurances marchandises", "is_correct": false}, {"id": "d", "label": "Ne peuvent pas être assurées", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:267', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une surcharge de véhicule peut entraîner :', '[{"id": "a", "label": "Une annulation de la police d''assurance", "is_correct": false}, {"id": "b", "label": "Une amende de 750 €", "is_correct": false}, {"id": "c", "label": "Une indemnisation de l''assureur", "is_correct": false}, {"id": "d", "label": "Une réduction des primes d''assurance", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:268', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''assurance de la responsabilité civile délictuelle :', '[{"id": "a", "label": "Est obligatoire pour tous les transporteurs", "is_correct": false}, {"id": "b", "label": "Couvre les dommages causés à des tiers en dehors d''un contrat", "is_correct": false}, {"id": "c", "label": "Ne couvre que les dommages causés aux clients", "is_correct": false}, {"id": "d", "label": "Est identique à l''assurance responsabilité civile contractuelle", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:269', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les polices à alimenter exigent que :', '[{"id": "a", "label": "L''assuré déclare chaque expédition avant son départ", "is_correct": false}, {"id": "b", "label": "L''assuré paie une prime unique pour toutes les expéditions", "is_correct": false}, {"id": "c", "label": "L''assuré fournisse un rapport annuel à l''assureur", "is_correct": false}, {"id": "d", "label": "L''assuré assure uniquement des marchandises périssables", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:270', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Page 57 sur 204 La responsabilité civile contractuelle est :', '[{"id": "a", "label": "Toujours couverte par l''assurance responsabilité civile délictuelle", "is_correct": false}, {"id": "b", "label": "Couverte uniquement si un contrat est en place", "is_correct": false}, {"id": "c", "label": "Obligatoire pour toutes les entreprises", "is_correct": false}, {"id": "d", "label": "Uniquement applicable aux contrats internationaux", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:271', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La police à tiers chargeur est :', '[{"id": "a", "label": "Souscrite par le propriétaire de la marchandise", "is_correct": false}, {"id": "b", "label": "Souscrite par le transporteur ou le commissionnaire", "is_correct": false}, {"id": "c", "label": "Souscrite par l''assureur directement", "is_correct": false}, {"id": "d", "label": "Obligatoire pour tous les transporteur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:272', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une entreprise qui ne respecte pas les conditions d''accès à la profession peut :', '[{"id": "a", "label": "Se voir retirer son autorisation d''exercer", "is_correct": false}, {"id": "b", "label": "Recevoir une simple amende", "is_correct": false}, {"id": "c", "label": "Bénéficier d''une réduction de primes d''assurance", "is_correct": false}, {"id": "d", "label": "Continuer à exercer sans changement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:273', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les denrées périssables :', '[{"id": "a", "label": "Sont systématiquement couvertes par la police de base", "is_correct": false}, {"id": "b", "label": "Ne sont jamais couvertes par l''assurance marchandise", "is_correct": false}, {"id": "c", "label": "Nécessitent une garantie spéciale pour être assurées", "is_correct": false}, {"id": "d", "label": "Sont couvertes par la garantie « tous risques »", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:274', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une entreprise peut perdre son honorabilité si :', '[{"id": "a", "label": "Elle ne paie pas ses primes d''assurance", "is_correct": false}, {"id": "b", "label": "Elle est condamnée pour des infractions graves", "is_correct": false}, {"id": "c", "label": "Elle dépasse le quota d''expéditions couvertes", "is_correct": false}, {"id": "d", "label": "Elle souscrit une police d''assurance internationale", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:275', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les sanctions pénales pour les infractions graves en matière de transport peuvent inclure :', '[{"id": "a", "label": "Une amende seulement", "is_correct": false}, {"id": "b", "label": "Une peine de prison. Page 58 sur 204", "is_correct": false}, {"id": "c", "label": "La suspension de l''assurance", "is_correct": false}, {"id": "d", "label": "La confiscation des marchandises", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:276', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La déclaration de valeur :', '[{"id": "a", "label": "Remplace l''assurance marchandise", "is_correct": false}, {"id": "b", "label": "Permet une réparation des dommages si la responsabilité du transporteur est reconnue", "is_correct": false}, {"id": "c", "label": "Couvre tous les risques", "is_correct": false}, {"id": "d", "label": "Est obligatoire pour chaque expédition", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:277', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''indemnité due en cas de retard est calculée sur la base :', '[{"id": "a", "label": "De la valeur totale du contrat de transport", "is_correct": false}, {"id": "b", "label": "Du prix du transport seulement", "is_correct": false}, {"id": "c", "label": "De la valeur des marchandises retardées", "is_correct": false}, {"id": "d", "label": "Du montant de la déclaration de valeur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:278', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de déclaration d''intérêt spécial à la livraison, le transporteur est tenu de :', '[{"id": "a", "label": "Remplacer la marchandise endommagée", "is_correct": false}, {"id": "b", "label": "Indemniser le préjudice au-delà du plafond d''indemnisation", "is_correct": false}, {"id": "c", "label": "Réduire le coût du transport", "is_correct": false}, {"id": "d", "label": "Assurer une livraison prioritaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:279', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La déclaration de valeur doit être faite :', '[{"id": "a", "label": "Avant le départ du transport", "is_correct": false}, {"id": "b", "label": "Au moment de la prise en charge des marchandises", "is_correct": false}, {"id": "c", "label": "Lors de la conclusion du contrat de transport", "is_correct": false}, {"id": "d", "label": "Après l''acceptation de la marchandise par le transporteur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:280', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de destruction de la marchandise imposée par le donneur d''ordre, l''indemnité peut être réduite de : Page 59 sur 204 :', '[{"id": "a", "label": "Un quart", "is_correct": false}, {"id": "b", "label": "Un tiers", "is_correct": false}, {"id": "c", "label": "La moitié", "is_correct": false}, {"id": "d", "label": "Deux tiers", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:281', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''assurance des marchandises transportées "magasin à magasin" couvre :', '[{"id": "a", "label": "La marchandise depuis le lieu d''origine jusqu''à la livraison finale", "is_correct": false}, {"id": "b", "label": "La marchandise uniquement pendant le transport terrestre", "is_correct": false}, {"id": "c", "label": "Les dommages uniquement à l''arrivée", "is_correct": false}, {"id": "d", "label": "La marchandise pendant le stockage uniquement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:282', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lorsque la responsabilité du transporteur est engagée pour une faute inexcusable, les limitations d''indemnisation :', '[{"id": "a", "label": "Sont annulées", "is_correct": false}, {"id": "b", "label": "Sont doublées", "is_correct": false}, {"id": "c", "label": "Sont maintenues mais réduites", "is_correct": false}, {"id": "d", "label": "Sont applicables uniquement en cas de dol", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:283', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La responsabilité du transporteur pour avarie est établie :', '[{"id": "a", "label": "Dès la prise en charge des marchandises jusqu''à leur livraison", "is_correct": false}, {"id": "b", "label": "Lors de la livraison seulement", "is_correct": false}, {"id": "c", "label": "Après la livraison uniquement", "is_correct": false}, {"id": "d", "label": "Avant la prise en charge des marchandises", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:284', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lorsqu''un transporteur invoque une panne mécanique pour se dégager de sa responsabilité, cela est considéré comme :', '[{"id": "a", "label": "Une faute inexcusable", "is_correct": false}, {"id": "b", "label": "Une cause d''exonération", "is_correct": false}, {"id": "c", "label": "Une négligence", "is_correct": false}, {"id": "d", "label": "Un cas de force majeure. Page 60 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:285', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de manquement grave du transporteur, les sanctions applicables peuvent inclure :', '[{"id": "a", "label": "La suspension temporaire de la licence de transport", "is_correct": false}, {"id": "b", "label": "Une augmentation de la prime d''assurance uniquement", "is_correct": false}, {"id": "c", "label": "La confiscation des véhicules utilisés pour le transport", "is_correct": false}, {"id": "d", "label": "La réduction des responsabilités contractuelles uniquement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:286', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de retard du transport causé par des conditions météorologiques extrêmes, l''indemnité :', '[{"id": "a", "label": "Peut être réduite à zéro", "is_correct": false}, {"id": "b", "label": "Est augmentée de 50%", "is_correct": false}, {"id": "c", "label": "Peut être contestée en invoquant la force majeure", "is_correct": false}, {"id": "d", "label": "Est calculée sur la base des frais supplémentaires engagés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:287', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lorsque la déclaration d''intérêt spécial à la livraison est effectuée, le montant de l''indemnité :', '[{"id": "a", "label": "Ne peut jamais dépasser le plafond d''indemnisation fixé par le contrat-type", "is_correct": false}, {"id": "b", "label": "Peut être augmenté au-delà du plafond d''indemnisation", "is_correct": false}, {"id": "c", "label": "Est limité au prix du transport", "is_correct": false}, {"id": "d", "label": "Est réduit de moitié par rapport à la valeur déclarée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:288', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Selon l''article L. 133 -1 du code de commerce, la responsabilité du voiturier pour avarie ne s''applique pas en cas de :', '[{"id": "a", "label": "Force majeure", "is_correct": false}, {"id": "b", "label": "Faute légère", "is_correct": false}, {"id": "c", "label": "Vol des marchandises", "is_correct": false}, {"id": "d", "label": "Incendie du véhicule de transport", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:289', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de perte totale d''une marchandise sans dépôt de plainte, l''indemnisation se base sur :', '[{"id": "a", "label": "La valeur HT de la marchandise. Page 61 sur 204", "is_correct": false}, {"id": "b", "label": "Le montant de la déclaration de valeur", "is_correct": false}, {"id": "c", "label": "La valeur TTC de la marchandise", "is_correct": false}, {"id": "d", "label": "Le montant de l''assurance de la marchandise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:290', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''indemnité due en cas de retard est calculée :', '[{"id": "a", "label": "En fonction des frais supplémentaires de stockage", "is_correct": false}, {"id": "b", "label": "Sur la base du prix du transport uniquement", "is_correct": false}, {"id": "c", "label": "En ajoutant une pénalité par jour de retard", "is_correct": false}, {"id": "d", "label": "Selon la valeur des marchandises", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:291', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La déclaration de valeur permet de :', '[{"id": "a", "label": "Réduire le coût du transport", "is_correct": false}, {"id": "b", "label": "Augmenter le plafond d''indemnisation en cas de perte ou d''avarie", "is_correct": false}, {"id": "c", "label": "Éviter les frais d''assurance supplémentaires", "is_correct": false}, {"id": "d", "label": "Assurer une livraison plus rapide", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:292', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La réduction de l''indemnité due en cas de destruction de la marchandise imposée par le donneur d''ordre :', '[{"id": "a", "label": "Est de 10%", "is_correct": false}, {"id": "b", "label": "Est de 20%", "is_correct": false}, {"id": "c", "label": "Est de 30%", "is_correct": false}, {"id": "d", "label": "Est de 50%", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:293', false) ON CONFLICT DO NOTHING;
