  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour une déclaration de valeur, le montant doit être : Page 62 sur 204 :', '[{"id": "a", "label": "Payé au transporteur au moment de la prise en charge", "is_correct": false}, {"id": "b", "label": "Inclus dans le prix du transport", "is_correct": false}, {"id": "c", "label": "Payé au moment de la livraison", "is_correct": false}, {"id": "d", "label": "Subordonné au paiement d''un prix convenu", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:295', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de fausse déclaration de valeur, le transporteur peut :', '[{"id": "a", "label": "Refuser toute indemnisation", "is_correct": false}, {"id": "b", "label": "Exiger un paiement supplémentaire pour couvrir le montant incorrect", "is_correct": false}, {"id": "c", "label": "Limiter l''indemnisation au montant effectivement assuré", "is_correct": false}, {"id": "d", "label": "Augmenter le plafond d''indemnisation", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:296', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La responsabilité du transporteur est réduite en cas de :', '[{"id": "a", "label": "Faute lourde du donneur d''ordre", "is_correct": false}, {"id": "b", "label": "Délai de livraison excédé", "is_correct": false}, {"id": "c", "label": "Marchandise périssable", "is_correct": false}, {"id": "d", "label": "Conditions de transport inadéquates", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:297', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les plafonds d''indemnisation pour avarie sont généralement calculés :', '[{"id": "a", "label": "Sur la base de la valeur des marchandises après avarie", "is_correct": false}, {"id": "b", "label": "Sur la base de la valeur initiale déclarée", "is_correct": false}, {"id": "c", "label": "Sur la base du coût du transport", "is_correct": false}, {"id": "d", "label": "En fonction du type de dommage", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:298', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lors de la destruction de marchandises en cas de sinistre, le transporteur est responsable :', '[{"id": "a", "label": "De l''intégralité des dommages", "is_correct": false}, {"id": "b", "label": "Si la destruction est causée par une négligence", "is_correct": false}, {"id": "c", "label": "En cas de dol ou de faute inexcusable", "is_correct": false}, {"id": "d", "label": "Des dommages indirects uniquement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:298', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de destruction de la marchandise, la réduction de l''indemnité s''applique si : Page 63 sur 204 :', '[{"id": "a", "label": "La destruction est ordonnée par le donneur d''ordre", "is_correct": false}, {"id": "b", "label": "La marchandise est périssable", "is_correct": false}, {"id": "c", "label": "La marchandise est de valeur élevée", "is_correct": false}, {"id": "d", "label": "Le transporteur est en faute", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:299', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lorsqu''un transporteur ne peut prouver une exonération de responsabilité, il doit :', '[{"id": "a", "label": "Réduire le montant de l''indemnité", "is_correct": false}, {"id": "b", "label": "Assumer l''indemnisation dans les limites du contrat", "is_correct": false}, {"id": "c", "label": "Négocier avec le donneur d''ordre pour un accord", "is_correct": false}, {"id": "d", "label": "Payer une pénalité supplémentaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:300', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas d''absence de déclaration de valeur, le transporteur est responsable :', '[{"id": "a", "label": "Jusqu''à un montant fixe déterminé par la loi", "is_correct": false}, {"id": "b", "label": "Selon les limites prévues par le contrat-type", "is_correct": false}, {"id": "c", "label": "Pour le montant total de la marchandise", "is_correct": false}, {"id": "d", "label": "Uniquement en cas de négligence avérée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:301', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La déclaration de valeur doit être :', '[{"id": "a", "label": "Effectuée uniquement en cas de marchandises de haute valeur", "is_correct": false}, {"id": "b", "label": "Faite en respectant un format spécifique convenu avec le transporteur", "is_correct": false}, {"id": "c", "label": "Fournie en tout temps, peu importe la valeur de la marchandise", "is_correct": false}, {"id": "d", "label": "Accompagnée d''un reçu de paiement pour être valide", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:302', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''indemnité en cas d''atteinte à la marchandise est calculée sur la base de :', '[{"id": "a", "label": "La valeur de remplacement", "is_correct": false}, {"id": "b", "label": "La valeur au jour de la livraison", "is_correct": false}, {"id": "c", "label": "La valeur à la date de la perte ou avarie", "is_correct": false}, {"id": "d", "label": "Le coût de réparation uniquement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:303', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un retard causé par une grève des conducteurs est généralement :', '[{"id": "a", "label": "Considéré comme une cause d''exonération. Page 64 sur 204", "is_correct": false}, {"id": "b", "label": "Considéré comme une négligence du transporteur", "is_correct": false}, {"id": "c", "label": "Évalué pour une indemnité supplémentaire", "is_correct": false}, {"id": "d", "label": "Non couvert par les contrats de transport standard", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:304', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lorsqu''un transporteur invoque un cas d''exonération, il doit prouver :', '[{"id": "a", "label": "Que l''événement était imprévisible et inévitable", "is_correct": false}, {"id": "b", "label": "Que les marchandises étaient correctement emballées", "is_correct": false}, {"id": "c", "label": "Que la déclaration de valeur a été correctement remplie", "is_correct": false}, {"id": "d", "label": "Que la marchandise a été bien entretenue avant le transport", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:304', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas d''indemnisation pour perte totale, le transporteur peut :', '[{"id": "a", "label": "Refuser d''indemniser sans preuve de la perte", "is_correct": false}, {"id": "b", "label": "Offrir une indemnisation basée sur la valeur de remplacement", "is_correct": false}, {"id": "c", "label": "Payer uniquement la valeur des marchandises sans TVA", "is_correct": false}, {"id": "d", "label": "Réduire l''indemnisation en fonction des frais de stockage", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:305', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La responsabilité du transporteur en cas de dommage aux marchandises est :', '[{"id": "a", "label": "Limité par le montant déclaré ou par le contrat", "is_correct": false}, {"id": "b", "label": "Illimitée sauf en cas de force majeure", "is_correct": false}, {"id": "c", "label": "Réduite par le montant de la prime d''assurance", "is_correct": false}, {"id": "d", "label": "Déterminée uniquement par les conditions météorologiques", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:306', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La validité de la déclaration de valeur est conditionnée par :', '[{"id": "a", "label": "La remise d''une preuve de paiement", "is_correct": false}, {"id": "b", "label": "La soumission au transporteur au plus tard au moment de la conclusion du contrat", "is_correct": false}, {"id": "c", "label": "La signature d''un accord supplémentaire", "is_correct": false}, {"id": "d", "label": "L''acceptation de la marchandise par le destinataire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:307', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de faute lourde, les limitations d''indemnisation :', '[{"id": "a", "label": "Peuvent être appliquées avec une réduction de montant", "is_correct": false}, {"id": "b", "label": "Sont annulées, et l''indemnisation est totale. Page 65 sur 204", "is_correct": false}, {"id": "c", "label": "Sont doublées pour couvrir les frais supplémentaires", "is_correct": false}, {"id": "d", "label": "Sont augmentées pour inclure des frais supplémentaires", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:308', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''indemnité pour avarie est calculée sur la base de :', '[{"id": "a", "label": "La valeur de la marchandise après l''avarie", "is_correct": false}, {"id": "b", "label": "La valeur totale déclarée avant l''avarie", "is_correct": false}, {"id": "c", "label": "Le coût de réparation seulement", "is_correct": false}, {"id": "d", "label": "La valeur de remplacement dans le pays de destination", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:309', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La réduction de l''indemnité pour destruction imposée par le donneur d''ordre est applicable :', '[{"id": "a", "label": "En cas de négligence du transporteur", "is_correct": false}, {"id": "b", "label": "Lorsqu''une demande de destruction est faite par le destinataire", "is_correct": false}, {"id": "c", "label": "Lorsque la destruction est ordonnée sans possibilité de sauvetage", "is_correct": false}, {"id": "d", "label": "En cas de retard excessif", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:310', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour les marchandises perdues, l''indemnité est calculée :', '[{"id": "a", "label": "Sur la base de la valeur assurée TTC", "is_correct": false}, {"id": "b", "label": "Selon la valeur du contrat de transport", "is_correct": false}, {"id": "c", "label": "En fonction des frais de stockage", "is_correct": false}, {"id": "d", "label": "Basée sur la valeur déclarée HT", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:311', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lorsqu''une déclaration de valeur est faite, le transporteur est tenu de :', '[{"id": "a", "label": "Augmenter la prime d''assurance pour couvrir la valeur déclarée", "is_correct": false}, {"id": "b", "label": "Réduire le coût du transport en conséquence", "is_correct": false}, {"id": "c", "label": "Offrir une couverture d''indemnisation au -delà du plafond normal", "is_correct": false}, {"id": "d", "label": "Assurer une livraison dans un délai plus court", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:312', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les sanctions pour une faute lourde ou dol peuvent inclure :', '[{"id": "a", "label": "Une amende uniquement", "is_correct": false}, {"id": "b", "label": "La suspension ou la révocation de la licence de transport. Page 66 sur 204", "is_correct": false}, {"id": "c", "label": "L''augmentation des frais d''expédition pour le client", "is_correct": false}, {"id": "d", "label": "La confiscation de la marchandise en cas de non-paiement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:313', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de confusion entre un contrat de location et un contrat de transport, la différence principale est :', '[{"id": "a", "label": "La durée du contrat", "is_correct": false}, {"id": "b", "label": "Le montant payé pour le service", "is_correct": false}, {"id": "c", "label": "La maîtrise des opérations de transport", "is_correct": false}, {"id": "d", "label": "La présence d’un chauffeur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:314', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'N’est pas utilisé pour qualifier un contrat comme étant de location plutôt que de transport :', '[{"id": "a", "label": "L’inscription au registre des loueurs", "is_correct": false}, {"id": "b", "label": "La facturation en fonction du temps de mise à disposition", "is_correct": false}, {"id": "c", "label": "La présence d''un chauffeur fourni par le loueur", "is_correct": false}, {"id": "d", "label": "La précision sur le type de véhicule utilisé", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:315', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de panne du véhicule loué, le loueur est tenu de :', '[{"id": "a", "label": "Informer le locataire et prendre les mesures nécessaires pour réparer ou remplacer le véhicule", "is_correct": false}, {"id": "b", "label": "Rembourser le locataire pour les frais de réparation", "is_correct": false}, {"id": "c", "label": "Attendre que le locataire se charge de la réparation", "is_correct": false}, {"id": "d", "label": "Assumer les frais de stockage du véhicule jusqu’à sa réparation", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:316', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Selon l’article 5 du décret du 21 juin 2014, les opérations de conduite qui sont de la responsabilité du loueur :', '[{"id": "a", "label": "La préparation technique du véhicule et la protection contre le vol", "is_correct": false}, {"id": "b", "label": "Le chargement et le déchargement des marchandises", "is_correct": false}, {"id": "c", "label": "La détermination des itinéraires pour les livraisons", "is_correct": false}, {"id": "d", "label": "La rédaction des documents d''accompagnement des marchandises", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:317', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En matière de location avec chauffeur, le locataire doit : Page 67 sur 204 :', '[{"id": "a", "label": "Assumer la responsabilité des opérations de conduite", "is_correct": false}, {"id": "b", "label": "Fournir des instructions au chauffeur en matière de conduite", "is_correct": false}, {"id": "c", "label": "Assumer la maîtrise des opérations de transport", "is_correct": false}, {"id": "d", "label": "Réparer le véhicule en cas de panne", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:318', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les obligation qui ne relève pas de la responsabilité du locataire selon le décret du 21 juin 2014 :', '[{"id": "a", "label": "Restituer le véhicule en bon état", "is_correct": false}, {"id": "b", "label": "Assumer la responsabilité des opérations de transport", "is_correct": false}, {"id": "c", "label": "Assurer la protection contre le vol du véhicule", "is_correct": false}, {"id": "d", "label": "Établir les documents d''accompagnement des marchandises", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:319', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de dommages aux marchandises transportées, le locataire est responsable sauf si :', '[{"id": "a", "label": "Les dommages proviennent d''un vice caché du véhicule loué", "is_correct": false}, {"id": "b", "label": "Les dommages sont causés par une faute du loueur dans l’exécution des opérations de conduite", "is_correct": false}, {"id": "c", "label": "Les dommages sont causés par une panne du véhicule", "is_correct": false}, {"id": "d", "label": "Les dommages résultent d''une erreur dans les documents de transport", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:320', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat-type de location avec chauffeur a été modifié par le décret du 19 juin 2014 pour :', '[{"id": "a", "label": "Inclure une nouvelle définition des véhicules industriels", "is_correct": false}, {"id": "b", "label": "Réduire le montant des indemnités en cas de dommage", "is_correct": false}, {"id": "c", "label": "Modifier la durée des contrats de location", "is_correct": false}, {"id": "d", "label": "Changer les critères de qualification du contrat de location", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:321', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Selon le décret du 21 juin 2014, les dommages au véhicule du loueur doivent être pris en charge par :', '[{"id": "a", "label": "Le loueur, si les dommages proviennent d''un vice caché du véhicule loué", "is_correct": false}, {"id": "b", "label": "Le locataire, si les dommages sont dus à un manquement aux obligations contractuelles", "is_correct": false}, {"id": "c", "label": "L’assureur du véhicule loueur. Page 68 sur 204", "is_correct": false}, {"id": "d", "label": "Les tiers responsables des dommages", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:322', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de dommages aux biens du locataire (comme une remorque attachée), le loueur est responsable si :', '[{"id": "a", "label": "Le locataire prouve que les dommages proviennent d''un vice caché du véhicule loué", "is_correct": false}, {"id": "b", "label": "Les dommages sont causés par une faute du locataire dans l''exécution des opérations de transport", "is_correct": false}, {"id": "c", "label": "Le véhicule loué a été mal entretenu par le locataire", "is_correct": false}, {"id": "d", "label": "Les dommages sont dus à une défaillance de l’équipement de transport", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:323', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le délai de prescription pour les actions nées du contrat de location est :', '[{"id": "a", "label": "De deux ans à compter de la livraison des marchandises", "is_correct": false}, {"id": "b", "label": "D’un an à compter du jour où le dommage est constaté ou la marchandise aurait dû être livrée", "is_correct": false}, {"id": "c", "label": "De trois mois à compter du jour où le dommage a été constaté", "is_correct": false}, {"id": "d", "label": "De six mois à compter du jour de la prise en charge du véhicule", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:324', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’article 6 du décret du 21 juin 2014 précise que le locataire est responsable des opérations de transport, y compris :', '[{"id": "a", "label": "La vérification technique du véhicule", "is_correct": false}, {"id": "b", "label": "La gestion des documents de transport", "is_correct": false}, {"id": "c", "label": "La protection contre le vol du véhicule", "is_correct": false}, {"id": "d", "label": "La conduite proprement dite du véhicule", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:325', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de dommages causés aux tiers par le véhicule loué, le loueur est responsable si :', '[{"id": "a", "label": "Les dommages résultent d''une faute dans l''exécution des opérations de conduite", "is_correct": false}, {"id": "b", "label": "Le locataire ne fournit pas les informations nécessaires sur les marchandises", "is_correct": false}, {"id": "c", "label": "Les dommages sont causés par une panne du véhicule", "is_correct": false}, {"id": "d", "label": "Le véhicule est mal entretenu par le locataire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:326', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La responsabilité du locataire pour les dommages aux marchandises transportées peut être écartée si : Page 69 sur 204 :', '[{"id": "a", "label": "Les dommages sont causés par un vice caché du véhicule", "is_correct": false}, {"id": "b", "label": "Le locataire ne respecte pas les délais de livraison", "is_correct": false}, {"id": "c", "label": "Les dommages résultent d''une mauvaise préparation technique du véhicule", "is_correct": false}, {"id": "d", "label": "Le locataire ne peut pas fournir les documents de transport", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:327', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Lorsqu’un véhicule est loué avec chauffeur, le locataire est responsable de :', '[{"id": "a", "label": "La conduite du véhicule", "is_correct": false}, {"id": "b", "label": "La détermination des itinéraires et des points de chargement/déchargement", "is_correct": false}, {"id": "c", "label": "La maintenance du véhicule", "is_correct": false}, {"id": "d", "label": "La protection du véhicule contre le vol", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:328', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat-type de location de véhicule avec chauffeur est applicable si :', '[{"id": "a", "label": "Il n’existe pas de convention écrite entre les parties", "is_correct": false}, {"id": "b", "label": "Le véhicule est loué sans chauffeur", "is_correct": false}, {"id": "c", "label": "Le locataire fournit le chauffeur", "is_correct": false}, {"id": "d", "label": "Le contrat de location est conclu pour une durée indéterminée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:329', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de perte totale de la marchandise, le délai de prescription pour les actions est :', '[{"id": "a", "label": "Deux ans à partir de la date de la perte", "is_correct": false}, {"id": "b", "label": "Un an à compter du jour où la marchandise aurait dû être livrée", "is_correct": false}, {"id": "c", "label": "Six mois à partir du jour où le dommage est constaté", "is_correct": false}, {"id": "d", "label": "Trois ans à partir de la prise en charge du véhicule", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:330', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le loueur doit assumer la responsabilité des opérations de conduite, qui incluent :', '[{"id": "a", "label": "La conduite du véhicule uniquement", "is_correct": false}, {"id": "b", "label": "La manipulation des équipements spéciaux uniquement", "is_correct": false}, {"id": "c", "label": "La vérification du chargement avant le départ. Page 70 sur 204", "is_correct": false}, {"id": "d", "label": "La conduite, la protection contre le vol, la préparation technique et la manipulation des équipements spéciaux", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:331', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les documents de transport doivent être établis par :', '[{"id": "a", "label": "Le loueur dans tous les cas", "is_correct": false}, {"id": "b", "label": "Le locataire en cas de contrat de location", "is_correct": false}, {"id": "c", "label": "Le chauffeur pour les transports spécifiques", "is_correct": false}, {"id": "d", "label": "Le transporteur si le contrat est requalifié", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:332', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de dommages au matériel roulant du locataire, la responsabilité du loueur est engagée si :', '[{"id": "a", "label": "Les dommages résultent d’un vice caché du véhicule loué", "is_correct": false}, {"id": "b", "label": "Le locataire a mal utilisé le matériel", "is_correct": false}, {"id": "c", "label": "Les dommages sont causés par une panne du véhicule", "is_correct": false}, {"id": "d", "label": "Le locataire n’a pas payé le prix de la location", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:333', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat-type de location avec chauffeur remplace celui du :', '[{"id": "a", "label": "1er juillet 2014", "is_correct": false}, {"id": "b", "label": "17 avril 2002", "is_correct": false}, {"id": "c", "label": "1er janvier 2014", "is_correct": false}, {"id": "d", "label": "19 juin 2014", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:334', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de dommages causés par le véhicule loué à des tiers, le loueur doit :', '[{"id": "a", "label": "Indemniser le locataire pour les recours exercés contre lui", "is_correct": false}, {"id": "b", "label": "Réparer les dommages causés aux tiers", "is_correct": false}, {"id": "c", "label": "Fournir une couverture d’assurance au locataire", "is_correct": false}, {"id": "d", "label": "Assumer les frais de défense juridique", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:335', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le locataire est responsable de la perte et des dommages occasionnés au véhicule du loueur si :', '[{"id": "a", "label": "Les dommages sont causés par une défaillance du loueur", "is_correct": false}, {"id": "b", "label": "Le locataire ne respecte pas les obligations contractuelles. Page 71 sur 204", "is_correct": false}, {"id": "c", "label": "Les dommages résultent d’un vice caché du véhicule loué", "is_correct": false}, {"id": "d", "label": "Le véhicule est mal entretenu par le loueur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:336', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de non-respect des obligations de restitution du véhicule en bon état, la responsabilité du locataire est :', '[{"id": "a", "label": "Exclue si le dommage est causé par une défaillance du loueur", "is_correct": false}, {"id": "b", "label": "Limitée aux dommages causés par une faute dans l''exécution des opérations de conduite", "is_correct": false}, {"id": "c", "label": "Engagée pour les pertes et dommages occasionnés au véhicule du loueur", "is_correct": false}, {"id": "d", "label": "Couvert par l''assurance du loueur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:337', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat de location doit prévoir :', '[{"id": "a", "label": "Les points de chargement et de déchargement des marchandises", "is_correct": false}, {"id": "b", "label": "Les documents d’accompagnement des marchandises", "is_correct": false}, {"id": "c", "label": "Les modalités de restitution du véhicule en cas de panne", "is_correct": false}, {"id": "d", "label": "Les conditions d''assurance du véhicule", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:338', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat-type de location de véhicule avec chauffeur s''applique lorsque :', '[{"id": "a", "label": "Il existe une convention écrite entre les parties", "is_correct": false}, {"id": "b", "label": "Les parties ne prévoient pas de contrat spécifique", "is_correct": false}, {"id": "c", "label": "Le loueur est inscrit au registre du commerce", "is_correct": false}, {"id": "d", "label": "Le locataire assure la maintenance du véhicule", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:339', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de sous-traitance en cascade non autorisée, le sous-traitant :', '[{"id": "a", "label": "Ne peut être tenu responsable des marchandises", "is_correct": false}, {"id": "b", "label": "Doit informer immédiatement l''opérateur de transport", "is_correct": false}, {"id": "c", "label": "Peut choisir librement un nouveau sous-traitant", "is_correct": false}, {"id": "d", "label": "Est exonéré de toute responsabilité contractuelle", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:340', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le sous-traitant est libre de choisir :', '[{"id": "a", "label": "Les clients de l''opérateur de transport. Page 72 sur 204", "is_correct": false}, {"id": "b", "label": "Les moyens nécessaires pour effectuer la prestation", "is_correct": false}, {"id": "c", "label": "Les itinéraires de transport fixés par l''opérateur", "is_correct": false}, {"id": "d", "label": "Le volume de marchandises à transporter", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:341', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La responsabilité pénale de l’opérateur de transport est engagée lorsqu''il :', '[{"id": "a", "label": "Donne des instructions contraires au Code de la route", "is_correct": false}, {"id": "b", "label": "Réduit la rémunération du sous-traitant sans justification", "is_correct": false}, {"id": "c", "label": "Ne fournit pas les documents administratifs nécessaires", "is_correct": false}, {"id": "d", "label": "Sous-traite sans contrat écrit", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:342', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de manquements graves du sous-traitant, le contrat peut être résilié :', '[{"id": "a", "label": "Avec un préavis d’un mois", "is_correct": false}, {"id": "b", "label": "Après une mise en demeure", "is_correct": false}, {"id": "c", "label": "Immédiatement et sans indemnités", "is_correct": false}, {"id": "d", "label": "Après une période de négociation", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:343', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le sous-traitant doit prouver son inscription au registre des transporteurs en fournissant :', '[{"id": "a", "label": "Une attestation sur l''honneur", "is_correct": false}, {"id": "b", "label": "Une copie de la licence communautaire", "is_correct": false}, {"id": "c", "label": "Un extrait du registre du commerce", "is_correct": false}, {"id": "d", "label": "Une attestation fiscale", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:344', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le sous-traitant peut sous-traiter à un tiers en cas de :', '[{"id": "a", "label": "Volume de travail excédant les prévisions", "is_correct": false}, {"id": "b", "label": "Problème de santé du conducteur", "is_correct": false}, {"id": "c", "label": "Accord préalable de l''opérateur de transport", "is_correct": false}, {"id": "d", "label": "Retard important dans la livraison", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:345', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le prix de la prestation de sous-traitance est renégocié :', '[{"id": "a", "label": "En cas de changement de client. Page 73 sur 204", "is_correct": false}, {"id": "b", "label": "Chaque année à la date anniversaire du contrat", "is_correct": false}, {"id": "c", "label": "Chaque fois que le coût du carburant augmente", "is_correct": false}, {"id": "d", "label": "À la fin de chaque trimestre", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:346', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat de sous-traitance peut être résilié par l''une ou l''autre des parties :', '[{"id": "a", "label": "Uniquement en cas de manquement grave", "is_correct": false}, {"id": "b", "label": "À tout moment avec un préavis de 3 mois", "is_correct": false}, {"id": "c", "label": "Après 6 mois d''exécution sans préavis", "is_correct": false}, {"id": "d", "label": "Sans motif en cas de contrat à durée indéterminée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:347', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’opérateur de transport doit vérifier que le sous-traitant est :', '[{"id": "a", "label": "Propriétaire de tous les véhicules utilisés", "is_correct": false}, {"id": "b", "label": "En conformité avec la réglementation fiscale et sociale", "is_correct": false}, {"id": "c", "label": "Enregistré auprès de la chambre de commerce locale", "is_correct": false}, {"id": "d", "label": "Lié par un contrat avec un assureur spécifique", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:348', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat de sous-traitance est soumis à renégociation :', '[{"id": "a", "label": "En cas de modification des délais de livraison", "is_correct": false}, {"id": "b", "label": "Lorsqu’un nouveau client est intégré", "is_correct": false}, {"id": "c", "label": "Chaque année ou en cas de changement de conditions économiques", "is_correct": false}, {"id": "d", "label": "Tous les six mois sans exception", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:349', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le sous-traitant doit obtenir l’accord de l’opérateur de transport avant de :', '[{"id": "a", "label": "Modifier l’itinéraire de livraison", "is_correct": false}, {"id": "b", "label": "Changer le type de véhicule utilisé", "is_correct": false}, {"id": "c", "label": "Sous-traiter une partie de l’opération", "is_correct": false}, {"id": "d", "label": "Augmenter les coûts de transport", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:350', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’opérateur de transport doit fournir au sous-traitant :', '[{"id": "a", "label": "Un plan détaillé des itinéraires à suivre", "is_correct": false}, {"id": "b", "label": "Une estimation du volume de prestations à réaliser. Page 74 sur 204", "is_correct": false}, {"id": "c", "label": "Une copie de l''assurance des marchandises", "is_correct": false}, {"id": "d", "label": "Les détails financiers de chaque client", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:351', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’opérateur de transport peut résilier le contrat sans préavis si :', '[{"id": "a", "label": "Le sous-traitant refuse d’augmenter son volume de travail", "is_correct": false}, {"id": "b", "label": "Le sous-traitant sous-traite sans autorisation", "is_correct": false}, {"id": "c", "label": "Le client final change de conditions", "is_correct": false}, {"id": "d", "label": "Le coût des opérations devient trop élevé", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:352', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La responsabilité du sous-traitant est engagée en cas de :', '[{"id": "a", "label": "Retard de livraison dû à un accident", "is_correct": false}, {"id": "b", "label": "Non-conformité des marchandises livrées", "is_correct": false}, {"id": "c", "label": "Mauvaise gestion technique de son matériel", "is_correct": false}, {"id": "d", "label": "Changement de client en cours d’exécution", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:353', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de résiliation du contrat, les parties doivent :', '[{"id": "a", "label": "Continuer d’exécuter leurs obligations pendant le préavis", "is_correct": false}, {"id": "b", "label": "Arrêter immédiatement toute activité liée au contrat", "is_correct": false}, {"id": "c", "label": "Renégocier les termes de la résiliation", "is_correct": false}, {"id": "d", "label": "Payer une pénalité de résiliation anticipée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:354', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le sous-traitant doit informer l’opérateur de transport en cas de :', '[{"id": "a", "label": "Modification des conditions météorologiques", "is_correct": false}, {"id": "b", "label": "Incapacité à respecter les délais de livraison", "is_correct": false}, {"id": "c", "label": "Augmentation du coût du carburant", "is_correct": false}, {"id": "d", "label": "Changement d’itinéraire sans préavis", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:355', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le contrat de sous-traitance peut être conclu pour :', '[{"id": "a", "label": "Une durée indéterminée avec reconduction automatique", "is_correct": false}, {"id": "b", "label": "Une durée déterminée renouvelable uniquement par accord mutuel", "is_correct": false}, {"id": "c", "label": "Une prestation spécifique sans durée fixe. Page 75 sur 204", "is_correct": false}, {"id": "d", "label": "Une durée déterminée non renouvelable", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:356', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La responsabilité du sous-traitant peut être engagée si :', '[{"id": "a", "label": "Le véhicule utilisé n’est pas adapté au transport", "is_correct": false}, {"id": "b", "label": "Le client impose un changement de véhicule", "is_correct": false}, {"id": "c", "label": "L''opérateur ne respecte pas les termes du contrat", "is_correct": false}, {"id": "d", "label": "Les marchandises sont mal emballées par le client", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:357', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de force majeure, le sous-traitant doit :', '[{"id": "a", "label": "Payer une indemnité à l’opérateur de transport", "is_correct": false}, {"id": "b", "label": "Informer immédiatement l’opérateur de transport", "is_correct": false}, {"id": "c", "label": "Continuer l’exécution du contrat malgré les difficultés", "is_correct": false}, {"id": "d", "label": "Résilier le contrat sans préavis", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:358', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le commissionnaire de transport agit :', '[{"id": "a", "label": "En son propre nom et pour son compte", "is_correct": false}, {"id": "b", "label": "Au nom du transporteur public", "is_correct": false}, {"id": "c", "label": "Au nom du donneur d''ordre", "is_correct": false}, {"id": "d", "label": "Pour le compte du transporteur public", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:359', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les opérations de groupage consistent à :', '[{"id": "a", "label": "Regrouper des envois de plusieurs expéditeurs en un seul lot", "is_correct": false}, {"id": "b", "label": "Confier des marchandises à un transporteur public sans tri préalable", "is_correct": false}, {"id": "c", "label": "Organiser le transport de marchandises uniquement à destination internationale", "is_correct": false}, {"id": "d", "label": "Remettre les marchandises à différents commissionnaires", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:360', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le commissionnaire de transport est responsable :', '[{"id": "a", "label": "Uniquement des dommages causés par les transporteurs publics", "is_correct": false}, {"id": "b", "label": "Des marchandises uniquement en cas de faute du transporteur", "is_correct": false}, {"id": "c", "label": "Des opérations de transport en son propre nom et sous sa responsabilité", "is_correct": false}, {"id": "d", "label": "Des marchandises uniquement pendant le transport maritime. Page 76 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:361', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les opérations d''affrètement impliquent que le commissionnaire :', '[{"id": "a", "label": "Regroupe les marchandises avant de les remettre à un transporteur public", "is_correct": false}, {"id": "b", "label": "Confie des marchandises à un transporteur public sans groupage préalable", "is_correct": false}, {"id": "c", "label": "Prend en charge les colis à l''adresse du destinataire", "is_correct": false}, {"id": "d", "label": "Assure l''acheminement des marchandises par plusieurs transporteurs", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:362', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de dommage aux marchandises, le commissionnaire :', '[{"id": "a", "label": "N''est pas responsable si le transporteur est en faute", "is_correct": false}, {"id": "b", "label": "A une obligation de moyens envers le donneur d''ordre", "is_correct": false}, {"id": "c", "label": "Est responsable sauf en cas de force majeure", "is_correct": false}, {"id": "d", "label": "Peut se décharger de sa responsabilité sur le transporteur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:363', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les opérations de bureau de ville réalisées par un commissionnaire consistent à :', '[{"id": "a", "label": "Remettre des marchandises en un seul lot à un transporteur public", "is_correct": false}, {"id": "b", "label": "Regrouper les envois de plusieurs expéditeurs pour le transport", "is_correct": false}, {"id": "c", "label": "Prendre en charge des colis et les remettre séparément à des transporteurs", "is_correct": false}, {"id": "d", "label": "Organiser le transport maritime de marchandises", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:364', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le commissionnaire de transport assume une obligation de résultat, ce qui signifie :', '[{"id": "a", "label": "Il doit obtenir le meilleur prix pour le transport", "is_correct": false}, {"id": "b", "label": "Il est responsable du bon déroulement de l''acheminement des marchandises", "is_correct": false}, {"id": "c", "label": "Il n''est responsable que de la coordination entre les transporteurs", "is_correct": false}, {"id": "d", "label": "Il peut se dégager de sa responsabilité en cas de retard du transporteur", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:365', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans le cadre de l''organisation du transport, le commissionnaire :', '[{"id": "a", "label": "Ne peut confier les marchandises qu''à un seul transporteur", "is_correct": false}, {"id": "b", "label": "Doit assurer le transport uniquement par voie terrestre", "is_correct": false}, {"id": "c", "label": "Peut faire appel à plusieurs transporteurs pour l''acheminement des marchandises. Page 77 sur 204", "is_correct": false}, {"id": "d", "label": "Est responsable uniquement jusqu''à l''entrée sur le territoire national", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:366', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le commissionnaire peut être exonéré de sa responsabilité si :', '[{"id": "a", "label": "Le transport est retardé par des conditions météorologiques exceptionnelles", "is_correct": false}, {"id": "b", "label": "Le transporteur public fait faillite avant la livraison", "is_correct": false}, {"id": "c", "label": "Le client n''a pas fourni les informations correctes sur les marchandises", "is_correct": false}, {"id": "d", "label": "Les marchandises sont endommagées par une grève des transporteurs", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:367', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les activités de commissionnaire pour le transport routier de marchandises incluent :', '[{"id": "a", "label": "Le contrôle des marchandises à la douane", "is_correct": false}, {"id": "b", "label": "L''affrètement des envois sans groupage préalable", "is_correct": false}, {"id": "c", "label": "La livraison directe au destinataire final", "is_correct": false}, {"id": "d", "label": "Le stockage des marchandises avant expédition. Page 78 sur 204 Module D L’ENTREPRISE ET SON ACTIVITÉ FINANCIÉRE", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qcm:368', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le coût de revient d’un véhicule comprend :', '[{"id": "a", "label": "Uniquement les charges variables liées à son utilisation", "is_correct": false}, {"id": "b", "label": "Les coûts directs et indirects supportés par l’entreprise", "is_correct": false}, {"id": "c", "label": "Les dépenses engagées uniquement pour l’achat du véhicule", "is_correct": false}, {"id": "d", "label": "Les frais de carburant et d’entretien seulement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:369', false) ON CONFLICT DO NOTHING;
