  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le mode de calcul le plus précis pour la prime d’assurance d’un véhicule est :', '[{"id": "a", "label": "Calculé pour l’ensemble du parc", "is_correct": false}, {"id": "b", "label": "Calculé sur un véhicule donné", "is_correct": false}, {"id": "c", "label": "Calculé sur la base des bénéfices annuels", "is_correct": false}, {"id": "d", "label": "Calculé sur la consommation de carburant. Page 85 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:407', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour une entreprise en situation de forte concurrence, un taux de marge commerciale stable mais inférieur à celui du marché peut indiquer :', '[{"id": "a", "label": "Une meilleure gestion des coûts fixes", "is_correct": false}, {"id": "b", "label": "Une surévaluation des prix de vente", "is_correct": false}, {"id": "c", "label": "Une sous-estimation des coûts d''achat ou des prix de vente trop bas", "is_correct": false}, {"id": "d", "label": "Une baisse du chiffre d''affaires", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:408', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise de transport décide de sous-traiter une partie de ses services, cela peut-affecter son calcul de la marge commerciale :', '[{"id": "a", "label": "En augmentant directement le chiffre d''affaires HT", "is_correct": false}, {"id": "b", "label": "En réduisant les coûts fixes", "is_correct": false}, {"id": "c", "label": "En modifiant le coût de revient HT", "is_correct": false}, {"id": "d", "label": "En augmentant la TVA collectée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:409', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une entreprise réalise une marge commerciale positive mais enregistre une perte nette. La cause la plus probable est :', '[{"id": "a", "label": "Une mauvaise estimation du chiffre d''affaires HT", "is_correct": false}, {"id": "b", "label": "Une sous-évaluation des coûts d''achat", "is_correct": false}, {"id": "c", "label": "Une mauvaise gestion des remises clients", "is_correct": false}, {"id": "d", "label": "Des frais fixes et généraux trop élevés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:410', false) ON CONFLICT DO NOTHING;
