  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour une entreprise de transport, le calcul de la marge commerciale peut être complexe en raison de :', '[{"id": "a", "label": "La variabilité des prix de vente", "is_correct": false}, {"id": "b", "label": "La stabilité des coûts fixes", "is_correct": false}, {"id": "c", "label": "Les fluctuations des coûts d''exploitation, comme le carburant", "is_correct": false}, {"id": "d", "label": "Les remises saisonnières", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:412', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise décide de réduire ses coûts d''achat grâce à une production en interne, cela impactera principalement :', '[{"id": "a", "label": "Le chiffre d''affaires HT", "is_correct": false}, {"id": "b", "label": "Les frais fixes", "is_correct": false}, {"id": "c", "label": "La marge commerciale", "is_correct": false}, {"id": "d", "label": "La TVA Page 86 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:413', false) ON CONFLICT DO NOTHING;
