  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le calcul de la marge commerciale peut être influencé par :', '[{"id": "a", "label": "Le taux de TVA appliqué sur les produits", "is_correct": false}, {"id": "b", "label": "Les variations de stock au cours de l''exercice comptable", "is_correct": false}, {"id": "c", "label": "La localisation géographique de l''entreprise", "is_correct": false}, {"id": "d", "label": "Le nombre d''employés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:418', false) ON CONFLICT DO NOTHING;
