  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise de transport a un chiffre d''affaires HT de 1 000 000 € et un coût de revient HT de 800 000 €, son taux de marge commerciale est :', '[{"id": "a", "label": "2 %", "is_correct": false}, {"id": "b", "label": "12 %", "is_correct": false}, {"id": "c", "label": "20 %", "is_correct": false}, {"id": "d", "label": "200 %", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:420', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour calculer la marge commerciale d''une entreprise, il est important de :', '[{"id": "a", "label": "Inclure la TVA dans le calcul", "is_correct": false}, {"id": "b", "label": "Calculer en hors taxe pour éliminer la TVA", "is_correct": false}, {"id": "c", "label": "Ignorer les coûts fixes", "is_correct": false}, {"id": "d", "label": "Ajouter les frais de transport au prix de vente", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:421', false) ON CONFLICT DO NOTHING;
