  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La marge brute d''une entreprise de transport est égale à :', '[{"id": "a", "label": "La différence entre le chiffre d''affaires HT et les taxes", "is_correct": false}, {"id": "b", "label": "La différence entre le chiffre d''affaires HT et le coût de revient HT", "is_correct": false}, {"id": "c", "label": "La somme des bénéfices nets", "is_correct": false}, {"id": "d", "label": "Le total des frais de fonctionnement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:423', false) ON CONFLICT DO NOTHING;
