  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une entreprise peut réduire son seuil de rentabilité :', '[{"id": "a", "label": "En augmentant ses charges fixes", "is_correct": false}, {"id": "b", "label": "En augmentant sa marge sur coût variable (MSCV)", "is_correct": false}, {"id": "c", "label": "En augmentant ses coûts variables", "is_correct": false}, {"id": "d", "label": "En diminuant ses prix de vente", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:427', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si le prix de vente par kilomètre augmente tout en maintenant des coûts fixes constants, l’effet direct sur le seuil de rentabilité en kilomètres est :', '[{"id": "a", "label": "Augmentation du seuil de rentabilité", "is_correct": false}, {"id": "b", "label": "Diminution du seuil de rentabilité", "is_correct": false}, {"id": "c", "label": "Aucune modification", "is_correct": false}, {"id": "d", "label": "Augmentation du point mort", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:428', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une diminution du coût variable par kilomètre, avec un prix de vente constant, entraînera :', '[{"id": "a", "label": "Une augmentation du seuil de rentabilité", "is_correct": false}, {"id": "b", "label": "Une diminution des charges fixes", "is_correct": false}, {"id": "c", "label": "Une augmentation de la MSCV et une diminution du seuil de rentabilité", "is_correct": false}, {"id": "d", "label": "Une augmentation du coefficient de rentabilité", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:429', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le point mort est un indicateur qui exprime :', '[{"id": "a", "label": "Le nombre de jours nécessaires pour atteindre le seuil de rentabilité", "is_correct": false}, {"id": "b", "label": "Le chiffre d’affaires minimum annuel", "is_correct": false}, {"id": "c", "label": "Le coût total des charges fixes", "is_correct": false}, {"id": "d", "label": "Le nombre de kilomètres minimum à parcourir pour être rentable", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:430', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une entreprise avec un coefficient de rentabilité élevé indique que :', '[{"id": "a", "label": "Les charges fixes sont faibles", "is_correct": false}, {"id": "b", "label": "Les charges variables sont proportionnellement élevées par rapport au chiffre d’affaires", "is_correct": false}, {"id": "c", "label": "Le seuil de rentabilité est facilement atteignable", "is_correct": false}, {"id": "d", "label": "Le prix de vente au kilomètre est très bas Page 89 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:431', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise augmente ses charges fixes tout en maintenant ses prix de vente et ses coûts variables constants, cela entraînera :', '[{"id": "a", "label": "Une diminution du point mort", "is_correct": false}, {"id": "b", "label": "Une augmentation de la MSCV", "is_correct": false}, {"id": "c", "label": "Une augmentation du seuil de rentabilité", "is_correct": false}, {"id": "d", "label": "Une diminution du coefficient de rentabilité", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:432', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de diminution du chiffre d’affaires avec des coûts fixes constants, l’effet sur le seuil de rentabilité sera :', '[{"id": "a", "label": "Diminution du seuil de rentabilité", "is_correct": false}, {"id": "b", "label": "Augmentation du seuil de rentabilité", "is_correct": false}, {"id": "c", "label": "Augmentation de la MSCV", "is_correct": false}, {"id": "d", "label": "Aucune modification", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:433', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise souhaite maintenir son seuil de rentabilité tout en augmentant ses charges fixes, elle devrait :', '[{"id": "a", "label": "Augmenter sa MSCV", "is_correct": false}, {"id": "b", "label": "Augmenter ses prix de vente proportionnellement aux coûts fixes", "is_correct": false}, {"id": "c", "label": "Diminuer ses coûts variables", "is_correct": false}, {"id": "d", "label": "Réduire le nombre de kilomètres parcourus", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:435', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour une entreprise de transport, une augmentation des frais de carburant affectera principalement :', '[{"id": "a", "label": "Le prix de vente au kilomètre", "is_correct": false}, {"id": "b", "label": "Le coût variable par kilomètre", "is_correct": false}, {"id": "c", "label": "Les charges fixes", "is_correct": false}, {"id": "d", "label": "Le coefficient de rentabilité", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:436', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Page 90 sur 204 Un coefficient de rentabilité proche de 1 signifie que :', '[{"id": "a", "label": "Les charges fixes sont à peine couvertes par la marge sur coût variable", "is_correct": false}, {"id": "b", "label": "Le chiffre d’affaires est largement supérieur aux charges variables", "is_correct": false}, {"id": "c", "label": "L’entreprise réalise un bénéfice significatif", "is_correct": false}, {"id": "d", "label": "Les coûts fixes sont négligeables", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:437', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise réduit ses charges variables tout en maintenant ses charges fixes constantes, cela aura pour effet :', '[{"id": "a", "label": "Une augmentation du seuil de rentabilité b Une diminution du seuil de rentabilité", "is_correct": false}, {"id": "c", "label": "Une augmentation du point mort", "is_correct": false}, {"id": "d", "label": "Une diminution de la MSCV", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:438', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour une entreprise de transport, le seuil de rentabilité en kilomètres est atteint lorsque :', '[{"id": "a", "label": "Les recettes couvrent l’ensemble des coûts fixes et variables sur la distance parcourue", "is_correct": false}, {"id": "b", "label": "Le prix de vente au kilomètre est égal aux charges fixes", "is_correct": false}, {"id": "c", "label": "Les coûts variables sont supérieurs au chiffre d’affaires", "is_correct": false}, {"id": "d", "label": "Le point mort est atteint après 100 jours", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:439', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le bilan comptable permet de :', '[{"id": "a", "label": "Évaluer la rentabilité à court terme de l''entreprise", "is_correct": false}, {"id": "b", "label": "Reprendre les flux de trésorerie de l''année", "is_correct": false}, {"id": "c", "label": "Visualiser les actifs et passifs à un moment donné", "is_correct": false}, {"id": "d", "label": "Mesurer uniquement les dettes financières", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:440', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un compte de résultat sert principalement à :', '[{"id": "a", "label": "Calculer l''excédent brut d''exploitation", "is_correct": false}, {"id": "b", "label": "Suivre l''évolution des immobilisations Page 91 sur 204", "is_correct": false}, {"id": "c", "label": "Comparer les flux d''entrée et de sortie de trésorerie", "is_correct": false}, {"id": "d", "label": "Représenter la situation financière instantanée de l''entreprise", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:441', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le livre-journal enregistre :', '[{"id": "a", "label": "Les actifs immobilisés", "is_correct": false}, {"id": "b", "label": "Les transactions chronologiquement", "is_correct": false}, {"id": "c", "label": "Les écritures de clôture uniquement", "is_correct": false}, {"id": "d", "label": "Les comptes de résultat de l’exercice", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:442', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les Soldes Intermédiaires de Gestion (SIG) :', '[{"id": "a", "label": "Sont obligatoires pour les petites entreprises", "is_correct": false}, {"id": "b", "label": "Permettent d''évaluer la trésorerie disponible", "is_correct": false}, {"id": "c", "label": "Facilitent l''analyse de la performance économique", "is_correct": false}, {"id": "d", "label": "Sont des documents fiscaux imposés par l’administration", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:443', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le compte de résultat :', '[{"id": "a", "label": "Présente la situation financière à un instant donné", "is_correct": false}, {"id": "b", "label": "Permet d’analyser les flux de trésorerie", "is_correct": false}, {"id": "c", "label": "Reprend les produits et charges de l''exercice pour déterminer le résultat", "is_correct": false}, {"id": "d", "label": "Inclut les opérations d''investissement de l''année", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:444', false) ON CONFLICT DO NOTHING;
