  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La marge commerciale brute est calculée comme suit :', '[{"id": "a", "label": "Chiffre d’affaires – Consommables", "is_correct": false}, {"id": "b", "label": "Chiffre d’affaires – Charges externes", "is_correct": false}, {"id": "c", "label": "Valeur ajoutée – Frais généraux", "is_correct": false}, {"id": "d", "label": "Production de l’exercice – Coût de revient", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:446', false) ON CONFLICT DO NOTHING;
