  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''excédent brut d’exploitation (EBE) est défini comme :', '[{"id": "a", "label": "Valeur ajoutée + Subventions d''exploitation – Salaires", "is_correct": false}, {"id": "b", "label": "Valeur ajoutée – (Salaires + Impôts + Taxes)", "is_correct": false}, {"id": "c", "label": "Chiffre d’affaires – Coût de revient", "is_correct": false}, {"id": "d", "label": "Production de l’exercice – Charges externes", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:448', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le résultat brut d’exploitation (REX) est calculé en :', '[{"id": "a", "label": "Soustrayant les amortissements du résultat d’exploitation", "is_correct": false}, {"id": "b", "label": "Additionnant les subventions d’exploitation au résultat d’exploitation", "is_correct": false}, {"id": "c", "label": "Soustrayant les dotations aux amortissements et provisions de l’EBE", "is_correct": false}, {"id": "d", "label": "Ajoutant les produits exceptionnels au résultat courant avant impôt", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:449', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le résultat exceptionnel est calculé comme suit :', '[{"id": "a", "label": "Résultat courant avant impôt + Charges exceptionnelles", "is_correct": false}, {"id": "b", "label": "Produits exceptionnels – Charges exceptionnelles", "is_correct": false}, {"id": "c", "label": "Résultat brut d’exploitation – Produits exceptionnels", "is_correct": false}, {"id": "d", "label": "Résultat net – Résultat courant avant impôt", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:450', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Page 93 sur 204 Si l’EBE est négatif, cela signifie :', '[{"id": "a", "label": "Une insuffisance brute d’exploitation", "is_correct": false}, {"id": "b", "label": "Une excellente performance économique", "is_correct": false}, {"id": "c", "label": "Un excédent dans la production de l’exercice", "is_correct": false}, {"id": "d", "label": "Un résultat exceptionnel favorable", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:451', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L’EBE est un indicateur clé pour :', '[{"id": "a", "label": "Comparer les performances d’exploitation entre entreprises", "is_correct": false}, {"id": "b", "label": "Mesurer l''impact des opérations exceptionnelles", "is_correct": false}, {"id": "c", "label": "Évaluer la rentabilité nette après impôt", "is_correct": false}, {"id": "d", "label": "Déterminer les produits financiers", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:452', false) ON CONFLICT DO NOTHING;
