  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le délai de paiement maximum légal sans accord spécifique entre les parties est :', '[{"id": "a", "label": "30 jours à compter de la date d''émission de la facture", "is_correct": false}, {"id": "b", "label": "45 jours à compter de la fin du mois de facturation", "is_correct": false}, {"id": "c", "label": "60 jours à compter de la date d''émission de la facture", "is_correct": false}, {"id": "d", "label": "45 jours à compter de la date de la facture", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:457', false) ON CONFLICT DO NOTHING;
