  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour les créances clients, la formule du délai moyen de paiement en jours est :', '[{"id": "a", "label": "(Créances clients / Chiffre d’affaires TTC) × 365 jours", "is_correct": false}, {"id": "b", "label": "(Créances clients / Chiffre d’affaires TTC) × 360 jours", "is_correct": false}, {"id": "c", "label": "(Dettes fournisseurs / Chiffre d’affaires TTC) × 365 jours", "is_correct": false}, {"id": "d", "label": "(Dettes fournisseurs / Achats TTC) × 360 jours Page 95 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:459', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le calcul du délai de paiement des fournisseurs est basé sur :', '[{"id": "a", "label": "Le montant des ventes", "is_correct": false}, {"id": "b", "label": "Les achats TTC et autres achats externes TTC", "is_correct": false}, {"id": "c", "label": "Les créances clients uniquement", "is_correct": false}, {"id": "d", "label": "Les dettes fiscales et sociales", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:460', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les intérêts de retard en cas de non-paiement peuvent être appliqués en vertu de :', '[{"id": "a", "label": "L''article L441-10-I du Code de commerce", "is_correct": false}, {"id": "b", "label": "L''article L441-16 du Code de commerce", "is_correct": false}, {"id": "c", "label": "L''article L441-14 du Code de commerce", "is_correct": false}, {"id": "d", "label": "L''article L441-12 du Code de commerce Page 96 sur 204 Module E L’ENTREPRISE ET SES SALARIÉS", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qcm:461', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans les entreprises d''au moins 50 salariés, le règlement intérieur, établi par l''employeur doit :', '[{"id": "a", "label": "Concerner les qualifications et rémunérations des salariés", "is_correct": false}, {"id": "b", "label": "Concerner les règles d''hygiène et de sécurité applicables dans l''entreprise", "is_correct": false}, {"id": "c", "label": "Être transmis aux chambres syndicales des syndicats représentés dans l''entreprise", "is_correct": false}, {"id": "d", "label": "Être soumis pour avis à la Commission paritaire régionale interprofessionnelle (CPRI) avant sa mise en application", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:462', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un salarié déclaré inapte à son poste de travail par le médecin du travail doit : a. être considéré comme démissionnaire :', '[{"id": "b", "label": "Être licencié pour cas de force majeure", "is_correct": false}, {"id": "c", "label": "Être déclaré invalide", "is_correct": false}, {"id": "d", "label": "Être licencié pour inaptitude en cas d''impossibilité de reclassement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:463', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un licenciement économique individuel d''un salarié ne peut avoir lieu sans :', '[{"id": "a", "label": "La consultation préalable des représentants du personnel sur le licenciement", "is_correct": false}, {"id": "b", "label": "Un plan social", "is_correct": false}, {"id": "c", "label": "Un entretien préalable", "is_correct": false}, {"id": "d", "label": "Une autorisation administrative", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:464', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un contrat de travail à durée déterminée est requalifié en contrat à durée indéterminée lorsque :', '[{"id": "a", "label": "Le contrat ne précise pas de période d''essai", "is_correct": false}, {"id": "b", "label": "Le motif pour lequel il est conclu n''est pas indiqué", "is_correct": false}, {"id": "c", "label": "Le contrat est rompu avant le terme", "is_correct": false}, {"id": "d", "label": "Il est conclu pour remplacer un salarié absent", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:465', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le comité social et économique (CSE) doit être constitué au sein de toute entreprise, à partir de : Page 97 sur 204 :', '[{"id": "a", "label": "11 salariés pendant 12 mois consécutifs", "is_correct": false}, {"id": "b", "label": "25 salariés pendant 12 mois consécutifs", "is_correct": false}, {"id": "c", "label": "50 salariés pendant 12 mois consécutifs", "is_correct": false}, {"id": "d", "label": "100 salariés pendant 12 mois consécutifs", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:466', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour les élections de représentants du personnel, en cas d''absence de candidature de syndicats reconnus représentatifs, le chef d''entreprise doit :', '[{"id": "a", "label": "Renoncer aux élections", "is_correct": false}, {"id": "b", "label": "Organiser un second tour dans un délai d''1 mois", "is_correct": false}, {"id": "c", "label": "Prévenir l''inspecteur du travail", "is_correct": false}, {"id": "d", "label": "Organiser un second tour dans un délai de 15 jours", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:467', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de licenciement économique d''un conducteur, l''employeur doit observer un délai de réflexion minimum entre l''entretien préalable et la notification de la lettre de licenciement au salarié. Ce délai minimal sera de :', '[{"id": "a", "label": "1 jour", "is_correct": false}, {"id": "b", "label": "4 jours", "is_correct": false}, {"id": "c", "label": "7 jours", "is_correct": false}, {"id": "d", "label": "15 jours", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:468', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Au moment de la rupture du contrat de travail, lors d''un licenciement pour faute lourde, l''employeur doit remettre obligatoirement au salarié :', '[{"id": "a", "label": "Une attestation France travail signée pour lui permettre de faire valoir ses droits aux allocations chômage", "is_correct": false}, {"id": "b", "label": "Une indemnité compensatrice correspondant à l''ensemble des congés payés qu''il a acquis", "is_correct": false}, {"id": "c", "label": "Une indemnité compensatrice de préavis", "is_correct": false}, {"id": "d", "label": "Un document d''information sur le montant des droits à formation acquis par ce salarié sur son compte personnel de formation (CPF)", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:469', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Avant toute embauche, il y a lieu de :', '[{"id": "a", "label": "Prévenir l''inspecteur du travail", "is_correct": false}, {"id": "b", "label": "Faire une déclaration préalable à l''embauche (DPAE) auprès de l''URSSAF ; Page 98 sur 204", "is_correct": false}, {"id": "c", "label": "Établir un contrat de travail", "is_correct": false}, {"id": "d", "label": "Adresser copie du contrat de travail à l''inspection du travail", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:470', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''absence de contrat écrit à l''issue d''un contrat à durée déterminée, si le salarié est maintenu dans l''entreprise, entraîne :', '[{"id": "a", "label": "La rupture du contrat", "is_correct": false}, {"id": "b", "label": "Le renouvellement systématique pour une même durée", "is_correct": false}, {"id": "c", "label": "La régularisation par un écrit", "is_correct": false}, {"id": "d", "label": "Un contrat réputé tacitement à durée indéterminée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:471', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Sauf cas particulier, la durée maximale d''un contrat à durée déterminée conclu pour un accroissement temporaire d''activité est de :', '[{"id": "a", "label": "6 mois", "is_correct": false}, {"id": "b", "label": "12 mois", "is_correct": false}, {"id": "c", "label": "18 mois", "is_correct": false}, {"id": "d", "label": "24 mois", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:472', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le certificat de travail mentionne obligatoirement :', '[{"id": "a", "label": "Les dates d''entrée et de sortie", "is_correct": false}, {"id": "b", "label": "Le motif de la fin du contrat (rupture)", "is_correct": false}, {"id": "c", "label": "Une appréciation générale sur les qualités professionnelles", "is_correct": false}, {"id": "d", "label": "L''existence d''une clause de non-concurrence", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:473', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un salarié qui se trouve dans une situation dont il a un motif raisonnable de penser qu''elle comporte un risque pour sa vie ou sa santé, peut :', '[{"id": "a", "label": "Exercer uniquement son droit d''alerte", "is_correct": false}, {"id": "b", "label": "Exercer ses droits d''alerte et de retrait", "is_correct": false}, {"id": "c", "label": "Être sanctionné si le danger réel n''est pas prouvé", "is_correct": false}, {"id": "d", "label": "Exercer une action en référé devant le Conseil de prud''hommes", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:474', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'À la suite d’un accident du travail, un salarié est déclaré inapte à son emploi. L''employeur ne pouvant pas le reclasser doit : Page 99 sur 204 :', '[{"id": "a", "label": "Licencier le salarié pour motif économique", "is_correct": false}, {"id": "b", "label": "Solliciter la démission du salarié", "is_correct": false}, {"id": "c", "label": "Licencier le salarié et verser une indemnité spéciale de licenciement", "is_correct": false}, {"id": "d", "label": "Prononcer un licenciement pour faute grave", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:475', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''application d''une convention collective étendue est obligatoire :', '[{"id": "a", "label": "Uniquement pour les employeurs ayant signé la convention", "is_correct": false}, {"id": "b", "label": "Uniquement pour les employeurs qui ont demandé l''extension", "is_correct": false}, {"id": "c", "label": "Pour tous les employeurs exerçant les activités entrant dans son champ d''application", "is_correct": false}, {"id": "d", "label": "Pour les employeurs de la branche professionnelle concernée qui ont plus de 10 salariés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:476', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une convention collective de branche est un accord conclu entre :', '[{"id": "a", "label": "Les employeurs après consultation de l''inspection du travail", "is_correct": false}, {"id": "b", "label": "Le ministère du travail et les syndicats", "is_correct": false}, {"id": "c", "label": "Les représentants du personnel et les délégués syndicaux", "is_correct": false}, {"id": "d", "label": "Les organisations professionnelles d''employeurs et les organisations syndicales de salariés, représentatives au niveau de cette branche", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:477', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Sauf faute grave, le licenciement d''un conducteur d''une entreprise de transport routier ayant une ancienneté comprise entre six mois et deux ans donne droit au minimum à un délai congé de :', '[{"id": "a", "label": "1 semaine", "is_correct": false}, {"id": "b", "label": "1 mois", "is_correct": false}, {"id": "c", "label": "2 mois", "is_correct": false}, {"id": "d", "label": "3 mois", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:478', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''établissement d''un règlement intérieur est obligatoire à partir du seuil de :', '[{"id": "a", "label": "10 salariés", "is_correct": false}, {"id": "b", "label": "20 salariés", "is_correct": false}, {"id": "c", "label": "50 salariés", "is_correct": false}, {"id": "d", "label": "100 salariés ; Page 100 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:479', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de licenciement individuel d''un salarié, pour motif économique, l''employeur doit informer l''administration :', '[{"id": "a", "label": "Après l''entretien préalable", "is_correct": false}, {"id": "b", "label": "Avant l''envoi de la lettre de licenciement", "is_correct": false}, {"id": "c", "label": "Dans les 8 jours suivant l''envoi de la lettre de licenciement", "is_correct": false}, {"id": "d", "label": "Avant la fin du délai congé", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:480', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un contrat de travail à durée déterminée peut être conclu pour :', '[{"id": "a", "label": "Remplacer un salarié temporairement absent pendant la durée de son absence", "is_correct": false}, {"id": "b", "label": "Remplacer un salarié dont le contrat de travail est suspendu par suite d''un conflit collectif de travail", "is_correct": false}, {"id": "c", "label": "Embaucher un salarié en vue de vérifier ses aptitudes professionnelles, dans l''attente de son embauche définitive", "is_correct": false}, {"id": "d", "label": "Réembaucher sur un poste permanent, un salarié licencié un mois auparavant pour motif économique", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:481', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'A l''occasion d''un licenciement notifié par lettre recommandée avec avis de réception, le préavis débute :', '[{"id": "a", "label": "Lors de la remise effective de la lettre recommandée par le facteur au salarié", "is_correct": false}, {"id": "b", "label": "Lors de la présentation de la lettre recommandée par le facteur au domicile du salarié, même si celui-ci est absent", "is_correct": false}, {"id": "c", "label": "Lors du retrait de la lettre à la poste par le salarié absent de son domicile au moment du passage du facteur", "is_correct": false}, {"id": "d", "label": "À la date d''expédition de la lettre recommandée", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:482', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Selon l''annexe 1 de la convention collective des transports routiers et des activités auxiliaires du transport routier (CCNTR), la durée maximale de la période d''essai non renouvelable d''un conducteur routier embauché sous contrat de travail à durée indéterminée, est de :', '[{"id": "a", "label": "Une semaine", "is_correct": false}, {"id": "b", "label": "Quinze jours", "is_correct": false}, {"id": "c", "label": "Un mois", "is_correct": false}, {"id": "d", "label": "Deux mois ; Page 101 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:483', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le dépôt du règlement intérieur d''une entreprise ou d''un établissement est effectué :', '[{"id": "a", "label": "Au secrétariat-greffe du conseil de prud''hommes dans le ressort duquel l''entreprise ou l''établissement est situé(e) et auprès de l''inspecteur du travail", "is_correct": false}, {"id": "b", "label": "Au service des transports de la direction régionale de l''environnement, de l''aménagement et du logement", "is_correct": false}, {"id": "c", "label": "Au greffe du tribunal de commerce", "is_correct": false}, {"id": "d", "label": "Au greffe du tribunal judiciaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:484', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un salarié dont le contrat à durée déterminée est conclu du 15 avril au 15 juin, a un accident le 30 avril avec arrêt de 3 mois. Sauf clause de report mentionnée dans son contrat, celui-ci s''achèvera :', '[{"id": "a", "label": "Le 15 juillet", "is_correct": false}, {"id": "b", "label": "Le 30 juillet", "is_correct": false}, {"id": "c", "label": "Le 30 avril", "is_correct": false}, {"id": "d", "label": "Le 15 juin", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:485', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La déclaration préalable à l''embauche (DPAE) d''un salarié doit s''effectuer :', '[{"id": "a", "label": "Pendant la période d''essai", "is_correct": false}, {"id": "b", "label": "Au plus tôt dans les 8 jours avant l''embauche", "is_correct": false}, {"id": "c", "label": "Un mois avant l''embauche", "is_correct": false}, {"id": "d", "label": "Un mois après l''embauche", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:486', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le document unique d''évaluation des risques pour la sécurité et la santé des travailleurs doit être établi par :', '[{"id": "a", "label": "Le médecin du travail", "is_correct": false}, {"id": "b", "label": "L''employeur", "is_correct": false}, {"id": "c", "label": "Le comité d''hygiène, de sécurité des conditions de travail", "is_correct": false}, {"id": "d", "label": "L''inspecteur du travail", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:487', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un contrat à durée déterminée peut être renouvelé : Page 102 sur 204 :', '[{"id": "a", "label": "Une fois sans que la durée totale du contrat puisse dépasser 12 mois", "is_correct": false}, {"id": "b", "label": "Une fois sans que la durée totale du contrat puisse dépasser 18 mois", "is_correct": false}, {"id": "c", "label": "Plusieurs fois sans que la durée totale du contrat puisse dépasser 12 mois", "is_correct": false}, {"id": "d", "label": "Deux fois sans que la durée totale du contrat puisse dépasser 18 mois", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:488', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Pour qu''un conducteur soit considéré comme conducteur "courte distance" (hors messagerie et transport de fonds), il doit :', '[{"id": "a", "label": "Uniquement travailler dans une région déterminée", "is_correct": false}, {"id": "b", "label": "Prendre son repos journalier hors domicile moins de 6 fois par mois", "is_correct": false}, {"id": "c", "label": "Rentrer obligatoirement quotidiennement à l''établissement d''attache", "is_correct": false}, {"id": "d", "label": "Avoir des horaires fixes tous les jours", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:489', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''ouverture d''un droit à congés payés de 2,5 jours ouvrables a lieu dès que le salarié a travaillé chez le même employeur :', '[{"id": "a", "label": "10 jours de travail effectif", "is_correct": false}, {"id": "b", "label": "3 semaines de travail effectif", "is_correct": false}, {"id": "c", "label": "1 mois de travail effectif", "is_correct": false}, {"id": "d", "label": "2 mois de travail effectif", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:490', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les salariés sont informés de la convention collective de branche applicable dans l''entreprise par une mention :', '[{"id": "a", "label": "Déposée en mairie", "is_correct": false}, {"id": "b", "label": "Affichée au conseil de prud''hommes", "is_correct": false}, {"id": "c", "label": "Figurant sur le bulletin de paie", "is_correct": false}, {"id": "d", "label": "Affichée au tribunal de commerce", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:491', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un examen médical de reprise doit être organisé au bénéfice d''un salarié victime d''un accident du travail ayant occasionné un arrêt de travail d''au moins : a. 8 jours :', '[{"id": "b", "label": "10 jours", "is_correct": false}, {"id": "c", "label": "21 jours ; Page 103 sur 204", "is_correct": false}, {"id": "d", "label": "30 jours", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:492', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans une entreprise dépourvue de représentant du personnel, le salarié peut, au cours de l''entretien préalable au licenciement, se faire assister par :', '[{"id": "a", "label": "Un avocat du salarié", "is_correct": false}, {"id": "b", "label": "Un inspecteur du travail", "is_correct": false}, {"id": "c", "label": "Un conseiller du salarié inscrit sur une liste officielle", "is_correct": false}, {"id": "d", "label": "Un conseiller prud''homal", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:493', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'A l''occasion de certains évènements familiaux, tout salarié bénéficie d''une autorisation d''absence au travail d''un ou de plusieurs jours qui :', '[{"id": "a", "label": "Ne sont, en aucun cas, rémunérés", "is_correct": false}, {"id": "b", "label": "N''entraînent pas de réduction de la rémunération", "is_correct": false}, {"id": "c", "label": "S''imputent sur le droit acquis en repos compensateur pour heures supplémentaires", "is_correct": false}, {"id": "d", "label": "Ne sont pas assimilés à des jours de travail effectif", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:494', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un employeur qui fait au salarié une avance sur salaire ne peut se rembourser qu''au moyen de retenues successives ne dépassant pas :', '[{"id": "a", "label": "Un vingtième du montant du salaire exigible", "is_correct": false}, {"id": "b", "label": "Un dixième du montant du salaire exigible", "is_correct": false}, {"id": "c", "label": "Un cinquième du montant du salaire exigible", "is_correct": false}, {"id": "d", "label": "La moitié du montant du salaire exigible", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:495', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En application de l''article R. 3312 -47 du Code des transports, la 44ème heure de travail hebdomadaire pour un conducteur routier de marchandises est majorée de :', '[{"id": "a", "label": "25 %", "is_correct": false}, {"id": "b", "label": "33 %", "is_correct": false}, {"id": "c", "label": "50 %", "is_correct": false}, {"id": "d", "label": "75 % ; Page 104 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:496', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si un salarié est embauché dans une entreprise, il doit passer une visite médicale dans les trois mois suivants son embauche, appelée :', '[{"id": "a", "label": "Visite de mi-carrière", "is_correct": false}, {"id": "b", "label": "Visite d’information et de prévention (VIP)", "is_correct": false}, {"id": "c", "label": "Visite de reprise", "is_correct": false}, {"id": "d", "label": "Visite de début de carrière", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:497', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise ne respecte pas l’obligation de mettre en place un Comité Social et Économique (CSE), elle risque :', '[{"id": "a", "label": "Une simple amende", "is_correct": false}, {"id": "b", "label": "Un redressement fiscal", "is_correct": false}, {"id": "c", "label": "Des poursuites pénales pour délit d''entrave", "is_correct": false}, {"id": "d", "label": "Une réduction de subventions publiques", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:498', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si un litige survient entre un salarié et son employeur concernant une sanction disciplinaire, il sera traité par :', '[{"id": "a", "label": "L''URSSAF", "is_correct": false}, {"id": "b", "label": "Le Conseil des prud’hommes", "is_correct": false}, {"id": "c", "label": "La médecine du travail", "is_correct": false}, {"id": "d", "label": "L''inspection du travail", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:499', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si un employeur souhaite licencier un membre du CSE, il doit obtenir :', '[{"id": "a", "label": "L''accord du salarié", "is_correct": false}, {"id": "b", "label": "L''autorisation de l''inspection du travail", "is_correct": false}, {"id": "c", "label": "L''approbation de France Travail", "is_correct": false}, {"id": "d", "label": "Le consentement du délégué syndical", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:500', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Si une entreprise adhère à un service de médecine du travail, elle garantit :', '[{"id": "a", "label": "La prise en charge des arrêts maladie", "is_correct": false}, {"id": "b", "label": "L’accès à des soins médicaux pour tous les salariés Page 105 sur 204", "is_correct": false}, {"id": "c", "label": "La surveillance des conditions de travail", "is_correct": false}, {"id": "d", "label": "La prévention des accidents du travail", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:501', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de licenciement d''un salarié protégé, l''employeur doit :', '[{"id": "a", "label": "Informer le CSE uniquement", "is_correct": false}, {"id": "b", "label": "Obtenir l''accord du salarié", "is_correct": false}, {"id": "c", "label": "Obtenir l''autorisation de l''inspection du travail", "is_correct": false}, {"id": "d", "label": "Attendre la fin du mandat du salarié protégé", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:502', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le rôle principal de la médecine du travail est de :', '[{"id": "a", "label": "Traiter les maladies professionnelles", "is_correct": false}, {"id": "b", "label": "Sanctionner les employeurs en cas de non-conformité", "is_correct": false}, {"id": "c", "label": "Prévenir les risques professionnels et surveiller la santé des travailleurs", "is_correct": false}, {"id": "d", "label": "Gérer les arrêts maladie", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:503', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''URSSAF est principalement chargée de :', '[{"id": "a", "label": "Collecter les cotisations sociales", "is_correct": false}, {"id": "b", "label": "Gérer les retraites des fonctionnaires", "is_correct": false}, {"id": "c", "label": "Organiser les élections professionnelles", "is_correct": false}, {"id": "d", "label": "Former les inspecteurs du travail", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:504', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un salarié souhaitant contester une sanction disciplinaire doit s''adresser :', '[{"id": "a", "label": "Au Conseil de prud''hommes", "is_correct": false}, {"id": "b", "label": "À la médecine du travail", "is_correct": false}, {"id": "c", "label": "À l''inspection du travail", "is_correct": false}, {"id": "d", "label": "À l''URSSAF", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:505', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le Comité Social et Économique (CSE) doit être mis en place dans une entreprise lorsque l''effectif atteint :', '[{"id": "a", "label": "5 salariés ; Page 106 sur 204", "is_correct": false}, {"id": "b", "label": "11 salariés", "is_correct": false}, {"id": "c", "label": "25 salariés", "is_correct": false}, {"id": "d", "label": "50 salariés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:506', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le droit de retrait permet à un salarié de :', '[{"id": "a", "label": "Quitter son poste définitivement en cas de danger", "is_correct": false}, {"id": "b", "label": "Demander une indemnisation immédiate", "is_correct": false}, {"id": "c", "label": "Cesser temporairement de travailler en cas de danger grave et imminent", "is_correct": false}, {"id": "d", "label": "Contester une sanction disciplinaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:507', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le Conseil de prud''hommes est compétent pour régler :', '[{"id": "a", "label": "Les litiges individuels entre employeurs et salariés", "is_correct": false}, {"id": "b", "label": "Les litiges entre entreprises", "is_correct": false}, {"id": "c", "label": "Les conflits collectifs", "is_correct": false}, {"id": "d", "label": "Les infractions au code du travail", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:509', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un salarié est automatiquement affilié au régime général de la sécurité sociale :', '[{"id": "a", "label": "Uniquement s''il le demande", "is_correct": false}, {"id": "b", "label": "Dès son embauche", "is_correct": false}, {"id": "c", "label": "Après un an d''ancienneté", "is_correct": false}, {"id": "d", "label": "Uniquement en cas de maladie", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:510', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas d''absence de CSE dans une entreprise où il devrait être en place, cela constitue :', '[{"id": "a", "label": "Un délit d''entrave", "is_correct": false}, {"id": "b", "label": "Une infraction mineure", "is_correct": false}, {"id": "c", "label": "Une irrégularité sans conséquence", "is_correct": false}, {"id": "d", "label": "Une faute du salarié", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:511', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Page 107 sur 204 Un employeur qui veut modifier un élément essentiel du contrat de travail d''un salarié doit :', '[{"id": "a", "label": "L''informer par oral", "is_correct": false}, {"id": "b", "label": "Obtenir l''accord du salarié", "is_correct": false}, {"id": "c", "label": "Demander l''avis du CSE", "is_correct": false}, {"id": "d", "label": "Consulter l''inspection du travail", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:512', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La durée maximale de travail par semaine, selon le Code du travail, est de :', '[{"id": "a", "label": "35 heures", "is_correct": false}, {"id": "b", "label": "40 heures", "is_correct": false}, {"id": "c", "label": "48 heures", "is_correct": false}, {"id": "d", "label": "50 heures", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:513', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le médecin du travail peut proposer :', '[{"id": "a", "label": "Des sanctions disciplinaires", "is_correct": false}, {"id": "b", "label": "Des aménagements de poste ou un reclassement", "is_correct": false}, {"id": "c", "label": "Une réduction de salaire", "is_correct": false}, {"id": "d", "label": "Un changement de contrat", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:514', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Un salarié peut bénéficier d''une protection contre le licenciement s''il est :', '[{"id": "a", "label": "Membre du CSE", "is_correct": false}, {"id": "b", "label": "En période d''essai", "is_correct": false}, {"id": "c", "label": "En CDD de moins de 6 mois", "is_correct": false}, {"id": "d", "label": "En congé annuel", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:515', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas de fermeture définitive de l''entreprise, les salariés peuvent obtenir une indemnisation auprès :', '[{"id": "a", "label": "De l''URSSAF", "is_correct": false}, {"id": "b", "label": "De l''AGS (Association pour la gestion du régime de garantie des créances des salariés) ; Page 108 sur 204", "is_correct": false}, {"id": "c", "label": "Du conseil de prud’hommes", "is_correct": false}, {"id": "d", "label": "Du CSE", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:516', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le CSE doit être consulté obligatoirement en cas de :', '[{"id": "a", "label": "Recrutement d''un salarié", "is_correct": false}, {"id": "b", "label": "Congé maternité", "is_correct": false}, {"id": "c", "label": "Licenciement économique collectif", "is_correct": false}, {"id": "d", "label": "Augmentation de salaire", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:517', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le registre de droit d''alerte en matière sanitaire et environnementale est obligatoire pour :', '[{"id": "a", "label": "Toutes les entreprises", "is_correct": false}, {"id": "b", "label": "Les entreprises de plus de 50 salariés", "is_correct": false}, {"id": "c", "label": "Les entreprises de transport routier", "is_correct": false}, {"id": "d", "label": "Les entreprises de plus de 11 salariés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:518', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le registre spécial des avis de danger est obligatoire pour :', '[{"id": "a", "label": "Toutes les entreprises", "is_correct": false}, {"id": "b", "label": "Les entreprises de transport routier", "is_correct": false}, {"id": "c", "label": "Les entreprises d''au moins 50 salariés", "is_correct": false}, {"id": "d", "label": "Les entreprises d''au moins 11 salariés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:519', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Les consignes de sécurité pour incendie doivent être affichées :', '[{"id": "a", "label": "Dans les bureaux uniquement", "is_correct": false}, {"id": "b", "label": "Seulement dans les entreprises de plus de 50 salariés", "is_correct": false}, {"id": "c", "label": "Dans les lieux où peuvent se trouver plus de 50 personnes ou où des matières inflammables sont manipulées", "is_correct": false}, {"id": "d", "label": "Dans les locaux techniques seulement", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qcm:520', false) ON CONFLICT DO NOTHING;
