  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'En cas d’accident corporel, la première action à effectuer est : Page 146 sur 204 :', '[{"id": "a", "label": "Appeler les secours immédiatement", "is_correct": false}, {"id": "b", "label": "Protéger la zone pour éviter un suraccident", "is_correct": false}, {"id": "c", "label": "Déplacer la victime", "is_correct": false}, {"id": "d", "label": "Prendre une photo de la scène", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:687', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Dans le cadre des formations pour salariés, "PRAP" signifie :', '[{"id": "a", "label": "Prévention des risques administratifs et professionnels", "is_correct": false}, {"id": "b", "label": "Prévention des Risques liés à l''Activité Physique", "is_correct": false}, {"id": "c", "label": "Plan de Résolution des Accidents Professionnels", "is_correct": false}, {"id": "d", "label": "Programme de Réduction des Accidents Physiques", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:688', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'L''objectif principal de la démarche RSE (Responsabilité Sociétale des Entreprises) pour les transporteurs est :', '[{"id": "a", "label": "Augmenter les bénéfices à court terme", "is_correct": false}, {"id": "b", "label": "Intégrer les préoccupations sociales, éthiques, environnementales et économiques", "is_correct": false}, {"id": "c", "label": "Réduire les coûts administratifs", "is_correct": false}, {"id": "d", "label": "Améliorer uniquement l''image de marque", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:689', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le Code de l''environnement, pour une infraction relative à l''élimination des déchets, prévoit :', '[{"id": "a", "label": "Une simple amende", "is_correct": false}, {"id": "b", "label": "4 ans de prison et 150 000 € d''amende", "is_correct": false}, {"id": "c", "label": "Une réprimande publique", "is_correct": false}, {"id": "d", "label": "La suspension temporaire de l''activité", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:690', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'La limite sonore maximale autorisée pour les véhicules n''excédant pas 2,5 tonnes est :', '[{"id": "a", "label": "60 décibels", "is_correct": false}, {"id": "b", "label": "80 décibels Page 147 sur 204", "is_correct": false}, {"id": "c", "label": "72 décibels", "is_correct": false}, {"id": "d", "label": "74 décibels", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:691', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Une (ZFE) est :', '[{"id": "a", "label": "Une zone où les véhicules peuvent rouler sans restriction", "is_correct": false}, {"id": "b", "label": "Une zone où l''accès est limité aux véhicules les moins polluants", "is_correct": false}, {"id": "c", "label": "Une zone réservée aux véhicules électriques uniquement", "is_correct": false}, {"id": "d", "label": "Une zone de repos pour les chauffeurs", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:692', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Selon l''article L. 1431 -3 du Code des transports, les entreprises de transport doivent fournir sur les factures de leurs clients :', '[{"id": "a", "label": "Le nombre de kilomètres parcourus", "is_correct": false}, {"id": "b", "label": "La quantité de gaz à effet de serre émis", "is_correct": false}, {"id": "c", "label": "Le coût de la maintenance des véhicules", "is_correct": false}, {"id": "d", "label": "La marque des véhicules utilisés", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:693', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, choices, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qcm', 'Le pourcentage des émissions de CO2 imputable au secteur des transports en 2018 est :', '[{"id": "a", "label": "10%", "is_correct": false}, {"id": "b", "label": "25%", "is_correct": false}, {"id": "c", "label": "50%", "is_correct": false}, {"id": "d", "label": "75% Page 148 sur 204", "is_correct": false}]'::jsonb, 1, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qcm:694', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Concernant les conditions d’exercice du gestionnaire de transport : a. Citez 2 exigences auxquelles il doit répondre b. Citez 5 missions confiées au gestionnaire de transport par la réglementation. c. Dans l’hypothèse où le gestionnaire de transport n’est pas interne à l’entreprise, dans combien d’entreprises de transport routier au maximum peut-il exercer cette fonction ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:1', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'La société SAS TRANSGO, spécialisé dans le transport frigorifique sur le territoire national avec des véhicules n’excédant pas 3,5 tonnes, est implantée à Lyon. Lors d’un transport de beurre ( 3 palettes de 250 kg chacune pour une valeur totale de 900€) entre Lyon et Marseille, le groupe réfrigérant du véhicule n’a pas fonctionné. Á l’arrivée, la marchandise n’est plus consommable. a. Quelle assurance permettra de couvrir ce sinistre ? b. Quel est le contrat-type applicable à ce transport ? c. Déterminer le montant de l’indemnité prévue en réparation de ce dommage conformément aux clauses de ce contrat.', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:2', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'La société DMG RAPID est une entreprise de transport public de marchandises qui exploite un parc de 10 véhicules moins de 3,5 tonnes. Ces véhicules se répartissent comme suit :  7 en pleine propriété  3 pris en location ( 2 véhicules avec conducteurs et 1 véhicule sans conducteur) a. Quels sont les documents devant accompagner un véhicule léger pris en location avec conducteur (véhicule moins 3,5 tonnes) b. Quelles sont les exigences réglementaires pour exercer la profession de transporteur public routier de marchandises ? Page 150 sur 204 c. Sachant que le montant de ses capitaux propres est de 8 900 €, la société DMG RAPID satisfait -elle à la capacité financière exigée par la règlementation ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:3', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Vous travaillez pour une entreprise de transport ADF TRANS, comme gestionnaire de transport, et vous devez analyser différentes situations pour déterminer si elles peuvent être considérées comme des causes d’exonération en cas de retard dans le transport de marchandises. a. Citer les 3 causes d''exonération en cas de pertes ou avaries b. Á l’aide du tableau ci-dessous, étudier les situations suivantes et identifiez si elles peuvent être considérées comme des causes d’exonération en justifiant votre réponse. Situation Cause d’exonération Justification Une cargaison de fruits a été endommagée en raison d’une panne de réfrigération pendant le transport.  Oui  Non Un incendie imprévu a détruit une partie de la cargaison pendant le transport  Oui  Non La cargaison a été endommagée en raison d’un défaut d’emballage fourni par l’expéditeur.  Oui  Non Une grève des dockers a retardé le déchargement des marchandises, entraînant des avaries  Oui  Non La cargaison a été endommagée par des conditions météorologiques extrêmes imprévues  Oui  Non Page 151 sur 204', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:4', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'La société DMG Express, spécialisé dans le transport express de marchandises sur le territoire national avec des véhicules n’excédant pas 3,5 tonnes, est implantée à Paris. Vous avez été embauché(e) par cette société comme gestionnaire de transport a. Citez quatre des conditions sous lesquelles un salarié titulaire de l’attestation de capacité professionnelle peut-être gestionnaire de transport b. Quelle qualité de temps de travail doit figurer au contrat de travail du gestionnaire de transport de DMG EXPRESS c. Dans les deux cas suivants, qui sera retenu comme responsable pénal de l’infraction : ❖ d''excès de vitesse en situation de circulation sur la voie public ? ❖ d’absence de la copie certifiée conforme de la licence intérieure à bord du véhicule de transport ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:5', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'a. Selon le contrat-type de location avec conducteur ;  Citez 2 obligations pour le loueur  Citer 2 obligations pour le locataire b. Indiquer aux moins 2 documents qui doivent être au bord du véhicule de location avec conducteur', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:6', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Dans le cadre de la création de l’entreprise de transport SASU TRANSGO, certaines obligations réglementaires et administratives doivent être remplies. a. Citez les 4 exigences (conditions) auxquelles doit satisfaire l’entreprise SASU TRANSGO pour l’obtention de l’autorisation d’exercer la profession de transporteur public routier de marchandises. b. Quel titre d’exploitation prouve l’inscription de l’entreprise SASU TRANSGO au registre électronique national des entreprises de transport par route ? Page 152 sur 204 c. Si l''entreprise SASU TRANSGO n''a pas de gestionnaire de transport interne, que peut-elle faire ? d. Citez au moins deux missions que doit assurer le gestionnaire de transport de l''entreprise SASU TRANSGO.', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:7', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un transporteur utilisant un véhicule de moins de 3,5 tonnes est engagé pour livrer des fleurs coupées de Lille à Paris. Pendant le transport, le système de climatisation tombe en panne, ce qui entraîne la dégradation de la marchandise. a. Quelle assurance doit couvrir les pertes subies par les fleurs détériorées ? b. Comment le contrat-type pour les véhicules de moins de 3,5 tonnes encadre-t-il l''indemnisation en cas de dégradation de produits périssables ? c. Quelles actions l''expéditeur doit-il entreprendre pour obtenir une indemnisation dans ce cas ? d. Si le montant de l’indemnisation prévu est inférieur à la valeur réelle de la marchandise, quels recours l’expéditeur peut-il envisager ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:8', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Concernant les conditions d’exercice du commissionnaire de transport : a. Citez les 2 conditions auxquelles il doit répondre b. Le commissionnaire a plusieurs obligations envers le commettant dans le cadre d’un contrat de commission. Citez 2 obligations c. Donner deux activités principales d’un commissionnaire', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:9', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un transporteur routier utilise un véhicule de moins de 3,5 tonnes pour livrer des denrées alimentaires entre Bordeaux et Toulouse. Une panne du moteur retarde la livraison de plusieurs heures, compromettant la qualité des produits. a. Quelle assurance pourrait couvrir les pertes liées à la détérioration des denrées alimentaires ? b. Quelle est la responsabilité du transporteur dans ce scénario, selon le contrat-type applicable ? Page 153 sur 204 c. Quels sont les délais de réclamation que l''expéditeur doit respecter pour obtenir une indemnisation ? d. Si l''expéditeur estime que l''indemnisation est insuffisante, quels sont les recours possibles ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:10', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'La société SPRINT EXPRESS, une SARL, exploite une flotte de 5 véhicules légers de moins de 3,5 tonnes pour le transport de marchandises. a. Quels documents doivent être présentés pour chaque véhicule appartenant à SPRINT EXPRESS ? b. Quels sont les critères financiers que SPRINT EXPRESS doit remplir pour démontrer sa capacité financière ? c. Quel type de gestionnaire de transport est requis pour SPRINT EXPRESS ? d. Quels sont les principaux documents nécessaires pour prouver l’honorabilité des dirigeants de SPRINT EXPRESS ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:11', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'La société DELIVERIES PLUS, une SASU, utilise des véhicules de location pour ses opérations de transport de marchandises. a. Quels documents doivent accompagner un véhicule de location sans conducteur utilisé par DELIVERIES PLUS ? b. Quels sont les contrôles techniques requis pour les véhicules de DELIVERIES PLUS ? c. Quelles sont les exigences de formation pour les conducteurs employés par DELIVERIES PLUS ? d. Comment DELIVERIES PLUS doit-elle gérer les risques associés à l’utilisation de véhicules de location ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:12', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Vous travaillez pour une entreprise de transport et vous devez analyser différentes situations pour déterminer si elles peuvent être considérées comme des causes d’exonération en cas de retard dans le transport de marchandises. Page 154 sur 204 a. Citer les 2 causes d''exonération en cas de retard b. Étudier les situations suivantes et identifiez si elles peuvent être considérées comme des causes d’exonération en remplissant le tableau suivant. Justifiez votre réponse. Situation Cause d’exonération Justification Une tempête de neige imprévue a bloqué les routes, empêchant le camion de livraison d’atteindre sa destination à temps.  Oui  Non Le camion de livraison a été retardé en raison d’une panne mécanique due à un manque d’entretien régulier  Oui  Non Une grève nationale des transports a empêché la livraison des marchandises pendant trois jours.  Oui  Non Le chauffeur du camion a pris un itinéraire plus long par erreur, causant un retard de livraison  Oui  Non Un accident impliquant un autre véhicule a bloqué la route principale, retardant la livraison de plusieurs heures  Oui  Non Une panne de courant généralisée a empêché le chargement des marchandises dans les entrepôts, retardant ainsi leur expédition.  Oui  Non', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:13', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Une société de transport doit gérer une crise suite à un accident impliquant plusieurs véhicules, sans assurance adéquate pour couvrir les dommages causés.  Quelles actions immédiates devraient être prises pour gérer la situation ?  Quelles répercussions financières peuvent découler d''un manque de couverture d''assurance en cas d''accident ?  Quelles stratégies peuvent être mises en œuvre pour s''assurer que des situations similaires ne se reproduisent pas ? Page 155 sur 204', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:14', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le sous-traitant refuse de fournir les attestations de conformité sociale et fiscale exigées par l’opérateur.  Quelles obligations légales a l’opérateur en matière de conformité sociale et fiscale du sous-traitant ?  Quels sont les risques pour l''opérateur de transport en cas de non-conformité du sous-traitant ?  Comment l’opérateur peut-il inclure ces exigences dans le contrat de sous- traitance ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:15', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le juge requalifie un contrat de location en contrat de transport en raison de l''absence d''indices de location.  Quelles sont les implications de cette requalification pour les parties ?  Comment les parties peuvent-elles éviter cette requalification ?  Quels éléments doivent être présents dans un contrat de location pour assurer sa validité ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:16', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le loueur ne respecte pas son obligation de maintenance, et le véhicule tombe en panne pendant son utilisation.  Quelles sont les conséquences pour le loueur ?  Quels recours le locataire a-t-il en cas de panne due à un défaut d''entretien ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:17', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un expéditeur fournit des informations erronées concernant le poids de la marchandise.  Quelles sont les conséquences possibles de cette omission sur le contrat de transport ?  Comment le transporteur peut-il gérer cette situation pour éviter des complications ?  Quels types d’informations doivent être systématiquement vérifiés avant de finaliser un contrat de transport ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:18', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le sous-traitant utilise des fournisseurs tiers pour certains services (comme l’entretien des véhicules) qui ne respectent pas les normes de sécurité.  Quelles sont les obligations du sous -traitant en matière de sécurité concernant ses fournisseurs ?  L''opérateur peut-il être tenu responsable des manquements des fournisseurs du sous-traitant ?  Comment encadrer l’utilisation de fournisseurs tiers dans le contrat de sous- traitance ? Page 156 sur 204', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:19', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un transporteur a souscrit à une assurance marchandise, mais découvre que certaines exclusions rendent la couverture insuffisante pour un envoi spécifique.  Quelles vérifications devrait-il effectuer avant d''expédier des marchandises précieuses ?  Comment peut-il adapter son contrat d''assurance pour mieux couvrir les envois futurs ?  Quelles discussions devrait-il avoir avec son assureur pour clarifier les conditions de couverture ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:20', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le transporteur utilise une flotte de véhicules pour ses livraisons, mais n''a souscrit qu''à l''assurance responsabilité civile obligatoire, sans inclure les garanties « tous accidents » ou « vol et incendie ».  Quelles conséquences pourrait avoir cette omission sur les finances du transporteur en cas d''accident ?  Comment le transporteur peut-il évaluer le coût de l''ajout de ces garanties supplémentaires ?  Quelles recommandations pourrait -on faire pour optimiser la couverture d''assurance de la flotte ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:21', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le locataire ne parvient pas à payer les loyers convenus pour la location du véhicule.  Quelles sont les conséquences pour le locataire ?  Quelles actions le loueur peut-il entreprendre en cas de non -paiement ?  Comment le contrat de location peut-il prévoir des solutions en cas de défaut de paiement ?  Comment le loueur peut-il prouver qu''il a respecté ses obligations de maintenance ?', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:22', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'L’opérateur et le sous-traitant n’arrivent pas à s’entendre sur la renégociation annuelle du prix, créant une situation de blocage.  Que se passe-t-il si les deux parties ne parviennent pas à renégocier le prix ?  Quels mécanismes de résolution de conflits peuvent être inclus dans le contrat ?  Comment s’assurer que les renégociations annuelles respectent les intérêts des deux parties ? Page 157 sur 204', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:23', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un transporteur est confronté à un contrôle de la DREAL concernant la validité de sa licence.  Quels éléments la DREAL vérifiera-t-elle lors de ce contrôle ?  Comment le transporteur peut-il se préparer à cette inspection ?  Quelles sont les conséquences possibles si des irrégularités sont découvertes ? Page 158 sur 204 Module D L’ENTREPRISE ET SON ACTIVITÉ FINANCIÉRE', 4, 'moyen', ARRAY['module-c', 'reglementation', 'capa-3-5t'], 'base-2026:qr:24', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Vous disposez du bilan simplifié de la société AMG TRANS ci-dessous : BILAN SIMPLIFIE (montants exprimés en euros) ACTIF Année N PASSIF Année N Immobilisations incorporelles 38 878 Capitaux propres Capital social 125 000 Immobilisations corporelles Installations techniques… 601 Réserve légal 12 500 Autres immobilisations corporelles 86 856 Autres réserves 37 694 Immobilisations financières 548 Report à nouveau -47 167 Résultat de l’exercice 4 728 TOTAL actif immobilisé 126 883 TOTAL capitaux propres 132 755 Provisions pour risques et charges Actif circulant Dettes Stocks matières premières 41 222 Emprunts et dettes auprès des établissements de crédits 165 990 Créances clients et comptes rattachés 1 066 863 Fournisseurs et comptes rattachés 422 620 Autres créances 66 753 Dettes fiscales et sociales 664 659 Disponibilités 55 872 Dettes sur immobilisations Charges constatées d’avance 28 837 Autres dettes 406 TOTAL actif circulant 1 259 547 TOTAL dettes 1 253 675 TOTAL ACTIF 1 386 430 TOTAL PASSIF 1 386 430 À partir du bilan de la société AMG TRANS ci-dessus, définir et calculer les valeurs suivantes pour l’exercice comptable N : a) le fonds de roulement net global (FRNG) b) le besoin en fonds de roulement (BFR) c) la trésorerie nette (TN) et sa vérification. Page 159 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:25', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Vous disposez du compte de résultat de l’entreprise MH TRANS ci-dessous : COMPTE DE RESULTAT simplifié (montants exprimés en euros) CHARGES Montants PRODUITS Montants EXPLOITATION Achats GO Achats d’autres consommables Entretien et réparation Péages Personnel extérieur Crédit-bail véhicules Autres achats externes Impôts et taxes Salaires conducteurs Salaires autres salariés Charges sociales conducteurs Charges sociales autres salariés Dotations aux amortissements et aux provisions 533 500 87 250 50 100 65 800 80 500 158 400 113 400 12 750 296 800 92 260 188 600 54 825 51 750 EXPLOITATION Chiffre d’affaires Prestations de transport 1 792 000 Total charges d’exploitation 1 785 935 Total produits d’exploitation 1 792 000 FINANCIER Intérêts et charges assimilées 4 650 FINANCIER Intérêts et produits assimilées 2730 Total charges financiers 4 650 Total produits financiers 2 730 1. Donner une définition précise de la valeur ajoutée (VA) et du l’excédent brut d’exploitation (EBE) 2. Après avoir indiqué les formules de calcul, déterminer, en tenant compte des retraitements nécessaires et en détaillant vos calculs, pour l’année N : a) La valeur ajoutée VA b) L’excédent brut d’exploitation EBE 3. Commenter vos résultats en fonction des valeurs de référence retenues par l’entreprise MH TRANS : VA = 50% du CA et EBE = 20 % du CA Page 160 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:26', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Afin d’étudier la mise en place du nouveau marché pour la société RAPID TRANS, vous devez établir un plan de trésorerie du premier trimestre. Vous disposez des éléments suivants : Prévisions de recettes HT pour le 1er trimestre Mois Janvier Février Mars CA prévu 18 375 € 15 750 € 18 375 € Délais de règlement négociés avec le client : 25% au comptant, le solde 1 mois après Prévision des dépenses HT pour le 1er trimestre a. Achats Mois Janvier Février Mars Affrètement routier 9 190 € 8 190 € 7 190 € Consommables 3 050 € 660 € 450 € Location de matériels 2 000 € 2 000 € 2 000 € b. Autres dépenses Mois Janvier Février Mars Salaires 3 280 € 3 280 € 4 692 € Charges sociales 1 410 € 1 410 € 2 017 € TVA à décaisser 702 € 797 € 880 € Délais de règlement : ❖ Affrètement routier : paiement le 20 du mois suivant ❖ Consommables : au comptant ❖ Location de matériels : facture le 2 du mois suivant et paiement 15 jours après date d’émission ❖ Salaires : le 25 du mois en cours ❖ Charges : le 20 du mois suivant ❖ TVA à décaisser : le 15 du mois suivant L’intégralité des prestations d’effectuent sur le territoire français, le taux de TVA est de 20% À partir des éléments ci-dessus, établissez le tableau de trésorerie de ce nouveau marché pour le premier trimestre en remplissant le tableau suivant Page 161 sur 204 Plan de trésorerie Recettes Janvier Février Mars Total recettes (A) Dépenses Janvier Février Mars Total dépense (B) Situations du mois (A-B) Solde début de mois 0 Solde fin de mois Page 162 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:27', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Vous disposez du bilan simplifié de la société TRANSGO ci-dessous : BILAN SIMPLIFIE (montants exprimés en euros) ACTIF Année N-1 Année N PASSIF Année N-1 Année N Immobilisations 38 878 74 759 Capitaux propres 94 498 58 007 Actif circulant • Stocks • Créations clients • Disponibilité 9 250 259 724 4 894 19 853 355 262 64 573 Dettes • Emprunt * • Fournisseurs • Fiscales et sociales 1 650 139 900 109 100 17 650 253 550 185 240 Total 345 148 514 447 Total 345 148 514 447 * dont concours bancaires 500 2 550 1. a) À partir du bilan de la société TRANSGO ci-dessus, calculer, pour les deux exercices comptable N-1 et N : ❖ le fonds de roulement net global (FRNG) ❖ le besoin en fonds de roulement (BFR) ❖ la trésorerie nette (TN) et sa vérification. b) Comparer les résultats obtenus et commenter-les 2. Le chiffre d’affaires de la société TRANSGO pour l’année N s’élève à 1 798 515 € HT. Calculez le délai de paiement moyen de ses clients et commentez le résultat.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:28', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'a) Donnez une définition précise du bilan et du compte de résultat b) Comment les écritures relatives aux amortissements et provisions pour dépréciation affectent-elles : ❖ le bilan ❖ le compte de résultat ❖ le résultat comptable c) Quel est l''impact du résultats de l''exercice sur le montant du capitaux propres', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:29', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', '1. Donnez une définition du bilan 2. Quelles sont les informations supplémentaires apportées par le compte de résultat ; 3. Le délai de conservation des documents comptables Page 163 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:30', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'A quoi correspondent les charges variables ? Donnez des exemples ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:31', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'La société DUPONT TRANSPORT a acquis le 15 septembre N un véhicule pour un coût d’acquisition de 35 000 € HT. Ce matériel a été mis en service le 1er octobre N et il est amortissable en mode linéaire. La durée prévue d’utilisation est de 5 ans et la valeur résiduelle du véhicule est estimée à 5 000 €. Présentez, le plan d’amortissement initial en remplissant le tableau ci-dessus à la date d’entrée du véhicule dans le patrimoine de la société. ❖ Date d''acquisition : 15/09/N ❖ Mode d''amortissement : Linéaire ❖ Date de mise en service : 01/10/N ❖ Durée : 5 ans ❖ Coût d''acquisition : 35 000 € ❖ Valeur résiduelle : 5 000 € ❖ Montant amortissable : 30 000 € Page 164 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:32', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Une entreprise de transport, dont l’exercice coïncide avec l’année civile, achète le 15 avril N, un véhicule éligible à l’amortissement dégressif pour 20 000 euros. Sa durée d’usage fiscale est de 5 ans. La mise en service n’intervient que le 1er mai N. Présentez, le plan d’amortissement initial en remplissant le tableau ci-dessus. ❖ Date d''acquisition : 15/04/N ❖ Mode d''amortissement : Dégressive ❖ Date de mise en service : 17/04/N ❖ Durée : 5 ans ❖ Coût d''acquisition : 20 000 €', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:33', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Dans les établissements de transport, pour le calcul et l’analyse des soldes intermédiaires de gestion (SIG), certains postes doivent être retraiter pour tenir compte des spécificités du transport Quelles sont les trois postes à retraiter et de quelle manière ? Le poste De quelle manière Page 165 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:34', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'La société TMG TRANSPORT souhaite emprunter 20 000 € pour acheter un nouveau véhicule auprès de sa banque. Vous allez étudier sa situation financière 1. Définissez la capacité d’autofinancement 2. Calculer la capacité d’autofinancement CAF de la société TMG TRANSPORT à l’aide des éléments comptables ci-dessous 3. La société TMG TRANSPORT peut-elle espérer un crédit bancaire pour le financement de son véhicule. LES ÉLÉMENTS COMPTABLES A- SOLDES INTERMÉDIAIRES DE GESTION Chiffre d’affaires 1 798 515 € Valeur ajoutée 317 785 € Excédent brut d’exploitation -88 614 € Résultat net - 47 013 € B- AUTRES ÉLÉMENTS COMPTABLES Dotations aux amortissements et provisions (DAP) 21 103 € Reprise sur amortissements et provisions ( RAP) 55 025 € Valeurs nette comptable d’éléments d’actifs cédés (VNC) 2 198 € Produits comptables d’éléments d’actifs cédés (PCEAC) 40 000 €', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:35', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société TRANS’EXPRESS est une société de transport public routier de marchandises qui exploite un parc de 5 véhicules moins de 3,5 tonnes. La société vient de recevoir une demande d’une nouvelle tournée régulière sur 5 ans qui débute le mois suivant par son client. La tournée nécessite l’achat d’un nouveau véhicule. Le responsable souhaite connaitre la marge brut de cette tournée et vous demande d’analyser sa rentabilité Vous disposez des informations suivantes (montants HT) pour 12 mois ❖ Kilométrage parcourus :………………………………….. 87 300 km ❖ Nombre de jours d’exploitation :………………………… 220 jours ❖ Carburant ………………………………………………….. 0,210 € / km ❖ Pneumatiques ……………………………………………...1050 € / km ❖ Entretien ……………………………………………………. 2500 € Page 166 sur 204 ❖ Financement ……………………………………………….. 6 000 € ❖ Assurance du véhicule ……………………………………. 240 € ❖ Assurance des marchandises ……………………………... 180 € ❖ Charges de structure ……………………………………… 55 € / jour ❖ Salaires …………………………………………………….. 2600 € / mois 1. Classer les différentes charges mentionnées de la société TRANS’EXPRESS ci- dessus dans le tableau suivant : Déterminer le coût de revient totale annuel. 2. En déduire le coût de revient kilométrique et le coût de revient journalier 3. Présenter le coût de revient en :  Formulation binôme  Formulation trinôme Quel est l’intérêt pour une entreprise d’utiliser ces formulations', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:36', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Quels sont les différents moyens de financement disponibles pour une entreprise, et comment choisir entre eux ?  Comment le choix du moyen de financement peut-il influencer la performance financière d''une entreprise à long terme ? Page 167 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:37', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société TRANS’EXPRESS est une société de transport public routier de marchandises qui exploite un parc de 5 véhicules moins de 3,5 tonnes. La société vient de recevoir une demande d’une nouvelle tournée régulière sur 5 ans qui débute le mois suivant par son client. Le responsable vous demande d’analyser sa rentabilité Vous disposez des informations suivantes (montants HT) pour 12 mois ❖ Kilométrage parcourus :………………………………….. 87 300 km ❖ Nombre de jours d’exploitation :………………………… 220 jours ❖ Carburant ………………………………………………….. 0,210 € / km ❖ Pneumatiques ……………………………………………...0,031 € / km ❖ Entretien ……………………………………………………. 2500 € ❖ Financement ……………………………………………….. 6 000 € ❖ Assurance du véhicule ……………………………………. 240 € / mois ❖ Assurance des marchandises ……………………………... 6,50 € / jour ❖ Charges de structure ……………………………………… 55 € / jour ❖ Salaires …………………………………………………….. 2600 € / mois 1. Calculer le coût de revient total annuel en distinguant :  Les coûts variables  Les coûts fixes  Les coûts de structure 2. En déduire le coût de revient kilométrique et le coût de revient journalier 3. Présenter le coût de revient en :  Formulation monôme  Formulation binôme  Formulation trinôme 4. Sachant que le chiffre d’affaires annuel serait de 83 100 €, déterminer le résultat net prévisionnel en euros et en % du chiffre d’affaires.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:38', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de rentabilité La société RAPID’TRANS est une petite société de transport public routier de marchandises qui exploite uniquement des véhicules moins de 3,5 tonnes. Vous êtes embauché(e) par cette société comme gestionnaire de transport. Votre responsable vous demande d’étudier la rentabilité d’une proposition commerciale concernant d’un véhicule sur 220 jours et 80 000 kilomètres selon la ventilation suivante : ❖ Total annuel des coûts variables : 20 200 € ❖ Coûts fixes du véhicule et coûts de structure : 27 500 € 1. Sachant que le chiffre d’affaires annuel serait de 49 900 €, déterminer le résultat net prévisionnel en euros et en % du chiffre d’affaires. 2. Déterminer le seuil de rentabilité selon la méthode de votre choix en termes de : Page 168 sur 204 a. Chiffre d’affaires ( arrondir à l’euro supérieur) b. Kilomètres c. Jours d. Interpréter vos résultats', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:39', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société DUPONT est une petite société de transport public routier de marchandises, exploitant une dizaine des véhicules moins de 3,5 tonnes, est spécialisée en transport national et international. Chaque véhicule est exploité sur une base annuelle de 110 000 km et 220 j ours selon les éléments d’exploitation et financiers (HT) suivants : • Carburant : 0, 221 € par kilomètre • Pneumatiques : 0,019 € par kilomètre • Entretien – réparations : 0,054 € par kilomètre • Péages : 0,065 € par kilomètre • Salaire brut conducteur : 136,36 € par jour • Le taux de charges patronales : 30 % • Frais de déplacement : 12,50 € par jour • Coût de détention du véhicule : 48,48 € par jour • Assurances (véhicules + marchandises) : 19,36 par jour • Coût de structure : 8 000 € par an 1. Calculer le coût de revient total annuel 2. Présenter le coût de revient en :  Formulation monôme  Formulation binôme  Formulation trinôme 3. Cette société vend ses prestations à 1,45 € par km et 140 € par jour. a) Quel est son chiffre d’affaires par véhicule b) le prix de vente est-il bien choisi ? pourquoi ? Page 169 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:40', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société EXPRESS TRANS est une société de transport public routier de marchandises exploitant des véhicules moins de 3,5 tonnes. La société vient de recevoir une proposition commerciale. Afin de proposer un prix de vente à cette proposition, vous avez la tâche de calculer le coût de revient. Cette proposition commerciale concerne l’utilisation d’un véhicule bâché de moins de 3,5 tonnes sur 225 jours et 100 000 kilomètres (12 mois) selon les éléments d’exploitation et financiers (HT) suivants : 1. Après avoir classé les différentes charges mentionnées ci-dessus dans le tableau suivant, calculer le coût de revient total • Carburant : ……………………………….. 0, 221 € par kilomètre • Pneumatiques : ………………………….. 0,019 € par kilomètre • Entretien : ………………………………… 0,012 € par kilomètre • réparations : ……………………………… 0,035 € par kilomètre • Péages : ………………………………….. 0,065 € par kilomètre • Salaire brut conducteur : ………………... 2450 € par mois • Les charges patronales : ……………….136,36 € par jour • Frais de déplacement : …………………..12,50 € par jour • Financement : ………………………..… 35,75 € par jour • Assurance du véhicule………………….. 185 € par mois • Assurance de marchandises : ……..….. 800 € par mois • Coût de structure : …………………..….. 580 € par mois Page 170 sur 204 2. En déduire le coût de revient kilométrique et le coût de revient journalier 3. Présenter le coût de revient en :  Formulation binôme  Formulation trinôme Quel est l’intérêt pour une société d’utiliser ces formulations 4. La société applique une marge de 15% du chiffre d’affaires pour toutes les prestations de transport. 4.a- Sachant que le chiffre d’affaires annuel serait de 115 240 €, déterminer le résultat net prévisionnel en euros. 4.b- Cette proposition respecte-elle la marge appliquée par la société. Si non, proposez au moins une solution.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:41', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Expliquez de manière détaillée ce qu’est le BILAN.  Expliquez de manière détaillée ce qu’est le compte de résultat', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:42', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Page 171 sur 204 Expliquez ce qu’est le Besoin en Fonds de Roulement.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:43', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société TRANSGO est une société de transport public routier de marchandises qui exploite des véhicules moins de 3,5 tonnes. Chaque véhicule de la société est exploité sur une base annuelle de 100 000 kilomètres et de 225 jours selon les éléments d’exploitation et financiers (HT) suivants : Carburant 0,17 €/km Pneumatiques 700 € Entretien 0,032 €/km Financement 6000 € Assurance du véhicule 150 €/mois Assurance des marchandises 0,54 €/jour Charges de structure 88 €/jour Salaire brut du conducteur 2450 €/mois Le taux de charges patronales 30% Chiffre d’affaires 430 €/ jour 1- a) Classer les différentes charges mentionnées ci-dessus dans le tableau suivant : 1- b) En déduire le coût de revient annuel d’un véhicule. 2 - Déterminer le coût de revient journalier d’un véhicule. Que signifie la valeur obtenue ? 3 - Calculer le terme kilométrique et le terme journalier. 4 - Déterminer le seuil de rentabilité en nombre de jours. Page 172 sur 204 Que signifie la valeur obtenue ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:44', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Expliquer ce qu’est une immobilisation.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:45', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'A quoi correspondent les charges fixes ? Donnez des exemples ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:46', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', '1. Indiquez ce que représente, pour une entreprise, le bilan. 2. Quelles sont les principales composantes d''un bilan', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:47', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', '1. Comment évaluer la solvabilité d''une entreprise à partir de son bilan ? 2. Quelles informations peut-on tirer de la comparaison d''un bilan sur plusieurs Années.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:48', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Quels sont les principaux postes du compte de résultat et leur signification ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:49', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient et rentabilité La société TRANSFREEGO a pour spécialité le transport frigorifique en véhicule léger (PTAC inférieur à 3,5 T). Vous êtes salarié(e) de cette société comme un gestionnaire de transport et votre responsable vous demande d’étudier le coût de revient. Chaque véhicule de la société est exploité sur une base annuelle de 90 000 kilomètres et de 220 jours selon les éléments d’exploitation et financiers (HT) suivants : • • Consommation moyenne du véhicule ……….…... 15 L/ 100 km • Prix du litre de carburant en moyenne :………….. 1,254 €/L • Pneumatiques : ………………………….. 0,015 € par kilomètre • Entretien : ………………………………… 0,012 € par kilomètre • Groupe réfrigèrent – coût exploitation : …… 6,55 € par jour • Péages : ………………………………….. 0,05 € par kilomètre • Salaire brut conducteur : ………………... 2550 € par mois • Charges sur salaire : ……………….55,63 € par jour • Frais de déplacement : …………………..12,50 € par jour • Financement : ………………………..… 35,75 € par jour • Assurance du véhicule………….……….. 185 € par jour • Coût de structure : ……………….…..….. 6000 € par an Page 173 sur 204 1.a- Calculer le montant du carburant annuel consommé par chaque véhicule 1.b- En déduire le coût de revient total annuel en distinguant : ❖ Les coûts variables ❖ Les coûts fixes ❖ Les coûts de structures 1.c- Déterminer le coût de revient kilométrique. 1.d- Déterminer le coût de revient journalier. 2. a- Présenter le coût de revient en ➢ Formulation binôme, ➢ Formulation trinôme 2. b- Quel est l’intérêt pour une société d’utiliser ces formulations 3. Sachant que le chiffre d’affaires annuel serait de 149 900 €, déterminer le résultat net prévisionnel en euros et en % du chiffre d’affaires. 4. Déterminer le seuil de rentabilité selon la méthode de votre choix en termes de : 4.a- Chiffre d’affaires ( arrondir à l’euro supérieur) 4.b- Kilomètres 4.c- Jours', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:50', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient Vous êtes gestionnaire de transport routier de marchandises au sein de la société GMS RAPID exploitant plusieurs véhicules de moins de 3,5 tonnes. . Le responsable vous demande d’analyser sa rentabilité Vous disposez des informations suivantes (montants HT) pour 12 mois ❖ Kilométrage parcourus :………………………………….. 87 300 km ❖ Nombre de jours d’exploitation :………………………… 220 jours ❖ Carburant ………………………………………………….. 0,210 € / km ❖ Pneumatiques ……………………………………………...0,031 € / km ❖ Entretien ……………………………………………………. 2500 € ❖ Financement ……………………………………………….. 6 000 € ❖ Assurance du véhicule ……………………………………. 240 € / mois ❖ Assurance des marchandises ……………………………... 6,50 € / jour ❖ Charges de structure ……………………………………… 55 € / jour ❖ Salaires …………………………………………………….. 2600 € / mois 1. Calculer le coût de revient total annuel. 2. En déduire le coût de revient kilométrique et le coût de revient journalier 3. Présenter le coût de revient en : Page 174 sur 204  Formulation monôme  Formulation binôme  Formulation trinôme 5. Sachant que le chiffre d’affaires annuel serait de 83 100 €, déterminer le résultat net prévisionnel en euros et en % du chiffre d’affaires.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:51', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', '1. Quels sont les principaux taux d''imposition appliqués à l''impôt sur les sociétés depuis 2023 ? 2. Quelles sont les principales dépenses déductibles pour le calcul de l''assiette de l''impôt sur les sociétés ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:52', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', '1. Quels sont les principaux taux d''imposition appliqués à l''impôt sur les sociétés depuis 2023 ? 2. Quelles sont les principales dépenses déductibles pour le calcul de l''assiette de l''impôt sur les sociétés ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:53', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient Vous êtes gestionnaire de transport au service route de l’entreprise DISTRIGO de Clermont Ferrand (63). A la demande de votre client, vous allez mettre en place une tournée régulière pour une durée de trois ans. Cette tournée nécessite l’achat d’un véhicule de moins de 3,5 T . Votre responsable vous demande d’étudier la rentabilité de cette tournée. Vous disposez des informations suivantes (montants HT) pour 12 mois Kilométrage annuel 150 500 km Nombre de jours d’exploitation 220 jours Coût du carburant 1.25 € / l Consommation carburant 25 l/100 km Coût de l’entretien 0.020 €/ km Pneumatiques 0.012 € /km Coût des péages autoroutiers 0.035€/km Salaire brut du conducteur 140 €/jr Taux de charges patronales 30% Frais de déplacement 7.25 €/jr Prix achat véhicule 30 000 € Durée d’utilisation 3 ans Valeur de reprise 15% du prix du neuf Amortissement linéaire Amortissement technique à calculer Page 175 sur 204 Assurance 7 €/ jr Prorata des charges de structure à affecter 3 500€/an 1.a- Calculer le montant du carburant annuel consommé par ce véhicule. 1.b- Déterminer le montant annuel de l''amortissement. 1.c- Calculer le montant de charges patronales. 1.d- En déduire le coût de revient annuel. 2- Calculer le coût de revient selon la méthode de monôme, binôme et trinôme. 3- Sachant que le chiffre d’affaires est de 450 €/j, déterminer la rentabilité 3.a- en kilomètres, 3.b- en jours d’exploitation, 3.c- en chiffre d’affaires critique (CAC). 4- La direction exige une marge brute minimale moyenne sur l’ensemble des trafics de : 7% sur le prix de vente. La consigne est-elle respectée.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:54', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', '1. Quels sont les différents types de revenus soumis à l''impôt sur le revenu France ? 2. Comment est calculé le montant de l''impôt sur le revenu d''une personne célibataire ayant un revenu net imposable de 35 000 euros en 2024 ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:55', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Définissez l''actif dans un bilan et donnez trois exemples d''éléments qui le composent', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:56', false) ON CONFLICT DO NOTHING;
