  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Que signifie l''équation comptable fondamentale et comment se rapporte-t-elle à l''actif et au passif.  Si l''actif total d''une entreprise est de 500 000€ et que son passif total est de 300 000€, quel est le montant des capitaux propres', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:58', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Qu''est-ce que la TVA et comment fonctionne-t-elle dans le cadre d''une transaction commerciale ? Page 176 sur 204  Quels sont les principaux taux de TVA appliqués et dans quelles situations sont - ils utilisés ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:59', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Expliquer ce qu’est un plan de financement.  Pourquoi un plan de financement est-il essentiel dans la gestion financière d''une entreprise ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:60', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Quelles sont les étapes principales du mécanisme de déclaration de la TVA pour une entreprise.  Comment calculer le montant de TVA à verser à l''administration fiscale à partir d''une vente de 1 000€ HT avec un taux de TVA de 20 % ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:61', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient Vous êtes affecté au service d’exploitation de la société DHM TPS spécialisée dans le transport routier de marchandises. Cette société exploite des véhicules légers (PTAC inférieur à 3,5 T). Vous avez la tâche d’analyser la rentabilité de l’activité. Chaque véhicule de la société est exploité selon les éléments d’exploitation et financiers (HT) suivants : Les informations pour 12 mois d’exploitation d’un véhicule Montants HT  Kilométrage parcouru : …………………………………………… 90 000 km  Nombre de jours d’exploitation : …………………………………. 200 jours  Carburant : ………………………………………………………... 0,130€ / km  Pneumatiques : ……………………………………………………. 0,011 €/ km  Entretien : ……………………… …………………………………. 900€  Financement : ……………………………………………………. 10 000€  Assurance du véhicule : …………………………………………. 800€  Assurance des marchandises : ………...…………………………. 155€  Charges de structure : ……………………………………………. 123€ / jour  Main d’œuvre : …………………………………………………. 2600 € / mois  Frais de déplacement : ………………………………………….. 9,75 € / jour  Charges patronales : ……………………………………………. 500 € / mois  Chiffre d’affaires : ………………………………………………. 325€ / jour 1. Á l’aide du tableau suivant, déterminer le coût de revient annuel. Page 177 sur 204 2. En déduire le coût de revient journalier d''un véhicule. 3. Calculer le terme kilométrique et le terme journalier pour cette activité. 4. Déterminer le seuil de rentabilité 4.a) au nombre de jours, 4.b) au nombre de kilomètre 4.c) en chiffre d’affaires critique CAC. Page 178 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:62', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société TRANSGO est une société de transport public routier de marchandises exploitant des véhicules moins de 3,5 tonnes avec ou sans hayon. La société vient de recevoir une proposition commerciale. Afin de proposer un prix de vente à cette proposition, vous avez la tâche de calculer le coût de revient. Cette proposition commerciale concerne l’utilisation d’un véhicule avec hayon de moins de 3,5 tonnes sur 225 jours et 100 000 kilomètres (12 mois) selon les éléments d’exploitation et financiers (HT) suivants : 1. Après avoir classé les différentes charges mentionnées ci-dessus dans le tableau suivant, calculer le coût de revient total. • Carburant : ……………………………….. 0, 175 € par kilomètre • Pneumatiques : ………………………….. 0,015 € par kilomètre • Entretien- Réparations : ………………… 0,052 € par kilomètre • Péages : ………………………………….. 0,052 € par kilomètre • Salaire brut conducteur : ………………... 2600 € par mois • Les charges patronales : …………………..140 € par jour • Frais de déplacement : ……………………..10 € par jour • Financement : ………………………..……. 15 000 € • Assurance du véhicule………………….. 185 € par mois • Assurance de marchandises : ……..….. 800 € par mois • Coût de structure : …………………..……….. 6500 € • Chiffre d’affaires : …………………………….. 280 € par jour Page 179 sur 204 2. En déduire le coût de revient kilométrique et le coût de revient journalier 3. Présenter le coût de revient en : 3.a- Formulation binôme 3.b- Formulation trinôme 3.c- Quel est l’intérêt pour une société d’utiliser ces formulations 4. La société applique une marge de 15% du chiffre d’affaires pour toutes les prestations de transport. 4.a- Calculer le chiffre d’affaires annuel. 4.b- déterminer le résultat net prévisionnel en euros 4.c Cette proposition respecte-elle la marge appliquée par la société ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:63', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société TMS TRANS a pour spécialité le transport frigorifique en véhicule moins de 3,5 tonnes. Cette société exploite uniquement des véhicules à gaz Vous êtes salarié(e) de cette société comme un gestionnaire de transport et votre responsable vous demande d’étudier le coût de revient. Chaque véhicule de la société est exploité sur une base annuelle de 110 000 kilomètres et de 200 jours selon les éléments d’exploitation et financiers (HT) suivants : 1.a- Calculer le montant du carburant annuel consommé par ce véhicule. Coût du carburant 0.67 € / kg Consommation carburant 25 kg/100 km Coût de l’entretien 0.020 €/ km Pneumatiques 0.012 € /km Coût des péages autoroutiers 0.035€/km Salaire brut du conducteur 140 €/jr Taux de charges patronales 26% Frais de déplacement 9.75 €/jr Assurance du véhicule 1050 €/ mois Assurance des marchandises 9.50 €/jr Prorata des charges de structure à affecter 3 500€/an Page 180 sur 204 1.b- Calculer le montant de charges patronales. 1.c- Calculer le coût de revient annuel en distinguant : ❖ Les coûts variables ❖ Les coûts fixes ❖ Les coûts de structures 2- Calculer le coût de revient selon la méthode de 2.a- monôme, 2.b- binôme 2.c- trinôme. 3- Sachant que le chiffre d’affaires est de 375 €/j, déterminer la rentabilité 3.a- en kilomètres, 3.b- jours d’exploitation, 3.c- chiffre d’affaires critique (CAC). 4- La direction exige une marge brute minimale moyenne sur l’ensemble des trafics de 18% sur le prix de vente. La consigne est-elle respectée.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:64', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Comment le seuil de rentabilité est-il impacté par les variations des coûts fixes et variables.  Quelles actions une entreprise peut-elle entreprendre pour réduire le seuil de rentabilité ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:65', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Qu''est-ce que l''amortissement linéaire ?  Qu''est-ce que l''amortissement dégressif ?  Quels sont les avantages et les inconvénients de l''amortissement linéaire par rapport à l''amortissement dégressif', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:66', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Dans quels cas l''amortissement dégressif est-il préférable à l''amortissement linéaire ?  Peut-on passer d''un amortissement dégressif à un amortissement linéaire au cours de la durée de vie d''un bien ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:67', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Page 181 sur 204  Quelles stratégies une entreprise peut-elle mettre en place pour réduire son besoin en fonds de roulement (BFR) ?  Quels sont les impacts d''un BFR élevé sur la trésorerie d''une entreprise ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:68', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Donner une définition de l''excédent brut d''exploitation (EBE) et quelle est sa signification pour la performance financière d''une entreprise ?*', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:69', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société DUPONT est une petite société de transport public routier de marchandises, exploitant une dizaine des véhicules moins de 3,5 tonnes. Chaque véhicule est exploité sur une base annuelle de 125 000 km et 200 jours selon les éléments d’exploitation et financiers (HT) suivants : 1. a- Classer les différentes charges mentionnées ci-dessus à l’aide du tableau suivant : Coût du carburant 0.67 € / l Consommation carburant 25 l/100 km Coût de l’entretien 0.020 €/ km Pneumatiques 0.012 € /km Coût des péages autoroutiers 0.035€/km Salaire brut du conducteur 140 €/jr Taux de charges patronales 26% Frais de déplacement 9.75 €/jr Assurance du véhicule 1050 €/ mois Assurance des marchandises 9.50 €/jr Prorata des charges de structure à affecter 3 500€/an Page 182 sur 204 1.b- En déduire le coût de revient total annuel 2. Présenter le coût de revient en :  Formulation monôme  Formulation binôme  Formulation trinôme 3. Cette société vend ses prestations à 0,740 € par km. 3.a- Quel est son chiffre d’affaires annuelle par véhicule. 3.b- La direction exige une marge brute minimale moyenne sur l’ensemble des trafics de 18% sur le prix de vente. La consigne est-elle respectée 4. l’entreprise souhaite augmenter sa marge sur son chiffre d’affaires pour atteindre 20 %. 4.a- Quel est le chiffre d’affaires doit-être réaliser par chaque véhicule pour satisfaire l’exigence de la société. 4.b- En déduire le prix de vente par km pour chaque véhicule exploité.', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:70', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Quels sont les leviers dont dispose une entreprise pour améliorer son EBE ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:71', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Pourquoi la trésorerie est-elle un indicateur crucial pour la gestion financière d''une entreprise ?  Quels sont les principaux éléments qui influencent la variation de trésorerie d''une entreprise ?', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:72', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Comment une entreprise peut-elle gérer un déficit de trésorerie à court terme ? Page 183 sur 204', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:73', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient La société TRANSGO est une société de transport public routier de marchandises exploitant des véhicules moins de 3,5 tonnes. Vous êtes gestionnaire de transport et vous devez étudier la rentabilité du véhicule. Chaque véhicule est exploité selon les éléments d’exploitation et financiers suivants : Nombre de jours travaillés 285 jrs Nombre de Km parcourus 84000Km Poste carburant Consommation 5.5L/100KM Prix /L 1.34€ TTC 1.34€TTC Poste entretien Entretien et réparation 0,03€/Km Poste pneumatique Nombre de pneus 4 Coût d’1 pneu HT 95€ Nombre de Km maxi que l’on peut parcourir 77 000Km Poste salaire et charge sociales Salaire brut conducteur 1585€ Charges patronales 42% Frais de déplacement/jour 11.5,00 Poste frais de structure Fourniture de bureau HT 772€/an Honoraire comptable HT 317€/mois Documentation HT 267€/an Tél fixe HT 205€/mois Frais de réception HT 317€/an Taxes diverses 1067€/an Frais de gestion HT 277€/an Honoraires conseil HT 315€/an Poste assurances Assurances diverses 3475€ Loyer/mois 734€ Marge souhaitée 12% PV 1. Calculer le total des charges variables, le total des charges fixes conducteur, le total des charges fixes véhicule et charges de structure. 2. Calcul du coût de revient : 2.a- calculer le coût de revient selon la formule monôme 2.a- calculer le coût de revient selon la formule binôme 2.a- calculer le coût de revient selon la formule trinôme 3. Calculer le prix de vente kilométrique en tenant compte de la marge mentionnée Page 184 sur 204 dans les données du coût de revient', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:74', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Coût de revient Calcul du coût de revient de deux véhicules (Thermique et Électrique) et les avantages pour les tournées La société RAPIDES TRANS envisage d’acheter deux véhicules utilitaires pour ses tournées régulières de livraison. Elle hésite entre : ❖ Un véhicule utilitaire thermique (carburant diesel). ❖ Un véhicule utilitaire électrique. Les caractéristiques des deux véhicules sont données en annexe ci-dessous. 1. Calcul du coût total annuel d’utilisation pour chaque véhicule en distinguant : ❖ Les coûts variables ❖ Les coûts fixes ❖ Les coûts de structures 2. Calculer le prix de revient kilométrique (PRK) pour chaque véhicule : 3. a- Quelle est la différence en termes de coût d''utilisation entre les deux véhicules ? b. Indiquez dans quels types de tournées (longue distance, tournées urbaines, etc.) l''un des véhicules pourrait être plus avantageux que l''autre. Prenez en compte les autres avantages non financiers (écologiques, logistiques, réglementaires). Page 185 sur 204 ANNEXE Les caractéristiques des deux véhicules Poste de coût Base de calcul Montant Montant Véhicule thermique Véhicule électrique Nombre de jours d’exploitation 250 jours 250 jours Nombre de km parcourus 80 000 km 80 000 km Consommation moyenne 9,2l/100 km à définir 20 kWh/100 km Prix moyen du carburant 1,70 € TTC 0,18€/ kWh Coût des péages autoroutiers Coût au km 0,0045 € Autonomie 250 km Salaires conducteurs Sur un an 30 000 € 30 000 € Charges patronales 29% à définir à définir Entretien et réparation Sur un an 1 200 € HT 600 € TTC Pneumatiques Prix à la pièce 70,00 € TTC 70,00 € TTC Assurance véhicule Montant annuel 950 € HT 950 € HT Assurance marchandises Montant annuel 900 € HT 900 € HT Achat du véhicule Durée utilisation : 3 ans 26 000 € TTC 33 000 € TTC Amortissement Amortissement linéaire à définir à définir Frais financiers pour achat de véhicule Intérêts annuels payés 600 € 600 € Provision pour renouvellement Valeur d’achat dans 3 ans 30 000 € TTC 36 000 € TTC Impôts communs 3% par an affectés à ce véhicule à définir à définir Assurances communes 2% par an affectés à ce véhicule à définir à définir Frais de déplacement Coût journalier 8,90 € 8,90 € Page 186 sur 204 Module E L’ENTREPRISE ET SES SALARIÉS', 4, 'moyen', ARRAY['module-d', 'financier', 'capa-3-5t'], 'base-2026:qr:75', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'A partir de combien de salariés une entreprise a l’obligation d’organiser les élections des délégués du personnel et quelles sont les conditions d’éligibilité ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:76', false) ON CONFLICT DO NOTHING;
