  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Quels sont les droits spécifiques des conducteurs travaillant de nuit ?  Comment une société de transport doit-elle organiser les pauses et les périodes de repos pour les conducteurs de nuit ?  Quelles sont les obligations de cette société concernant les conditions de travail pour les horaires de nuit ?  Quels types d’assurances sont recommandés pour les conducteurs travaillant de nuit ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:102', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'L’entreprise RAPIDELIVERY , une SAS, propose des services de transport avec des véhicules légers en location et emploie des conducteurs en CDD pour des missions ponctuelles.  Quels documents doivent être fournis pour chaque mission ponctuelle des conducteurs en CDD chez RAPIDELIVERY ?  Comment RAPIDELIVERY doit-elle s''assurer que les conducteurs en CDD respectent les réglementations en matière de temps de travail ?  Quels sont les droits des conducteurs en CDD en matière de sécurité et de conditions de travail ?  Comment RAPIDELIVERY doit-elle gérer les renouvellements de contrats pour les conducteurs en CDD ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:103', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'L’entreprise SMART MOVE, une SA, emploie des conducteurs en CDI et en CDD, certains à temps plein et d’autres à temps partiel, pour sa flotte de véhicules légers.  Quels sont les avantages et inconvénients des différents types de contrats (CDI, CDD, temps plein, temps partiel) pour SMART MOVE ?  Comment SMART MOVE doit-elle gérer les horaires de travail et les congés pour les conducteurs en temps partiel ? Page 190 sur 204  Quelles obligations SMART MOVE doit -elle respecter pour les conducteurs en CDI et en CDD ?  Comment SMART MOVE doit-elle organiser la formation pour les conducteurs sous différents types de contrats ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:104', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Qu’est-ce qu’une faute lourde en matière de licenciement ?  Quelles sont les étapes de la procédure de licenciement pour faute lourde ?  Quels sont les droits du salarié en cas de licenciement pour faute lourde ?  Quels recours le salarié peut-il exercer en cas de licenciement pour faute lourde ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:105', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Citer les 3 catégories de conducteurs  Selon l’article D. 3312-45 du code des transports, quelles sont les durées de temps de service hebdomadaire et trimestrielle pour chaque catégorie de conducteurs en précisant le nombre d’heures d’équivalence ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:106', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Citer les 3 catégories de conducteurs.  Selon les articles R. 3312 -50 et R. 3312 -51 du code des transports, et pour chaque catégorie de conducteurs :  quelles sont les durées de temps de service maximale hebdomadaire sur une semaine isolée ?  quelles sont les durées de temps de service maximale trimestrielle?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:107', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Qu’est-ce qu’ un travailleur de nuit ?  Définissez la période nocturne.  Quelle est la durée quotidienne maximale de travail de nuit pour le personnel roulant ?  Quelle est la durée moyenne maximale hebdomadaire par mois de travail de nuit pour un conducteur de longue distance ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:108', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Les heures supplémentaires deviennent fréquentes dans une société de transport léger de marchandises. Page 191 sur 204  Quelles sont les règles légales concernant le paiement des heures supplémen- taires ?  Comment l’entreprise peut-elle équilibrer les heures supplémentaires avec la charge de travail normale ?  Selon l’article R. 3312-48 du code des transports, déterminer le nombre de jours de compensation obligatoire en repos (ROC) par trimestre en fonction de nombre d’heures supplémentaires effectuées.', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:109', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un chauffeur de transport léger remarque que les freins de son véhicule ne fonctionnent plus correctement et qu''il y a un risque de panne mécanique imminente.  Que doit faire le chauffeur en constatant ce problème de sécurité ?  Peut-il refuser de conduire le véhicule sans être sanctionné ?  Quelles mesures l’employeur doit-il prendre après avoir été alerté ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:110', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un employé se sent épuisé après plusieurs heures de conduite sans pause et craint que continuer à travailler représente un risque pour sa sécurité sur la route.  Le salarié peut-il se retirer de son poste pour cause de fatigue ?  Quelle est la responsabilité de l''employeur en termes de gestion du temps de travail et des pauses ?  Comment l''employeur doit-il réagir si le salarié invoque son droit de retrait pour cause de fatigue ?', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:111', false) ON CONFLICT DO NOTHING;
