  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un autre conducteur ayant réalisé 110 H d’heures supplémentaires dans un quadrimestre obtient : a. 2 jours b. 2,5 jours c. 3 jours d. 3,5 jours', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:114', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Pour 80 H à 108 H d’heures supplémentaires dans un quadrimestre par un conducteur de messagerie, le nombre de jours de COR est : a. 1 jour b. 1,5 jour c. 2 jours d. 3 jours', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:115', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le document unique d''évaluation des risques professionnels doit être mis à jour : a. Tous les 5 ans b. Annuellement dans les entreprises de 11 salariés et plus c. Tous les 3 ans d. À chaque départ d''un salarié', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:116', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Les conducteurs doivent respecter les dispositions du document unique d''évaluation des risques : a. Seulement s''ils le souhaitent b. Tous les salariés de l''entreprise doivent le respecter c. Uniquement les managers d. Cela dépend de la taille de l''entreprise', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:117', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Les heures travaillées au-delà de 151,67 heures mensuelles pour les conducteurs sont considérées comme : a. Heures normales b. Heures supplémentaires c. Heures complémentaires d. Heures de récupération', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:118', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le taux de majoration pour les heures complémentaires au-delà de 1/10 de la durée de travail prévue est de : a. 10% b. 25% c. 20% d. 30% Page 193 sur 204', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:119', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Pour un salarié travaillant à temps partiel, le contrat de travail doit obligatoirement mentionner : a. La durée maximale de travail b. La durée de travail c. Le salaire brut d. Le type de contrat', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:120', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Les conducteurs de nuit ayant effectué au moins 50 heures de service pendant la nuit bénéficient d''un repos compensateur égal à : a. 10% du temps de service de nuit b. 5% du temps de service de nuit c. 15% du temps de service de nuit d. 20% du temps de service de nuit', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:121', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'L''employeur doit prendre des mesures pour : a. Augmenter les heures de travail b. Assurer la sécurité et protéger la santé des salariés c. Diminuer les congés payés d. Réduire le temps de travail', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:122', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Les indemnités de frais professionnels sont versées lorsque : a. Les salariés prennent leur repas à domicile b. Les salariés doivent prendre un repas ou découcher à l''extérieur c. Les salariés travaillent moins de 30 heures d. Les salariés sont en congé', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:123', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Le montant de l''indemnité de repas au 1er décembre 2023 est de : a. 10,00 € b. 15,96 € c. 12,50 € d. 18,00 €', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:124', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Les salariés travaillant le dimanche et effectuant moins de 3 heures de travail bénéficient d''une : a. Prime de nuit b. Indemnité forfaitaire c. Indemnité de repas d. Compensation financière Page 194 sur 204 Module F L’ENTREPRISE ET LA SÉCURITÉ', 4, 'moyen', ARRAY['module-e', 'salaries', 'capa-3-5t'], 'base-2026:qr:125', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Marie, employée dans un centre de distribution, doit superviser le chargement de plusieurs palettes dans un camion avant l''expédition. Elle doit aussi préparer les documents nécessaires.  Comment Marie doit-elle disposer les marchandises dans le camion ?  Quels sont les critères pour vérifier l''arrimage pendant le transport ?  Que doit-elle faire si des anomalies ou des incidents sont constatés lors du dé- chargement ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:126', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Ahmed doit livrer un chargement de meubles à un magasin. En arrivant, il remarque que la marchandise dépasse légèrement à l''arrière du camion.  Quelle est la réglementation concernant le dépassement de la charge à l''arrière du véhicule ?  Quels sont les risques liés au dépassement non signalé ?  Quelles mesures de sécurité doivent être prises pour éviter les problèmes liés au chargement ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:127', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Pierre, conducteur de camion, doit transporter des marchandises de valeur en utilisant un nouveau véhicule avec des équipements d’arrimage sophistiqués.  Quel est le rôle de l’arrimage couvrant dans le sécurisation du chargement ?  Pourquoi est-il important de vérifier régulièrement l’arrimage pendant le trajet ?  Quels équipements doivent être utilisés pour l’arrimage et pourquoi ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:128', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Kevin est en charge de l''arrimage des charges dans un camion avant une expédition internationale. Il doit utiliser différents types de matériel d’arrimage. Page 195 sur 204  Quel type d’arrimage est recommandé pour prévenir les rebonds et le glissement des charges ?  Pourquoi est-il important d’adapter les moyens d’arrimage en fonction de la na- ture de la charge ?  Que doit faire Kevin pour s’assurer que l’arrimage est efficace et sûr ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:129', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Émilie est responsable de la gestion du transport de produits alimentaires périssables, y compris des viandes et des produits laitiers. Elle doit préparer un camion pour une livraison à une chaîne de supermarchés, en s''assurant que le véhicule et le chargement respectent les normes de sécurité et de température.  Quels contrôles Émilie doit-elle effectuer sur le véhicule avant le départ pour as- surer le respect des normes de température pour les denrées périssables ?  Quelles sont les exigences pour l''étiquetage et la documentation des produits périssables dans le contexte du transport ?  Que doit-elle faire si la température dans le camion dépasse la température de conservation recommandée pendant le transport ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:130', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Lucas est conducteur de camion et doit transporter des produits chimiques dangereux classifiés comme matières inflammables. Avant de commencer son trajet, il doit vérifier que tous les documents et équipements nécessaires sont en place.  Quels documents et équipements Lucas doit-il s’assurer d’avoir à bord avant de transporter des matières dangereuses ?  Comment les matières dangereuses doivent-elles être étiquetées et marquées sur le camion ?  Que doit faire Lucas si un incident se produit pendant le transport qui pourrait compromettre la sécurité des matières dangereuses ? Page 196 sur 204', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:131', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Marc est chargé de vérifier les véhicules de transport pour s’assurer qu’ils respectent les normes ATP avant leur utilisation pour le transport de produits alimentaires.  Quels critères doivent être vérifiés pour s''assurer qu''un véhicule est conforme aux spécifications ATP ?  Que faire si le véhicule ne répond pas aux exigences ATP lors de l''inspection ?  Quels documents Marc doit-il vérifier pour s''assurer que le véhicule est correcte- ment homologué pour le transport des denrées périssables ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:132', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Alice, conductrice d’un véhicule de livraison, a eu un accident après que les freins de son véhicule ont échoué. L''entretien régulier a été négligé pendant plusieurs mois.  Quelles sont les obligations légales de l''employeur concernant l''entretien des vé- hicules de transport léger pour prévenir ce type d''accident ?  Comment Alice doit-elle signaler l''accident et quelles démarches doivent être entreprises pour faire reconnaître la faute ?  Quel est le rôle du carnet d''entretien du véhicule dans la prévention des acci- dents dus à des défaillances mécaniques ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:133', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Thomas, un chauffeur de camionnette, se blesse en manipulant des charges lourdes sans utiliser les équipements de protection fournis.  Quelles sont les responsabilités de l''employeur pour garantir que les conducteurs utilisent correctement les équipements de protection ?  Comment Thomas peut-il démontrer que la blessure est due à une négligence dans l''utilisation des équipements de protection ?  Quels types de formations doivent être proposées aux conducteurs pour éviter des blessures liées à la manipulation de charges lourdes ? Page 197 sur 204', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:134', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Claire, conductrice de camionnette, jette des emballages et des déchets de livraison dans des conteneurs non appropriés, créant des problèmes de gestion des déchets.  Quelles sont les obligations légales concernant la gestion des déchets produits par les activités de livraison ?  Comment Claire peut-elle être sensibilisée à la gestion correcte des déchets et à l''impact environnemental ?  Quels sont les protocoles à suivre pour assurer une gestion appropriée des dé- chets issus des activités de livraison ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:135', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'L’entreprise de transport de David est critiquée pour sa gestion inappropriée des déchets générés lors de la maintenance des véhicules, entraînant des problèmes environnementaux locaux.  Quels sont les principes de base pour une gestion appropriée des déchets dans le secteur du transport ?  Quels sont les impacts négatifs d''une gestion inadéquate des déchets sur l''environnement et la communauté locale ?  Comment l’entreprise peut-elle améliorer sa gestion des déchets pour minimiser son impact environnemental ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:136', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Une entreprise de transport a récemment été accusée de polluer l''air en raison d''un entretien insuffisant des véhicules et d''une mauvaise gestion des déchets.  Quelles sont les obligations de l''entreprise en matière de gestion des émissions polluantes et de gestion des déchets dangereux ?  Quel impact les actions de cette entreprise peuvent-elles avoir sur l’environne- ment et la réputation de l’entreprise ?  Quelles actions l’entreprise peut-elle entreprendre pour réduire son impact envi- ronnemental et améliorer sa conformité réglementaire ? Page 198 sur 204', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:137', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Qu''est-ce que le permis de conduire à points ?  Quand ce système a-t-il été mis en place en France ?  Combien de points dispose un conducteur après la période probatoire ?  Comment les points peuvent-ils être retirés ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:138', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', ' Quelles infractions entraînent un retrait de points sur le permis de conduire ?  Quelle est la sanction pour un excès de vitesse de plus de 20 km/h ?  Quels comportements au volant entraînent le retrait le plus sévère de points ?  Est-il possible de perdre plus de 8 points à la suite d’une seule infraction ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:139', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Quels sont les moyens pour un employeur de vérifier que ses salariés ont un permis valide ?  Quelle est l’obligation légale de l’employeur en matière de vérification du permis ?  Quelles procédures l’employeur peut-il mettre en place pour vérifier la validité des permis ?  Que doit faire un salarié en cas de suspension de son permis ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:140', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Quels sont les risques encourus par un employeur si un salarié conduit sans permis valide ?  Qui est responsable en cas d''accident si un salarié conduit sans permis valide ?  Comment l’assurance de l’employeur réagit-elle dans ce cas ?  Quelles conséquences financières l’entreprise peut-elle subir en cas d’accident grave causé par un salarié sans permis ? Page 199 sur 204', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:141', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Quels sont les effets d''une suspension du permis de conduire sur le contrat de travail ?  La suspension du permis peut-elle entraîner un licenciement ?  Quelles sont les obligations du salarié vis-à-vis de l’employeur en cas de perte de permis ?  Dans quels cas l’employeur peut-il envisager un licenciement pour suspension de permis ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:142', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un salarié cause un accident avec un véhicule professionnel et son employeur découvre qu''il conduisait sans permis.  Que risque le salarié pour conduite sans permis ?  Quelle est la responsabilité de l''employeur ?  Quelles actions peut entreprendre l''employeur pour éviter cette situation ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:143', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un jeune conducteur sous contrat d’apprentissage conduit sous l’emprise de l’alcool et est arrêté par la police.  Quelles sont les sanctions spécifiques pour un jeune conducteur en état d’al- coolémie ?  Quelles conséquences pour son emploi s’il est chauffeur professionnel ?  Que peut faire l''employeur pour éviter ces situations ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:144', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un conducteur salarié est responsable d’un accident alors qu’il est en période probatoire de son permis.  Quelles sont les conséquences d’un accident pour un conducteur en période probatoire ?  Comment cela affecte-t-il son emploi s''il est chauffeur professionnel ?  Que peut faire l’employeur pour réduire ces risques ? Page 200 sur 204', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:145', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Choix du véhicule pour une entreprise de transport de marchandises  Quels sont les critères à prendre en compte pour choisir un véhicule de transport de marchandises ?  Quelles sont les différences entre les catégories de véhicules N1, N2, et N3 ?  Comment le choix d’un véhicule peut-il impacter l’image de l’entreprise ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:146', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un salarié est arrêté lors d’un contrôle de police avec un véhicule utilitaire sans équipement obligatoire.  Quels sont les équipements obligatoires à bord d’un véhicule utilitaire ?  Pourquoi est-il conseillé d''avoir un constat amiable accident et une trousse de premiers secours à bord ?  Que risque un conducteur si son véhicule n''est pas équipé des éléments de sécurité obligatoires ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:147', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un conducteur professionnel oublie de faire le contrôle technique de son camionnette.  Quelle est la fréquence du contrôle technique pour les véhicules utilitaires légers ?  Quelles sont les sanctions en cas de défaut de contrôle technique ?  Pourquoi est-il crucial de réaliser une visite antipollution annuelle ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:148', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un employeur décide d’aménager un véhicule utilitaire pour transporter des marchandises volumineuses.  Quels aménagements intérieurs peuvent contribuer à la sécurité du conducteur lors du transport ?  Quelle est l’importance d’une cloison de séparation dans un véhicule utilitaire ?  Quels systèmes d’arrimage sont conseillés pour sécuriser les marchandises ? Page 201 sur 204', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:149', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un transporteur change les pneumatiques de son véhicule sans respecter les normes de sécurité.  Quels critères faut-il prendre en compte lors du choix des pneumatiques ?  Quelle est la profondeur minimale des rainures des pneumatiques pour un usage légal ?  Que peut-il se passer si un véhicule roule avec des pneumatiques inadaptés ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:150', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Jean, conducteur de camion, reçoit une mission pour transporter des matériaux de construction d''un entrepôt à un chantier. Avant de commencer le chargement, il doit vérifier l''état du véhicule et préparer le chargement.  Avant de commencer le chargement, que doit vérifier Jean concernant le véhicule ?  Quels éléments doit-il déterminer pour sécuriser correctement le chargement ?  Quel est le risque de ne pas respecter les protocoles de sécurité pour le chargement ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:151', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Une société de transport doit se conformer à des normes environnementales.  Quelles sont les principales réglementations à respecter dans ce secteur ?  Quels risques l''entreprise encourt-elle en cas de non-conformité ?  Comment l''entreprise peut-elle s''assurer de sa conformité en continu ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:152', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un transporteur veut mettre en place une politique de RSE.  Quels éléments doivent être intégrés dans cette politique ?  Comment cette politique peut-elle être communiquée aux clients et partenaires ?  Quels bénéfices à long terme peut-elle apporter à l''entreprise ? Page 202 sur 204', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:153', false) ON CONFLICT DO NOTHING;
  INSERT INTO public.question_bank (formation_id, type, statement, max_score, difficulty, tags, source_ref, active) VALUES (formation_uuid, 'qr', 'Un conducteur de transport participe à un stage de sensibilisation à l''environnement.  Quels sujets seront abordés lors de ce stage ?  Comment cette formation peut-elle influencer ses pratiques quotidiennes ?  Quelles certifications peuvent être obtenues à l''issue de ce stage ?', 4, 'moyen', ARRAY['module-f', 'securite', 'capa-3-5t'], 'base-2026:qr:154', false) ON CONFLICT DO NOTHING;
