-- Récupère l'UUID de la formation
DO $$
DECLARE
  formation_uuid uuid;
BEGIN
  SELECT id INTO formation_uuid FROM public.formations WHERE slug = 'capacite-3-5t';
  IF formation_uuid IS NULL THEN
    RAISE EXCEPTION 'Formation capacite-3-5t introuvable. Lancez d''abord formations_v2.sql.';
  END IF;

